package org.apache.flink.core.fs;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.configuration.CoreOptions;
import org.apache.flink.configuration.IllegalConfigurationException;
import org.apache.flink.core.fs.FileSystem.WriteMode;
import org.apache.flink.core.fs.local.LocalFileSystem;
import org.apache.flink.core.plugin.MetricsAware;
import org.apache.flink.core.plugin.PluginManager;
import org.apache.flink.metrics.MetricGroup;
import org.apache.flink.metrics.groups.UnregisteredMetricsGroup;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.File;
import java.io.IOException;
import java.net.URI;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for the process-wide behavior exposed by {@link FileSystem}. */
class FileSystemTests {

    private static final String PLUGIN_SCHEME = "flink-test-fs";

    @TempDir File temporaryDirectory;

    @BeforeEach
    void initializeFileSystems() {
        FileSystem.initialize(new Configuration());
    }

    @AfterEach
    void restoreFileSystems() {
        FileSystem.initialize(new Configuration());
    }

    // ------------------------------------------------------------------------
    //  File system keys
    // ------------------------------------------------------------------------

    @Test
    void testFsKeyUsesSchemeAndAuthorityForIdentity() {
        FileSystem.FSKey key = new FileSystem.FSKey("hdfs", "namenode:8020");
        FileSystem.FSKey equalKey = new FileSystem.FSKey(URI.create("hdfs://namenode:8020/a/path"));

        assertThat(equalKey).isEqualTo(key);
        assertThat(equalKey.hashCode()).isEqualTo(key.hashCode());
        assertThat(key).isNotEqualTo(new FileSystem.FSKey("hdfs", "other:8020"));
        assertThat(key).isNotEqualTo(new FileSystem.FSKey("s3", "namenode:8020"));
        assertThat(key).isNotEqualTo("hdfs://namenode:8020");
        assertThat(key.toString()).isEqualTo("hdfs://namenode:8020");
    }

    @Test
    void testFsKeyHandlesMissingAuthorities() {
        FileSystem.FSKey fileKey = new FileSystem.FSKey(URI.create("file:/tmp/example"));
        FileSystem.FSKey anotherFileKey = new FileSystem.FSKey("file", null);

        assertThat(fileKey).isEqualTo(anotherFileKey);
        assertThat(fileKey.hashCode()).isEqualTo(anotherFileKey.hashCode());
        assertThat(fileKey).isNotEqualTo(new FileSystem.FSKey("file", "localhost"));
        assertThat(fileKey.toString()).isEqualTo("file://");
    }

    // ------------------------------------------------------------------------
    //  Initialization and default file system
    // ------------------------------------------------------------------------

    @Test
    void testDefaultFileSystemFallsBackToLocalFileSystem() {
        assertThat(FileSystem.getDefaultFsUri()).isEqualTo(LocalFileSystem.getLocalFsURI());
    }

    @Test
    void testConfiguredDefaultFileSystemIsExposed() {
        URI defaultUri = URI.create("flink-test-fs://master:1234/base");
        Configuration configuration = new Configuration();
        configuration.set(CoreOptions.DEFAULT_FILESYSTEM_SCHEME, defaultUri.toString());

        FileSystem.initialize(configuration);

        assertThat(FileSystem.getDefaultFsUri()).isEqualTo(defaultUri);
    }

    @Test
    void testInvalidDefaultFileSystemUriIsRejected() {
        Configuration configuration = new Configuration();
        String invalidUri = "bad uri with spaces";
        configuration.set(CoreOptions.DEFAULT_FILESYSTEM_SCHEME, invalidUri);

        assertThatThrownBy(() -> FileSystem.initialize(configuration))
                .isInstanceOf(IllegalConfigurationException.class)
                .hasMessageContaining("fs.default-scheme")
                .hasMessageContaining(invalidUri);
    }

    @Test
    void testSchemalessUriIsRewrittenUsingConfiguredDefaultFileSystem() throws Exception {
        URI defaultUri = URI.create("flink-test-fs://default-host:9876/base");
        Configuration configuration = new Configuration();
        configuration.set(CoreOptions.DEFAULT_FILESYSTEM_SCHEME, defaultUri.toString());
        RecordingFileSystemFactory factory = new RecordingFileSystemFactory(PLUGIN_SCHEME, 0);
        FileSystem.initialize(configuration, new TestingPluginManager(factory));

        FileSystem fileSystem = FileSystem.getUnguardedFileSystem(new URI("/relative/path"));

        assertThat(fileSystem).isNotNull();
        assertThat(factory.createdUris)
                .containsExactly(URI.create("flink-test-fs://default-host:9876/relative/path"));
    }

    // ------------------------------------------------------------------------
    //  Obtaining file systems
    // ------------------------------------------------------------------------

    @Test
    void testLocalFileSystemIsCachedBySchemeAndAuthority() throws Exception {
        FileSystem first = FileSystem.getUnguardedFileSystem(URI.create("file:/tmp/first"));
        FileSystem second = FileSystem.getUnguardedFileSystem(URI.create("file:///tmp/second"));

        assertThat(first).isSameAs(LocalFileSystem.getSharedInstance());
        assertThat(second).isSameAs(first);
        assertThat(FileSystem.getLocalFileSystem()).isSameAs(first);
    }

    @Test
    void testMalformedLocalFileSystemUriIsRejectedWithHint() {
        URI malformedUri = URI.create("file://tmp/example");

        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(malformedUri))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("authority 'tmp'")
                .hasMessageContaining("file:///tmp/example");
    }

    @Test
    void testNullFileSystemUriIsRejected() {
        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("file system URI");
    }

    @Test
    void testDirectlySupportedSchemeWithoutPluginIsRejected() {
        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(URI.create("s3://bucket/key")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("scheme 's3'")
                .hasMessageContaining("flink-s3-fs-hadoop")
                .hasMessageContaining("flink-s3-fs-presto")
                .hasMessageContaining("flink-s3-fs-native")
                .hasMessageContaining("fs.allowed-fallback-filesystems");
    }

    @Test
    void testUnknownSchemeWithoutAvailableFallbackIsRejected() {
        assertThatThrownBy(
                        () ->
                                FileSystem.getUnguardedFileSystem(
                                        URI.create("unknown-flink-scheme://host/path")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("scheme 'unknown-flink-scheme'")
                .hasMessageContaining("not directly supported by Flink");
    }

    @Test
    void testAllowedFallbackStillReportsMissingFileSystemPlugin() {
        Configuration configuration = new Configuration();
        configuration.set(CoreOptions.ALLOWED_FALLBACK_FILESYSTEMS, "s3; wasb");
        FileSystem.initialize(configuration);

        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(URI.create("s3://bucket/key")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("No file system to support this scheme could be loaded")
                .hasMessageContaining("flink-s3-fs-hadoop");
    }

    @Test
    void testCreatedFileSystemsAreCachedAndCacheIsClearedOnInitialization() throws Exception {
        RecordingFileSystemFactory factory = new RecordingFileSystemFactory(PLUGIN_SCHEME, 0);
        FileSystem.initialize(new Configuration(), new TestingPluginManager(factory));

        FileSystem first =
                FileSystem.getUnguardedFileSystem(URI.create(PLUGIN_SCHEME + "://host/first"));
        FileSystem firstOtherPath =
                FileSystem.getUnguardedFileSystem(URI.create(PLUGIN_SCHEME + "://host/second"));
        FileSystem otherAuthority =
                FileSystem.getUnguardedFileSystem(URI.create(PLUGIN_SCHEME + "://other/first"));

        assertThat(firstOtherPath).isSameAs(first);
        assertThat(otherAuthority).isNotSameAs(first);
