        assertThat(fileSystem.lastWriteMode).isEqualTo(WriteMode.OVERWRITE);

        assertThat(fileSystem.create(path, false)).isNull();
        assertThat(fileSystem.lastWriteMode).isEqualTo(WriteMode.NO_OVERWRITE);
    }

    @Test
    void testDeprecatedCreateMapsOnlyOverwriteFlagToWriteMode() throws Exception {
        WriteModeRecordingFileSystem fileSystem = new WriteModeRecordingFileSystem();
        Path path = new Path("file:///tmp/ignored");

        assertThat(fileSystem.create(path, true, 128, (short) 3, 1024L)).isNull();
        assertThat(fileSystem.lastWriteMode).isEqualTo(WriteMode.OVERWRITE);

        assertThat(fileSystem.create(path, false, 128, (short) 3, 1024L)).isNull();
        assertThat(fileSystem.lastWriteMode).isEqualTo(WriteMode.NO_OVERWRITE);
    }

    @Test
    void testDefaultBlockSize() {
        assertThat(new WriteModeRecordingFileSystem().getDefaultBlockSize())
                .isEqualTo(32L * 1024 * 1024);
    }

    @Test
    void testRecoverableWriterConfigurationOverloadsDelegateToDefaultMethod() throws Exception {
        FileSystem fileSystem = FileSystem.getLocalFileSystem();

        assertThat(fileSystem.createRecoverableWriter()).isNotNull();
        assertThat(fileSystem.createRecoverableWriter(null)).isNotNull();
        assertThat(fileSystem.createRecoverableWriter(Collections.emptyMap())).isNotNull();
        assertThat(fileSystem.createRecoverableWriter(Map.of("key", "value"))).isNotNull();
    }

    // ------------------------------------------------------------------------
    //  Local output path initialization
    // ------------------------------------------------------------------------

    @Test
    void testLocalInitCreatesMissingOutputDirectory() throws Exception {
        File outputDirectory = file("local-output");

        boolean initialized =
                FileSystem.getLocalFileSystem()
                        .initOutPathLocalFS(
                                Path.fromLocalFile(outputDirectory), WriteMode.NO_OVERWRITE, true);

        assertThat(initialized).isTrue();
        assertThat(outputDirectory).isDirectory();
