    @Test
    void testLocalInitAcceptsExistingOutputDirectoryInNoOverwriteMode() throws Exception {
        File outputDirectory = directory("existing-local-output");
        File marker = new File(outputDirectory, "marker");
        assertThat(marker.createNewFile()).isTrue();

        boolean initialized =
                FileSystem.getLocalFileSystem()
                        .initOutPathLocalFS(
                                Path.fromLocalFile(outputDirectory), WriteMode.NO_OVERWRITE, true);

        assertThat(initialized).isTrue();
