                                FileSystem.getLocalFileSystem()
                                        .initOutPathLocalFS(
                                                Path.fromLocalFile(outputFile),
                                                WriteMode.NO_OVERWRITE,
                                                false))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("already exists")
                .hasMessageContaining("NO_OVERWRITE");

        assertThat(outputFile).isFile();
    }

    @Test
    void testLocalInitOverwritesExistingFileWithOutputDirectory() throws Exception {
        File outputPath = file("local-overwrite-file");
        assertThat(outputPath.createNewFile()).isTrue();

        boolean initialized =
                FileSystem.getLocalFileSystem()
                        .initOutPathLocalFS(
                                Path.fromLocalFile(outputPath), WriteMode.OVERWRITE, true);

        assertThat(initialized).isTrue();
        assertThat(outputPath).isDirectory();
    }

    @Test
    void testLocalInitOverwritesExistingDirectoryForSingleOutputFile() throws Exception {
        File outputPath = directory("local-overwrite-directory");
        File nestedFile = new File(outputPath, "nested");
        assertThat(nestedFile.createNewFile()).isTrue();

        boolean initialized =
                FileSystem.getLocalFileSystem()
                        .initOutPathLocalFS(
                                Path.fromLocalFile(outputPath), WriteMode.OVERWRITE, false);

        assertThat(initialized).isTrue();
        assertThat(outputPath).doesNotExist();
