    @Test
    void testLocalInitAcceptsMissingSingleOutputFile() throws Exception {
        File outputPath = file("missing-local-output-file");

        boolean initialized =
                FileSystem.getLocalFileSystem()
                        .initOutPathLocalFS(
                                Path.fromLocalFile(outputPath), WriteMode.NO_OVERWRITE, false);

