        File outputPath = file("not-created-by-local-init");

        assertThat(
                        distributedFileSystem.initOutPathLocalFS(
                                Path.fromLocalFile(outputPath), WriteMode.NO_OVERWRITE, true))
                .isFalse();
        assertThat(outputPath).doesNotExist();
