    // ------------------------------------------------------------------------
    //  Distributed output path initialization
    // ------------------------------------------------------------------------

    @Test
    void testDistInitCreatesMissingOutputDirectory() throws Exception {
        DistributedLocalFileSystem fileSystem = new DistributedLocalFileSystem();
        File outputDirectory = file("dist-output");

        boolean initialized =
                fileSystem.initOutPathDistFS(
                        Path.fromLocalFile(outputDirectory), WriteMode.NO_OVERWRITE, true);

        assertThat(initialized).isTrue();
        assertThat(outputDirectory).isDirectory();
