    @Test
    void getAllDeclaredFieldsCollectsHierarchyAndSkipsStaticAndTransientFields() {
        List<Field> fields = TypeExtractor.getAllDeclaredFields(ChildPojo.class, false);
        assertThat(fields)
                .extracting(Field::getName)
                .containsExactlyInAnyOrder("child", "parent", "visible");
        assertThat(fields).noneMatch(field -> field.getName().equals("STATIC"));
        assertThat(fields).noneMatch(field -> field.getName().equals("transientField"));
    }

    @Test
    void getAllDeclaredFieldsRejectsDuplicateNamesUnlessIgnoringThem() {
        assertThatThrownBy(() -> TypeExtractor.getAllDeclaredFields(DuplicateChild.class, false))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("already contained");
        assertThatThrownBy(() -> TypeExtractor.getAllDeclaredFields(DuplicateChild.class, false))
                .hasMessageContaining("unique field names");

        List<Field> fields = TypeExtractor.getAllDeclaredFields(DuplicateChild.class, true);
        assertThat(fields).hasSize(1);
        assertThat(fields.get(0).getName()).isEqualTo("value");
        assertThat(fields.get(0).getDeclaringClass()).isEqualTo(DuplicateChild.class);
    }

    @Test
    void getDeclaredFieldFindsInheritedAndMissingFields() {
        Field parent = TypeExtractor.getDeclaredField(ChildPojo.class, "parent");
        assertThat(parent).isNotNull();
        assertThat(parent.getDeclaringClass()).isEqualTo(ParentPojo.class);

        assertThat(TypeExtractor.getDeclaredField(ChildPojo.class, "doesNotExist")).isNull();
    }

    @Test
    void isRecordReturnsFalseForOrdinaryClasses() {
        assertThat(TypeExtractor.isRecord(PublicPojo.class)).isFalse();
        assertThat(TypeExtractor.isRecord(String.class)).isFalse();
        assertThat(TypeExtractor.isRecord(Object.class)).isFalse();
    }

    @Test
    void getForObjectExtractsTupleAndRowFields() {
        TypeInformation<Tuple2<String, Integer>> tupleInfo =
                TypeExtractor.getForObject(new Tuple2<>("hello", 42));
        assertThat(tupleInfo).isInstanceOf(TupleTypeInfo.class);
        assertThat(tupleInfo.getTypeClass()).isEqualTo(Tuple2.class);
        assertThat(tupleInfo.getArity()).isEqualTo(2);
        assertThat(((TupleTypeInfo<?>) tupleInfo).getTypeAt(0))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(((TupleTypeInfo<?>) tupleInfo).getTypeAt(1))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);

        TypeInformation<Row> rowInfo = TypeExtractor.getForObject(Row.of("hello", 42L));
        assertThat(rowInfo).isInstanceOf(RowTypeInfo.class);
        assertThat(rowInfo.getTypeClass()).isEqualTo(Row.class);
        assertThat(rowInfo.getArity()).isEqualTo(2);
        assertThat(((RowTypeInfo) rowInfo).getTypeAt(0))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(((RowTypeInfo) rowInfo).getTypeAt(1))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
    }

    @Test
    void getForObjectRejectsNullTuplesAndNullObjects() {
        assertThatThrownBy(() -> TypeExtractor.getForObject(null))
                .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> TypeExtractor.getForObject(new Tuple2<>(null, 1)))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("null values");
    }

    @Test
    void getForObjectUsesRuntimeClassForPojoAndAnnotations() {
        assertThat(TypeExtractor.getForObject(new PublicPojo("a", 1, Arrays.asList("x"))))
                .isInstanceOf(PojoTypeInfo.class);

        TypeInformation<AnnotatedPojo> annotated =
                TypeExtractor.getForObject(new AnnotatedPojo());
        assertThat(annotated).isInstanceOf(GenericTypeInfo.class);
        assertThat(annotated.getTypeClass()).isEqualTo(AnnotatedPojo.class);
    }

    @Test
    void rejectsNullTypes() {
        assertThatThrownBy(() -> TypeExtractor.createTypeInfo((Type) null))
                .isInstanceOf(InvalidTypesException.class);
        assertThatThrownBy(() -> TypeExtractor.createTypeInfo((Class<?>) null))
                .isInstanceOf(InvalidTypesException.class);
        assertThatThrownBy(() -> TypeExtractor.getForClass(null))
                .isInstanceOf(NullPointerException.class);
    }

