    public static class StringToIntegerMap implements MapFunction<String, Integer> {
        @Override
        public Integer map(String value) {
            return value.length();
        }
    }

    public static class StringToLongFlatMap implements FlatMapFunction<String, Long> {
        @Override
        public void flatMap(String value, Collector<Long> out) {
            out.collect((long) value.length());
        }
    }

    public static class StringToDoubleMapPartition
            implements MapPartitionFunction<String, Double> {
        @Override
        public void mapPartition(Iterable<String> values, Collector<Double> out) {
            for (String value : values) {
                out.collect((double) value.length());
            }
        }
    }

    public static class StringToFloatGroupReduce
            implements GroupReduceFunction<String, Float> {
        @Override
        public void reduce(Iterable<String> values, Collector<Float> out) {
            out.collect(1.0f);
        }
    }

    public static class StringToByteGroupCombine implements GroupCombineFunction<String, Byte> {
        @Override
        public void combine(Iterable<String> values, Collector<Byte> out) {
            out.collect((byte) 1);
        }
    }

    public static class SumAggregate implements AggregateFunction<Integer, Long, Double> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(Integer value, Long accumulator) {
            return accumulator + value;
        }

        @Override
        public Double getResult(Long accumulator) {
            return accumulator.doubleValue();
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

