            implements CoGroupFunction<String, Integer, Float> {
        @Override
        public void coGroup(
                Iterable<String> first, Iterable<Integer> second, Collector<Float> out) {
            out.collect(1.0f);
        }
    }

    public static class StringIntegerToShortCross
            implements CrossFunction<String, Integer, Short> {
        @Override
