import org.apache.flink.types.Record;
import org.apache.flink.types.IntValue;
import org.apache.flink.types.StringValue;
import org.apache.flink.types.ByteValue;
import org.apache.flink.core.memory.*;
import java.io.*;
import java.util.Arrays;

public class Explore2 {
    static void p(Object o) { System.out.println(o); }
    static Record copyViaSerialize(Record r) throws Exception {
        DataOutputSerializer out = new DataOutputSerializer(1024);
        r.write(out);
        Record t = new Record();
        t.read(new DataInputDeserializer(out.getCopyOfBuffer()));
        return t;
    }
    static String dump(Record r) throws Exception {
        StringBuilder sb = new StringBuilder("nf=" + r.getNumFields() + " [");
        for (int i = 0; i < r.getNumFields(); i++) {
            if (r.isNull(i)) sb.append("null");
            else sb.append(r.getField(i, IntValue.class).getValue());
            sb.append(",");
        }
        return sb.append("]").toString();
    }
    public static void main(String[] args) throws Exception {
        // copy(DataInputView, DataOutputView)
        Record src = new Record(2);
        src.setField(0, new IntValue(11));
        src.setField(1, new StringValue("hello"));
        DataOutputSerializer o5 = new DataOutputSerializer(1024);
        src.write(o5);
        DataInputDeserializer in5 = new DataInputDeserializer(o5.getCopyOfBuffer());
        DataOutputSerializer o6 = new DataOutputSerializer(1024);
        Record tmp = new Record();
        tmp.copy(in5, o6);
        p("copy() out len " + o6.length() + " vs " + o5.length());
        Record fromCopy = new Record();
        fromCopy.read(new DataInputDeserializer(o6.getCopyOfBuffer()));
        p("from copy: nf=" + fromCopy.getNumFields() + " f0=" + fromCopy.getField(0, IntValue.class) + " f1=" + fromCopy.getField(1, StringValue.class));

        // setNumFields negative
        Record neg = new Record(2);
        neg.setNumFields(-1);
        p("neg numFields=" + neg.getNumFields());

        // union general case: this binary, other modified
        Record a = new Record(2);
        a.setField(0, new IntValue(1));
        a.setField(1, new IntValue(2));
        a.updateBinaryRepresenation();
        Record b = new Record(3);
        b.setField(0, new IntValue(7));
        b.setField(1, null);
        b.setField(2, new IntValue(9));
        Record c = copyViaSerialize(a);
        c.unionFields(b);
        p("union general(binary+modified): " + dump(c));

        // union where this modified, other binary
        Record d = new Record(3);
        d.setField(0, null);
        d.setField(1, new IntValue(5));
        d.setField(2, new IntValue(6));
        Record e = copyViaSerialize(a);
        d.unionFields(e);
        p("union general(modified + binary): " + dump(d));

        // union both binary, other longer with nulls
        Record f = new Record(2);
        f.setField(0, null);
        f.setField(1, null);
