package org.apache.flink.types;

import org.apache.flink.core.memory.DataInputDeserializer;
import org.apache.flink.core.memory.DataOutputSerializer;
import org.apache.flink.util.InstantiationUtil;

import org.junit.jupiter.api.Test;

import java.io.EOFException;
import java.io.IOException;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link Record}, covering construction, field access, sparse (null) field handling,
 * record modification, record combination ({@link Record#unionFields(Record)},
 * {@link Record#copyTo(Record)}, {@link Record#copyFrom(Record, int[], int[])}) and the binary
 * (de)serialization contract.
 */
class RecordTests {

    // --------------------------------------------------------------------------------------------
    //  Test utilities
    // --------------------------------------------------------------------------------------------

    /** Serializes the given record into a fresh output view. */
    private static DataOutputSerializer write(Record record) throws IOException {
        final DataOutputSerializer out = new DataOutputSerializer(1024);
        record.write(out);
        return out;
    }

    /** Serializes the given record and reads it back into a new record instance. */
    private static Record roundTrip(Record record) throws IOException {
        final DataOutputSerializer out = write(record);
        final Record copy = new Record();
        copy.read(new DataInputDeserializer(out.getCopyOfBuffer()));
        return copy;
    }

    /** Creates a record with the given {@link IntValue} fields; {@code null} entries stay null. */
    private static Record intRecord(Integer... values) {
        final Record record = new Record();
        for (int i = 0; i < values.length; i++) {
            record.setField(i, values[i] == null ? null : new IntValue(values[i]));
        }
        return record;
    }

    /** Checks the number of fields and the (possibly null) {@link IntValue} content of a record. */
    private static void assertIntFields(Record record, Integer... expected) {
        assertEquals(expected.length, record.getNumFields(), "number of fields");
        for (int i = 0; i < expected.length; i++) {
            if (expected[i] == null) {
                assertTrue(record.isNull(i), "field " + i + " should be null");
                assertNull(record.getField(i, IntValue.class), "field " + i + " should read as null");
            } else {
                assertFalse(record.isNull(i), "field " + i + " should not be null");
                assertEquals(
                        expected[i].intValue(),
                        record.getField(i, IntValue.class).getValue(),
                        "value of field " + i);
            }
        }
    }

    // --------------------------------------------------------------------------------------------
    //  Construction and number of fields
    // --------------------------------------------------------------------------------------------

    @Test
    void testEmptyRecordHasNoFields() {
        final Record record = new Record();

        assertEquals(0, record.getNumFields());
        // records are of variable length
        assertEquals(-1, record.getBinaryLength());

        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(0, IntValue.class));
        assertThrows(IndexOutOfBoundsException.class, () -> record.removeField(0));
    }

    @Test
    void testSingleValueConstructor() {
        final Record record = new Record(new IntValue(42));

        assertEquals(1, record.getNumFields());
        assertFalse(record.isNull(0));
        assertEquals(42, record.getField(0, IntValue.class).getValue());
    }

    @Test
    void testSingleValueConstructorWithNullValue() {
        final Record record = new Record((Value) null);

        assertEquals(1, record.getNumFields());
        assertTrue(record.isNull(0));
        assertNull(record.getField(0, IntValue.class));
    }

    @Test
    void testTwoValueConstructor() {
        final Record record = new Record(new IntValue(1), new StringValue("abc"));

        assertEquals(2, record.getNumFields());
        assertEquals(1, record.getField(0, IntValue.class).getValue());
        assertEquals("abc", record.getField(1, StringValue.class).getValue());
    }

    @Test
    void testTwoValueConstructorWithNullField() {
        final Record record = new Record(null, new IntValue(2));

        assertEquals(2, record.getNumFields());
        assertTrue(record.isNull(0));
        assertEquals(2, record.getField(1, IntValue.class).getValue());
    }

    @Test
    void testNumFieldsConstructorCreatesNullFields() {
        final Record record = new Record(4);

        assertEquals(4, record.getNumFields());
        for (int i = 0; i < 4; i++) {
            assertTrue(record.isNull(i), "field " + i + " should be null");
            assertNull(record.getField(i, IntValue.class));
        }
    }

    @Test
    void testMakeSpaceDoesNotChangeTheNumberOfFields() {
        final Record record = new Record();

        record.makeSpace(8);
        assertEquals(0, record.getNumFields());

        record.setField(0, new IntValue(5));
        assertEquals(1, record.getNumFields());
        assertEquals(5, record.getField(0, IntValue.class).getValue());
    }

    @Test
    void testSetNumFieldsExpandsWithNullFields() {
        final Record record = new Record(new IntValue(7));

        record.setNumFields(3);

        assertIntFields(record, 7, null, null);
    }

    @Test
    void testSetNumFieldsTruncatesTrailingFields() throws IOException {
        final Record record = intRecord(1, 2, 3);
        record.updateBinaryRepresenation();

        record.setNumFields(2);

        assertIntFields(record, 1, 2);
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(2));
        // the truncated field must not reappear in the serialized form
        assertIntFields(roundTrip(record), 1, 2);
    }

    @Test
    void testSetNumFieldsToZeroKeepsRecordReusable() {
        final Record record = intRecord(1, 2);

        record.setNumFields(0);
        assertEquals(0, record.getNumFields());

        record.setField(0, new IntValue(9));
        assertIntFields(record, 9);
    }

    // --------------------------------------------------------------------------------------------
    //  Setting fields
    // --------------------------------------------------------------------------------------------

    @Test
    void testSetFieldExpandsRecordSparsely() throws IOException {
        final Record record = new Record();

        record.setField(4, new IntValue(5));

        assertIntFields(record, null, null, null, null, 5);
        assertIntFields(roundTrip(record), null, null, null, null, 5);
    }

    @Test
    void testSetFieldWithNullValueMarksFieldAsNull() {
        final Record record = new Record(1);
        record.setField(0, new IntValue(3));

        record.setField(0, null);

        assertTrue(record.isNull(0));
        assertNull(record.getField(0, IntValue.class));
    }

    @Test
    void testSetFieldWithNegativePositionThrows() {
        final Record record = new Record(1);

        assertThrows(
                IndexOutOfBoundsException.class, () -> record.setField(-1, new IntValue(1)));
    }

    @Test
    void testAddFieldAppendsToTheEnd() throws IOException {
        final Record record = new Record(new IntValue(1));

        record.addField(new StringValue("s"));
        record.addField(null);

        assertEquals(3, record.getNumFields());
        assertEquals(1, record.getField(0, IntValue.class).getValue());
        assertEquals("s", record.getField(1, StringValue.class).getValue());
        assertTrue(record.isNull(2));

        final Record copy = roundTrip(record);
        assertEquals(3, copy.getNumFields());
        assertEquals("s", copy.getField(1, StringValue.class).getValue());
        assertTrue(copy.isNull(2));
    }

    // --------------------------------------------------------------------------------------------
    //  Reading fields
    // --------------------------------------------------------------------------------------------

    @Test
    void testGetFieldReturnsSetValueBeforeBinaryIsSynchronized() {
        final Record record = new Record(1);
        final IntValue value = new IntValue(1);

        record.setField(0, value);

        // the value is retained as a reference until the binary representation is synchronized
        assertSame(value, record.getField(0, IntValue.class));
        value.setValue(2);
        assertEquals(2, record.getField(0, IntValue.class).getValue());

        record.updateBinaryRepresenation();
        value.setValue(3);
        // once synchronized, the binary representation is authoritative
        assertEquals(2, record.getField(0, IntValue.class).getValue());
    }

    @Test
    void testGetFieldDeserializesLazilyAndReusesTheCachedInstance() throws IOException {
        final Record record = roundTrip(intRecord(11, 22));

        final IntValue first = record.getField(0, IntValue.class);
        final IntValue second = record.getField(0, IntValue.class);

        assertSame(first, second);
        assertEquals(11, first.getValue());

        final IntValue other = record.getField(1, IntValue.class);
        assertEquals(22, other.getValue());
        assertNotSame(first, other);
    }

    @Test
    void testGetFieldCreatesANewInstanceWhenADifferentTypeIsRequested() throws IOException {
        // ByteValue and BooleanValue share the same binary format
        final Record record = roundTrip(new Record(new ByteValue((byte) 1)));

        final ByteValue byteValue = record.getField(0, ByteValue.class);
        assertEquals(1, byteValue.getValue());

        final BooleanValue booleanValue = record.getField(0, BooleanValue.class);
        assertTrue(booleanValue.getValue());
