package org.apache.flink.types;

import org.apache.flink.core.memory.DataInputDeserializer;
import org.apache.flink.core.memory.DataOutputSerializer;
import org.apache.flink.util.InstantiationUtil;

import org.junit.jupiter.api.Test;

import java.io.EOFException;
import java.io.IOException;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for the {@link Record} data type. */
class RecordTests {

    // --------------------------------------------------------------------------------------------
    //                                     Test utilities
    // --------------------------------------------------------------------------------------------

    /** Serializes the record and reads it back into a fresh record (binary round trip). */
    private static Record roundTrip(Record record) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(1024);
        record.write(out);
        Record result = new Record();
        result.read(new DataInputDeserializer(out.getCopyOfBuffer()));
        return result;
    }

    /** Creates a record where the given (possibly {@code null}) values are stored as int fields. */
    private static Record intRecord(Integer... values) {
        Record record = new Record(values.length);
        for (int i = 0; i < values.length; i++) {
            record.setField(i, values[i] == null ? null : new IntValue(values[i]));
        }
        return record;
    }

    private static int intAt(Record record, int position) {
        return record.getField(position, IntValue.class).getValue();
    }

    // --------------------------------------------------------------------------------------------
    //                                   Construction / field count
    // --------------------------------------------------------------------------------------------

    @Test
    void testEmptyRecordHasNoFields() {
        Record record = new Record();

        assertEquals(0, record.getNumFields());
        assertEquals(-1, record.getBinaryLength());
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(0, IntValue.class));
    }

    @Test
    void testSingleValueConstructor() {
        Record record = new Record(new IntValue(42));

        assertEquals(1, record.getNumFields());
        assertFalse(record.isNull(0));
        assertEquals(42, intAt(record, 0));
    }

    @Test
    void testTwoValueConstructor() {
        Record record = new Record(new IntValue(1), new StringValue("hello"));

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals("hello", record.getField(1, StringValue.class).getValue());
    }

    @Test
    void testConstructorAcceptsNullFields() {
        Record single = new Record((Value) null);
        assertEquals(1, single.getNumFields());
        assertTrue(single.isNull(0));
        assertNull(single.getField(0, IntValue.class));

        Record pair = new Record((Value) null, new IntValue(3));
        assertEquals(2, pair.getNumFields());
        assertTrue(pair.isNull(0));
        assertEquals(3, intAt(pair, 1));
    }

    @Test
    void testNumFieldsConstructorCreatesNullFields() {
        Record record = new Record(5);

        assertEquals(5, record.getNumFields());
        for (int i = 0; i < 5; i++) {
            assertTrue(record.isNull(i), "Field " + i + " should be null");
            assertNull(record.getField(i, IntValue.class));
        }
    }

    @Test
    void testMakeSpaceDoesNotChangeNumberOfFields() {
        Record record = new Record();
        record.makeSpace(8);

        assertEquals(0, record.getNumFields());

        record.setField(0, new IntValue(7));
        assertEquals(1, record.getNumFields());
        assertEquals(7, intAt(record, 0));
    }

    @Test
    void testSetNumFieldsExpandsRecordWithNullFields() {
        Record record = new Record(new IntValue(1));
        record.setNumFields(4);

        assertEquals(4, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        for (int i = 1; i < 4; i++) {
            assertTrue(record.isNull(i));
        }
    }

    @Test
    void testSetNumFieldsTruncatesRecord() {
        Record record = intRecord(1, 2, 3, 4);
        record.setNumFields(2);

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals(2, intAt(record, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(2));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(2, IntValue.class));
    }

    @Test
    void testSetNumFieldsToZeroClearsRecordButKeepsItUsable() {
        Record record = intRecord(1, 2);
        record.setNumFields(0);

        assertEquals(0, record.getNumFields());
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));

        record.setField(0, new IntValue(9));
        assertEquals(1, record.getNumFields());
        assertEquals(9, intAt(record, 0));
    }

    // --------------------------------------------------------------------------------------------
    //                                     setField / addField
    // --------------------------------------------------------------------------------------------

    @Test
    void testSetFieldExpandsRecordBeyondCurrentSize() {
        Record record = new Record();
        record.setField(4, new IntValue(5));

        assertEquals(5, record.getNumFields());
        for (int i = 0; i < 4; i++) {
            assertTrue(record.isNull(i));
        }
        assertEquals(5, intAt(record, 4));

        Record copy = roundTrip(record);
        assertEquals(5, copy.getNumFields());
        assertTrue(copy.isNull(0));
        assertTrue(copy.isNull(3));
        assertEquals(5, intAt(copy, 4));
    }

    @Test
    void testSetFieldToNullMarksFieldAsNull() {
        Record record = intRecord(1);
        record.setField(0, null);

        assertEquals(1, record.getNumFields());
        assertTrue(record.isNull(0));
        assertNull(record.getField(0, IntValue.class));
        assertTrue(roundTrip(record).isNull(0));
    }

    @Test
    void testSetFieldWithNegativePositionThrows() {
        Record record = new Record();

        assertThrows(IndexOutOfBoundsException.class, () -> record.setField(-1, new IntValue(1)));
    }

    @Test
    void testAddFieldAppendsFields() {
        Record record = new Record(1);
        record.setField(0, new IntValue(1));
        record.addField(new StringValue("s"));
        record.addField(null);

        assertEquals(3, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals("s", record.getField(1, StringValue.class).getValue());
        assertTrue(record.isNull(2));

        Record copy = roundTrip(record);
        assertEquals(3, copy.getNumFields());
        assertEquals("s", copy.getField(1, StringValue.class).getValue());
        assertTrue(copy.isNull(2));
    }

    // --------------------------------------------------------------------------------------------
    //                                        getField
    // --------------------------------------------------------------------------------------------

    @Test
    void testGetFieldReturnsValueInstanceUntilBinaryIsSynchronized() {
        IntValue value = new IntValue(1);
        Record record = new Record();
        record.setField(0, value);

        assertSame(value, record.getField(0, IntValue.class));

        // modifications of the value are visible through the record until the binary is synced
        value.setValue(2);
        assertEquals(2, intAt(record, 0));

        record.updateBinaryRepresenation();
        value.setValue(3);
        assertEquals(2, intAt(record, 0), "The binary representation should be authoritative");
    }

    @Test
    void testGetFieldDeserializesLazilyAndCachesInstances() throws Exception {
        Record record = roundTrip(intRecord(17, 18));

        IntValue first = record.getField(0, IntValue.class);
        IntValue second = record.getField(0, IntValue.class);
        assertSame(first, second);
        assertEquals(17, first.getValue());

        // the binary representation is authoritative: changes on a returned value are not tracked
        first.setValue(99);
        assertEquals(17, intAt(record, 0));
    }

    @Test
    void testGetFieldWithDifferentTypeCreatesNewInstance() throws Exception {
        Record record = roundTrip(new Record(new ByteValue((byte) 1)));

        ByteValue asByte = record.getField(0, ByteValue.class);
        assertSame(asByte, record.getField(0, ByteValue.class));

        // a BooleanValue reads exactly the same binary form (one byte)
        BooleanValue asBoolean = record.getField(0, BooleanValue.class);
        assertTrue(asBoolean.getValue());

        ByteValue asByteAgain = record.getField(0, ByteValue.class);
        assertNotSame(asByte, asByteAgain);
        assertEquals(1, asByteAgain.getValue());
    }

    @Test
    void testGetFieldWithOutOfRangePositionThrows() {
        Record record = new Record(new IntValue(1));

        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(-1, IntValue.class));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(1, IntValue.class));
    }

    @Test
    void testGetFieldWithWrongTypeThrowsDeserializationException() throws Exception {
        Record record = roundTrip(new Record(new ByteValue((byte) 4)));

        DeserializationException exception =
                assertThrows(
                        DeserializationException.class,
                        () -> record.getField(0, IntValue.class));
        assertTrue(exception.getMessage().contains("Error reading field 0"));
        assertTrue(exception.getCause() instanceof EOFException);
    }

    @Test
    void testGetFieldWithTargetDeserializesIntoGivenInstance() throws Exception {
        Record record = roundTrip(intRecord(11));

        IntValue target = new IntValue();
        IntValue result = record.getField(0, target);

        assertSame(target, result);
        assertEquals(11, target.getValue());
    }

    @Test
    void testGetFieldWithTargetLeavesTargetUntouchedForNullField() {
        Record record = new Record(1);

        IntValue target = new IntValue(-7);

        assertNull(record.getField(0, target));
        assertEquals(-7, target.getValue());
    }

    @Test
    void testGetFieldWithTargetReturnsStoredValueForModifiedField() {
        IntValue value = new IntValue(5);
        Record record = new Record();
        record.setField(0, value);

        IntValue target = new IntValue(-1);
        IntValue result = record.getField(0, target);

        assertSame(value, result);
        assertEquals(-1, target.getValue(), "The target must be left unchanged");
    }

    @Test
    void testGetFieldWithTargetRejectsNullTargetAndOutOfRangePositions() {
        Record record = new Record(new IntValue(1));

        assertThrows(NullPointerException.class, () -> record.getField(0, (Value) null));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(1, new IntValue()));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(-1, new IntValue()));
    }

    // --------------------------------------------------------------------------------------------
    //                          getFieldInto / getFieldsInto(CheckingNull)
    // --------------------------------------------------------------------------------------------

    @Test
    void testGetFieldIntoReadsBinaryField() throws Exception {
        Record record = roundTrip(intRecord(23));

        IntValue target = new IntValue();
        assertTrue(record.getFieldInto(0, target));
        assertEquals(23, target.getValue());
    }

    @Test
    void testGetFieldIntoReturnsFalseForNullFieldAndKeepsTarget() {
        Record record = new Record(1);
        IntValue target = new IntValue(-3);

        assertFalse(record.getFieldInto(0, target));
        assertEquals(-3, target.getValue());
    }

    @Test
    void testGetFieldIntoHandlesModifiedFields() {
        Record record = new Record();
        record.setField(0, new IntValue(33));

        IntValue target = new IntValue();
        assertTrue(record.getFieldInto(0, target));
        assertEquals(33, target.getValue());
        assertEquals(33, intAt(record, 0));
    }

    @Test
    void testGetFieldIntoOutOfRangeThrows() {
        Record record = new Record(1);

        assertThrows(IndexOutOfBoundsException.class, () -> record.getFieldInto(1, new IntValue()));
        assertThrows(
                IndexOutOfBoundsException.class, () -> record.getFieldInto(-1, new IntValue()));
    }

    @Test
    void testGetFieldsIntoFillsAllRequestedFields() throws Exception {
        Record record = roundTrip(intRecord(1, 2, 3));

        Value[] targets = {new IntValue(), new IntValue(), new IntValue()};
        assertTrue(record.getFieldsInto(new int[] {0, 2}, targets));
        assertEquals(1, ((IntValue) targets[0]).getValue());
        assertEquals(3, ((IntValue) targets[2]).getValue());
    }

    @Test
    void testGetFieldsIntoStopsAtFirstNullField() throws Exception {
        Record record = roundTrip(intRecord(1, null, 3));

        Value[] targets = {new IntValue(), new IntValue(-1), new IntValue(-2)};
        assertFalse(record.getFieldsInto(new int[] {0, 1, 2}, targets));
        assertEquals(1, ((IntValue) targets[0]).getValue());
        assertEquals(-1, ((IntValue) targets[1]).getValue());
        assertEquals(-2, ((IntValue) targets[2]).getValue());
    }

    @Test
    void testGetFieldsIntoCheckingNullThrowsForNullField() throws Exception {
        Record record = roundTrip(intRecord(1, null));

        Value[] targets = {new IntValue(), new IntValue()};
        NullKeyFieldException exception =
                assertThrows(
                        NullKeyFieldException.class,
                        () -> record.getFieldsIntoCheckingNull(new int[] {0, 1}, targets));
        assertEquals(1, exception.getFieldNumber());
        assertEquals(1, ((IntValue) targets[0]).getValue());
    }

    @Test
    void testGetFieldsIntoCheckingNullSucceedsForNonNullFields() throws Exception {
        Record record = roundTrip(intRecord(4, 5));

        Value[] targets = {new IntValue(), new IntValue()};
        record.getFieldsIntoCheckingNull(new int[] {0, 1}, targets);
        assertEquals(4, ((IntValue) targets[0]).getValue());
        assertEquals(5, ((IntValue) targets[1]).getValue());
    }

    // --------------------------------------------------------------------------------------------
    //                                        equalsFields
    // --------------------------------------------------------------------------------------------

    @Test
    void testEqualsFieldsComparesRequestedPositions() throws Exception {
        Record record = roundTrip(new Record(new IntValue(1), new StringValue("x")));

        Value[] holders = {new IntValue(), new StringValue()};
        assertTrue(
                record.equalsFields(
                        new int[] {0, 1},
                        new Value[] {new IntValue(1), new StringValue("x")},
                        holders));

        Value[] otherHolders = {new IntValue(), new StringValue()};
        assertFalse(
                record.equalsFields(
                        new int[] {0, 1},
                        new Value[] {new IntValue(2), new StringValue("x")},
                        otherHolders));
    }

    @Test
    void testEqualsFieldsReturnsFalseForNullField() throws Exception {
        Record record = roundTrip(intRecord((Integer) null));

        assertFalse(
                record.equalsFields(
                        new int[] {0}, new Value[] {new IntValue(1)}, new Value[] {new IntValue()}));
    }

    // --------------------------------------------------------------------------------------------
    //                                 removeField / isNull / setNull
    // --------------------------------------------------------------------------------------------

    @Test
    void testRemoveFieldShiftsRemainingFields() throws Exception {
        Record record = roundTrip(intRecord(1, 2, 3));
        record.removeField(1);

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals(3, intAt(record, 1));

        Record copy = roundTrip(record);
        assertEquals(2, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertEquals(3, intAt(copy, 1));
    }

    @Test
    void testRemoveLastField() {
        Record record = intRecord(1, 2, null);
        record.removeField(2);

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals(2, intAt(record, 1));
    }

    @Test
    void testRemoveFieldOutOfRangeThrows() {
        Record record = intRecord(1, 2);

        assertThrows(IndexOutOfBoundsException.class, () -> record.removeField(-1));
        assertThrows(IndexOutOfBoundsException.class, () -> record.removeField(2));
    }

    @Test
    void testIsNullOutOfRangeThrows() {
        Record record = new Record(new IntValue(1));

        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(-1));
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(1));
    }

    @Test
    void testSetNullSingleField() {
        Record record = intRecord(1, 2);

        record.setNull(0);

        assertTrue(record.isNull(0));
        assertEquals(2, intAt(record, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> record.setNull(2));
        assertThrows(IndexOutOfBoundsException.class, () -> record.setNull(-1));
    }

    @Test
    void testSetNullWithBitMask() {
        Record record = intRecord(1, 2, 3, 4);

        // nullify fields 1 and 3
        record.setNull(0b1010L);

        assertFalse(record.isNull(0));
        assertTrue(record.isNull(1));
        assertFalse(record.isNull(2));
        assertTrue(record.isNull(3));

        Record copy = roundTrip(record);
        assertFalse(copy.isNull(0));
        assertTrue(copy.isNull(1));
        assertFalse(copy.isNull(2));
        assertTrue(copy.isNull(3));
    }

    @Test
    void testSetNullWithBitMaskArray() {
        Record record = new Record(70);
        for (int i = 0; i < 70; i++) {
            record.setField(i, new IntValue(i));
        }

        // the first (least significant) bit of the first word corresponds to field 0
        record.setNull(new long[] {0b101L, 0L});

        assertTrue(record.isNull(0));
        assertFalse(record.isNull(1));
        assertTrue(record.isNull(2));
        assertFalse(record.isNull(3));
        assertFalse(record.isNull(64));
    }

    @Test
    void testClearRemovesAllFields() {
        Record record = intRecord(1, 2, 3);
        record.clear();

        assertEquals(0, record.getNumFields());
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));

        // clearing an already empty record is a no-op
        record.clear();
        assertEquals(0, record.getNumFields());
    }

    @Test
    void testConcatenateIsUnsupported() {
        Record record = intRecord(1);

        assertThrows(UnsupportedOperationException.class, () -> record.concatenate(intRecord(2)));
    }

    // --------------------------------------------------------------------------------------------
    //                                       unionFields
    // --------------------------------------------------------------------------------------------

    @Test
    void testUnionFieldsMergesFieldsOfModifiedRecords() {
        Record left = intRecord(1, null, 3);
        Record right = intRecord(10, 20);

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertEquals(20, intAt(left, 1));
        assertEquals(3, intAt(left, 2));
    }

    @Test
    void testUnionFieldsWithBinaryRepresentations() throws Exception {
        Record left = intRecord(1, null, 3);
        Record right = intRecord(10, 20);
        left.updateBinaryRepresenation();
        right.updateBinaryRepresenation();

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertEquals(20, intAt(left, 1));
        assertEquals(3, intAt(left, 2));
    }

    @Test
    void testUnionFieldsKeepsLeftFieldWhenBothDefineIt() throws Exception {
        Record left = roundTrip(intRecord(1, 2));
        Record right = intRecord(7, null, 9);

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertEquals(2, intAt(left, 1));
        assertEquals(9, intAt(left, 2));
    }

    @Test
    void testUnionFieldsWithBinaryLeftAndModifiedRight() throws Exception {
        Record left = roundTrip(intRecord(null, 5, 6));
        Record right = intRecord(1, 2);

        left.unionFields(right);

        assertEquals(3, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertEquals(5, intAt(left, 1));
        assertEquals(6, intAt(left, 2));
    }

    @Test
    void testUnionFieldsWithBinaryRecordsOfDifferentLengths() throws Exception {
        Record left = intRecord(null, null);
        left.updateBinaryRepresenation();
        Record right = intRecord(1, null, 3, 4);
        right.updateBinaryRepresenation();

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertTrue(left.isNull(1));
        assertEquals(3, intAt(left, 2));
        assertEquals(4, intAt(left, 3));

        Record copy = roundTrip(left);
        assertEquals(4, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals(3, intAt(copy, 2));
        assertEquals(4, intAt(copy, 3));
    }

    @Test
    void testUnionFieldsResultSurvivesSerialization() throws Exception {
        Record left = intRecord(1, 2);
        Record right = intRecord(null, 20, 30);
        left.unionFields(right);

        Record copy = roundTrip(left);
        assertArrayEquals(
                new Integer[] {1, 2, 30},
                new Integer[] {intAt(copy, 0), intAt(copy, 1), intAt(copy, 2)});
    }

    // --------------------------------------------------------------------------------------------
    //                              copyTo / createCopy / copy
    // --------------------------------------------------------------------------------------------

    @Test
    void testCopyToCreatesIndependentRecord() {
        Record original = intRecord(1, 2);
        Record copy = new Record();

        original.copyTo(copy);

        assertEquals(2, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertEquals(2, intAt(copy, 1));

        copy.setField(0, new IntValue(50));
        copy.removeField(1);
        assertEquals(2, original.getNumFields());
        assertEquals(1, intAt(original, 0));
        assertEquals(2, intAt(original, 1));

        original.setField(1, new IntValue(60));
        assertEquals(1, intAt(copy, 0));
    }

    @Test
    void testCopyToOverwritesTargetContent() {
        Record target = intRecord(7, 8, 9, 10);
        Record source = intRecord(1, 2);

        source.copyTo(target);

        assertEquals(2, target.getNumFields());
        assertEquals(1, intAt(target, 0));
        assertEquals(2, intAt(target, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> target.getField(2, IntValue.class));
    }

    @Test
    void testCopyToWithModifiedSourceFields() {
        Record source = new Record();
        source.setField(0, new IntValue(5));
        source.setField(1, new StringValue("abc"));

        Record target = new Record();
        source.copyTo(target);

        assertEquals(5, intAt(target, 0));
        assertEquals("abc", target.getField(1, StringValue.class).getValue());
    }

    @Test
    void testCopyAndCreateCopyAreEquivalent() throws Exception {
        Record original = intRecord(1, null, 3);

        Record copy = original.copy();
        Record created = original.createCopy();

        assertEquals(original.getNumFields(), copy.getNumFields());
        assertEquals(original.getNumFields(), created.getNumFields());
        for (int i = 0; i < original.getNumFields(); i++) {
            assertEquals(original.isNull(i), copy.isNull(i));
            assertEquals(original.isNull(i), created.isNull(i));
        }
        assertEquals(3, intAt(copy, 2));
        assertEquals(3, intAt(created, 2));
    }

    // --------------------------------------------------------------------------------------------
    //                          write / read / serialize / deserialize / copy
    // --------------------------------------------------------------------------------------------

    @Test
    void testWriteReadRoundTripWithMixedFields() throws Exception {
        Record record = new Record(3);
        record.setField(0, new IntValue(11));
        record.setField(1, null);
        record.setField(2, new StringValue("round trip"));

        Record copy = roundTrip(record);

        assertEquals(3, copy.getNumFields());
        assertEquals(11, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals("round trip", copy.getField(2, StringValue.class).getValue());
    }

    @Test
    void testWriteReadRoundTripForRecordsWithManyFields() throws Exception {
        Record record = new Record(65);
        for (int i = 0; i < 65; i++) {
            record.setField(i, i % 7 == 0 ? null : new IntValue(i * 3));
        }

        Record copy = roundTrip(record);

        assertEquals(65, copy.getNumFields());
        for (int i = 0; i < 65; i++) {
            if (i % 7 == 0) {
                assertTrue(copy.isNull(i), "Field " + i + " should be null");
            } else {
                assertEquals(i * 3, intAt(copy, i));
            }
        }
    }

    @Test
    void testWriteReadRoundTripForRecordsWithNineFields() throws Exception {
        Record record = intRecord(1, 2, 3, 4, null, 6, 7, 8, 9);

        Record copy = roundTrip(record);

        assertEquals(9, copy.getNumFields());
        assertTrue(copy.isNull(4));
        assertEquals(1, intAt(copy, 0));
        assertEquals(9, intAt(copy, 8));
    }

    @Test
    void testWriteReadRoundTripForEmptyRecord() throws Exception {
        Record copy = roundTrip(new Record());

        assertEquals(0, copy.getNumFields());
    }

    @Test
    void testSerializeReturnsNumberOfWrittenBytes() throws Exception {
        Record record = intRecord(1, 2, 3);
        DataOutputSerializer out = new DataOutputSerializer(16);

        long written = record.serialize(out);

        assertEquals(out.length(), written);
        assertEquals(0, new DataInputDeserializer(out.getCopyOfBuffer()).available() - out.length());
    }

    @Test
    void testSerializeWritesSameBytesAsWrite() throws Exception {
        Record record = new Record(2);
        record.setField(0, new IntValue(7));
        record.setField(1, new StringValue("bytes"));

        DataOutputSerializer serializeOut = new DataOutputSerializer(64);
        record.serialize(serializeOut);
        DataOutputSerializer writeOut = new DataOutputSerializer(64);
        record.write(writeOut);

        assertArrayEquals(writeOut.getCopyOfBuffer(), serializeOut.getCopyOfBuffer());
    }

    @Test
    void testCopyBetweenViewsPreservesContent() throws Exception {
        Record source = new Record(2);
        source.setField(0, new IntValue(11));
        source.setField(1, new StringValue("hello"));

        DataOutputSerializer sourceOut = new DataOutputSerializer(64);
        source.write(sourceOut);
        byte[] serialized = sourceOut.getCopyOfBuffer();

        DataOutputSerializer targetOut = new DataOutputSerializer(64);
        Record copier = new Record();
        copier.copy(new DataInputDeserializer(serialized), targetOut);

        assertEquals(serialized.length, targetOut.length());

        Record result = new Record();
        result.read(new DataInputDeserializer(targetOut.getCopyOfBuffer()));
        assertEquals(2, result.getNumFields());
        assertEquals(11, intAt(result, 0));
        assertEquals("hello", result.getField(1, StringValue.class).getValue());
    }

    @Test
    void testDeserializeIsEquivalentToRead() throws Exception {
        Record record = intRecord(1, 2);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);

        Record deserialized = new Record();
        deserialized.deserialize(new DataInputDeserializer(out.getCopyOfBuffer()));

        assertEquals(2, deserialized.getNumFields());
        assertEquals(1, intAt(deserialized, 0));
        assertEquals(2, intAt(deserialized, 1));
    }

    @Test
    void testReadIntoReusedRecordReplacesContent() throws Exception {
        Record reused = intRecord(1, 2, 3, 4, 5);
        Record source = intRecord(7, 8);
        DataOutputSerializer out = new DataOutputSerializer(64);
        source.write(out);

        reused.read(new DataInputDeserializer(out.getCopyOfBuffer()));

        assertEquals(2, reused.getNumFields());
        assertEquals(7, intAt(reused, 0));
        assertEquals(8, intAt(reused, 1));
    }

    @Test
    void testReadFromTruncatedInputThrows() throws Exception {
        Record record = intRecord(1, 2, 3);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);
        byte[] truncated = Arrays.copyOf(out.getCopyOfBuffer(), 4);

        assertThrows(
                EOFException.class,
                () -> new Record().read(new DataInputDeserializer(truncated)));
    }

    @Test
    void testReadWithCorruptedHeaderThrowsRuntimeException() throws Exception {
        Record record = intRecord(1, 2);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);
        byte[] corrupted = out.getCopyOfBuffer();
        // turn the number of fields at the end of the record into a multi byte value
        corrupted[corrupted.length - 1] = (byte) 0xC8;

        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> new Record().read(new DataInputDeserializer(corrupted)));
        assertTrue(exception.getMessage().startsWith("Record deserialization error"));
    }

    // --------------------------------------------------------------------------------------------
    //                                     copyFrom
    // --------------------------------------------------------------------------------------------

    @Test
    void testCopyFromCopiesSelectedFieldsIntoSelectedPositions() throws Exception {
        Record source = new Record(2);
        source.setField(0, new IntValue(11));
        source.setField(1, new StringValue("hello"));
        source.updateBinaryRepresenation();

        Record target = intRecord(-1, -2, -3);
        target.copyFrom(source, new int[] {0, 1}, new int[] {2, 0});

        assertEquals(3, target.getNumFields());
        assertEquals("hello", target.getField(0, StringValue.class).getValue());
        assertEquals(-2, intAt(target, 1));

        Record copy = roundTrip(target);
        assertEquals(3, copy.getNumFields());
        assertEquals("hello", copy.getField(0, StringValue.class).getValue());
        assertEquals(-2, intAt(copy, 1));
        assertEquals(11, intAt(copy, 2));
    }

    @Test
    void testCopyFromExpandsTargetAndCopiesModifiedFields() {
        IntValue modified = new IntValue(5);
        Record source = new Record(1);
        source.setField(0, modified);

        Record target = new Record(0);
        target.copyFrom(source, new int[] {0}, new int[] {1});

        assertEquals(2, target.getNumFields());
        assertTrue(target.isNull(0));
        assertSame(modified, target.getField(1, IntValue.class));
    }

    @Test
    void testCopyFromNullSourceFieldNullifiesTargetField() {
        Record source = new Record(1);
        Record target = intRecord(5);

        target.copyFrom(source, new int[] {0}, new int[] {0});

        assertTrue(target.isNull(0));
    }

    // --------------------------------------------------------------------------------------------
    //                                   Java serialization
    // --------------------------------------------------------------------------------------------

    @Test
    void testJavaSerializationRoundTrip() throws Exception {
        Record record = new Record(3);
        record.setField(0, new IntValue(1));
        record.setField(2, new StringValue("abc"));

        byte[] serialized = InstantiationUtil.serializeObject(record);
        Record copy =
                InstantiationUtil.deserializeObject(
                        serialized, RecordTests.class.getClassLoader());

        assertEquals(3, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals("abc", copy.getField(2, StringValue.class).getValue());
    }
}
