/**
 * Tests for {@link AvroSchemaConverter}.
 *
 * <p>The tests exercise the public conversion entry points (Avro schema/class to Flink type
 * information and data types, and Flink logical types back to Avro schemas) and their observable
 * behavior such as field ordering, nullability handling, logical type mappings and error handling.
 */
class AvroSchemaConverterTests {

    // ---------------------------------------------------------------------
    // Avro schema -> TypeInformation
    // ---------------------------------------------------------------------

    @Test
    void testConvertToTypeInfoPreservesFieldOrderAndPrimitiveTypes() {
        final String schema =
                "{\"type\":\"record\",\"name\":\"PrimitiveRecord\",\"namespace\":\"com.example\","
                        + "\"fields\":["
                        + "{\"name\":\"f_int\",\"type\":\"int\"},"
                        + "{\"name\":\"f_long\",\"type\":\"long\"},"
                        + "{\"name\":\"f_float\",\"type\":\"float\"},"
                        + "{\"name\":\"f_double\",\"type\":\"double\"},"
                        + "{\"name\":\"f_boolean\",\"type\":\"boolean\"},"
                        + "{\"name\":\"f_string\",\"type\":\"string\"},"
                        + "{\"name\":\"f_bytes\",\"type\":\"bytes\"},"
                        + "{\"name\":\"f_null\",\"type\":\"null\"}]}";

        final TypeInformation<Row> typeInfo = AvroSchemaConverter.convertToTypeInfo(schema);

        final RowTypeInfo rowInfo = assertInstanceOf(RowTypeInfo.class, typeInfo);
        assertArrayEquals(
                new String[] {
                    "f_int", "f_long", "f_float", "f_double", "f_boolean", "f_string", "f_bytes",
                    "f_null"
                },
                rowInfo.getFieldNames());
        assertEquals(Types.INT, rowInfo.getTypeAt("f_int"));
        assertEquals(Types.LONG, rowInfo.getTypeAt("f_long"));
        assertEquals(Types.FLOAT, rowInfo.getTypeAt("f_float"));
        assertEquals(Types.DOUBLE, rowInfo.getTypeAt("f_double"));
        assertEquals(Types.BOOLEAN, rowInfo.getTypeAt("f_boolean"));
        assertEquals(Types.STRING, rowInfo.getTypeAt("f_string"));
        assertEquals(Types.PRIMITIVE_ARRAY(Types.BYTE), rowInfo.getTypeAt("f_bytes"));
        assertEquals(Types.VOID, rowInfo.getTypeAt("f_null"));
    }

    @Test
    void testConvertToTypeInfoMapsComplexAvroTypes() {
        final String schema =
                "{\"type\":\"record\",\"name\":\"ComplexRecord\",\"fields\":["
                        + "{\"name\":\"f_enum\",\"type\":{\"type\":\"enum\",\"name\":\"Color\","
                        + "\"symbols\":[\"RED\",\"GREEN\"]}},"
                        + "{\"name\":\"f_array\",\"type\":{\"type\":\"array\",\"items\":\"string\"}},"
                        + "{\"name\":\"f_map\",\"type\":{\"type\":\"map\",\"values\":\"long\"}},"
                        + "{\"name\":\"f_fixed\",\"type\":{\"type\":\"fixed\",\"name\":\"Fixed4\","
                        + "\"size\":4}},"
                        + "{\"name\":\"f_decimal_bytes\",\"type\":{\"type\":\"bytes\","
                        + "\"logicalType\":\"decimal\",\"precision\":10,\"scale\":2}},"
                        + "{\"name\":\"f_decimal_fixed\",\"type\":{\"type\":\"fixed\","
                        + "\"name\":\"DecimalFixed\",\"size\":8,\"logicalType\":\"decimal\","
                        + "\"precision\":10,\"scale\":2}}]}";

        final RowTypeInfo rowInfo =
                assertInstanceOf(
                        RowTypeInfo.class, AvroSchemaConverter.convertToTypeInfo(schema));

        assertEquals(Types.STRING, rowInfo.getTypeAt("f_enum"));
        assertEquals(Types.OBJECT_ARRAY(Types.STRING), rowInfo.getTypeAt("f_array"));
        assertEquals(Types.MAP(Types.STRING, Types.LONG), rowInfo.getTypeAt("f_map"));
        assertEquals(Types.PRIMITIVE_ARRAY(Types.BYTE), rowInfo.getTypeAt("f_fixed"));
        assertEquals(Types.BIG_DEC, rowInfo.getTypeAt("f_decimal_bytes"));
        assertEquals(Types.BIG_DEC, rowInfo.getTypeAt("f_decimal_fixed"));
    }

    @Test
    void testConvertToTypeInfoUnwrapsNullableAndSingleTypeUnions() {
        final String schema =
                "{\"type\":\"record\",\"name\":\"UnionRecord\",\"fields\":["
                        + "{\"name\":\"only_null\",\"type\":[\"null\"]},"
                        + "{\"name\":\"null_first\",\"type\":[\"null\",\"int\"]},"
                        + "{\"name\":\"null_last\",\"type\":[\"int\",\"null\"]},"
                        + "{\"name\":\"multi\",\"type\":[\"null\",\"boolean\",\"long\",\"double\"]}]}";

        final RowTypeInfo rowInfo =
                assertInstanceOf(
                        RowTypeInfo.class, AvroSchemaConverter.convertToTypeInfo(schema));

        assertEquals(Types.VOID, rowInfo.getTypeAt("only_null"));
        assertEquals(Types.INT, rowInfo.getTypeAt("null_first"));
        assertEquals(Types.INT, rowInfo.getTypeAt("null_last"));
        assertEquals(Types.GENERIC(Object.class), rowInfo.getTypeAt("multi"));
    }

    @Test
    void testConvertToTypeInfoUsesLegacyLogicalTypeMappingByDefault() {
        final String schema =
                "{\"type\":\"record\",\"name\":\"LegacyLogicalRecord\",\"fields\":["
                        + "{\"name\":\"f_date\",\"type\":{\"type\":\"int\",\"logicalType\":\"date\"}},"
                        + "{\"name\":\"f_time_millis\",\"type\":{\"type\":\"int\","
                        + "\"logicalType\":\"time-millis\"}},"
                        + "{\"name\":\"f_time_micros\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"time-micros\"}},"
                        + "{\"name\":\"f_ts_millis\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"timestamp-millis\"}},"
                        + "{\"name\":\"f_ts_micros\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"timestamp-micros\"}}]}";

        final RowTypeInfo rowInfo =
                assertInstanceOf(
                        RowTypeInfo.class, AvroSchemaConverter.convertToTypeInfo(schema));

        assertEquals(Types.SQL_DATE, rowInfo.getTypeAt("f_date"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("f_time_millis"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("f_time_micros"));
        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("f_ts_millis"));
        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("f_ts_micros"));
    }

    @Test
    void testConvertToTypeInfoUsesNonLegacyLogicalTypeMapping() {
        final String schema =
                "{\"type\":\"record\",\"name\":\"ModernLogicalRecord\",\"fields\":["
                        + "{\"name\":\"f_ts_millis\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"timestamp-millis\"}},"
                        + "{\"name\":\"f_ts_micros\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"timestamp-micros\"}},"
                        + "{\"name\":\"f_local_millis\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"local-timestamp-millis\"}},"
                        + "{\"name\":\"f_local_micros\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"local-timestamp-micros\"}},"
                        + "{\"name\":\"f_time_millis\",\"type\":{\"type\":\"int\","
                        + "\"logicalType\":\"time-millis\"}},"
                        + "{\"name\":\"f_time_micros\",\"type\":{\"type\":\"long\","
                        + "\"logicalType\":\"time-micros\"}}]}";

        final RowTypeInfo rowInfo =
                assertInstanceOf(
                        RowTypeInfo.class,
                        AvroSchemaConverter.convertToTypeInfo(schema, false));

        assertEquals(Types.INSTANT, rowInfo.getTypeAt("f_ts_millis"));
        assertEquals(Types.INSTANT, rowInfo.getTypeAt("f_ts_micros"));
        assertEquals(Types.LOCAL_DATE_TIME, rowInfo.getTypeAt("f_local_millis"));
        assertEquals(Types.LOCAL_DATE_TIME, rowInfo.getTypeAt("f_local_micros"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("f_time_millis"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("f_time_micros"));
    }

    @Test
    void testConvertToTypeInfoFromSpecificRecordClass() {
        final TypeInformation<Row> typeInfo = AvroSchemaConverter.convertToTypeInfo(User.class);

        final RowTypeInfo rowInfo = assertInstanceOf(RowTypeInfo.class, typeInfo);
        assertArrayEquals(
                new String[] {
                    "name",
                    "favorite_number",
                    "favorite_color",
                    "type_long_test",
                    "type_double_test",
                    "type_null_test",
                    "type_bool_test",
                    "type_array_string",
                    "type_array_boolean",
                    "type_nullable_array",
                    "type_enum",
                    "type_map",
                    "type_fixed",
                    "type_union",
                    "type_nested",
                    "type_bytes",
                    "type_date",
                    "type_time_millis",
                    "type_time_micros",
                    "type_timestamp_millis",
                    "type_timestamp_micros",
                    "type_decimal_bytes",
                    "type_decimal_fixed"
                },
                rowInfo.getFieldNames());

        assertEquals(Types.STRING, rowInfo.getTypeAt("name"));
        assertEquals(Types.INT, rowInfo.getTypeAt("favorite_number"));
        assertEquals(Types.STRING, rowInfo.getTypeAt("type_enum"));
        assertEquals(Types.OBJECT_ARRAY(Types.STRING), rowInfo.getTypeAt("type_array_string"));
        assertEquals(Types.MAP(Types.STRING, Types.LONG), rowInfo.getTypeAt("type_map"));
        assertEquals(Types.PRIMITIVE_ARRAY(Types.BYTE), rowInfo.getTypeAt("type_fixed"));
        assertEquals(Types.GENERIC(Object.class), rowInfo.getTypeAt("type_union"));
        assertEquals(Types.BIG_DEC, rowInfo.getTypeAt("type_decimal_bytes"));
        assertEquals(Types.BIG_DEC, rowInfo.getTypeAt("type_decimal_fixed"));
        assertEquals(Types.SQL_DATE, rowInfo.getTypeAt("type_date"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("type_time_millis"));
        assertEquals(Types.SQL_TIME, rowInfo.getTypeAt("type_time_micros"));
        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("type_timestamp_millis"));
        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("type_timestamp_micros"));

        final RowTypeInfo nested = assertInstanceOf(RowTypeInfo.class, rowInfo.getTypeAt("type_nested"));
        assertArrayEquals(
                new String[] {"num", "street", "city", "state", "zip"}, nested.getFieldNames());
        assertEquals(Types.INT, nested.getTypeAt("num"));
        assertEquals(Types.STRING, nested.getTypeAt("street"));
    }

    @Test
    void testConvertToTypeInfoFromSpecificRecordClassWithLegacyTimestampMapping() {
        final RowTypeInfo rowInfo =
                assertInstanceOf(
                        RowTypeInfo.class,
                        AvroSchemaConverter.convertToTypeInfo(Timestamps.class, true));

        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("type_timestamp_millis"));
        assertEquals(Types.SQL_TIMESTAMP, rowInfo.getTypeAt("type_timestamp_micros"));
        // Legacy mapping does not know local timestamps, so they fall back to plain long.
        assertEquals(Types.LONG, rowInfo.getTypeAt("type_local_timestamp_millis"));
        assertEquals(Types.LONG, rowInfo.getTypeAt("type_local_timestamp_micros"));
    }

    @Test
    void testConvertToTypeInfoRejectsNullSchemaString() {
        final NullPointerException exception =
                assertThrows(
                        NullPointerException.class,
                        () -> AvroSchemaConverter.convertToTypeInfo((String) null));
        assertEquals("Avro schema must not be null.", exception.getMessage());
    }

    @Test
    void testConvertToTypeInfoRejectsUnparsableSchemaString() {
        final IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
