                                                                DataTypes.FIELD(
                                                                        "x",
                                                                        DataTypes.INT()
                                                                                .notNull()))
                                                        .notNull()))
                                .notNull()
                                .getLogicalType();

        final Schema schema =
                AvroSchemaConverter.convertToSchema(rowType, "com.example.CustomRecord");

        assertEquals("CustomRecord", schema.getName());
        assertEquals("com.example", schema.getNamespace());

        final Schema inner = schema.getField("inner").schema();
        assertEquals("CustomRecord_inner", inner.getName());
        assertEquals("com.example", inner.getNamespace());
        assertEquals(Schema.Type.INT, inner.getField("x").schema().getType());
    }

    @Test
    void testConvertToSchemaWrapsNullableRowInUnion() {
        final RowType rowType =
                (RowType)
