        assertEquals("CustomRecord_inner", inner.getName());
        assertEquals("com.example", inner.getNamespace());
        assertEquals(Schema.Type.INT, inner.getField("x").schema().getType());
    }

    @Test
    void testConvertToSchemaWrapsNullableRowInUnion() {
        final RowType rowType =
                (RowType)
                        DataTypes.ROW(DataTypes.FIELD("id", DataTypes.INT().notNull()))
                                .nullable()
                                .getLogicalType();

        final Schema schema = AvroSchemaConverter.convertToSchema(rowType);

        assertEquals(Schema.Type.UNION, schema.getType());
        assertEquals(Schema.Type.NULL, schema.getTypes().get(0).getType());
        final Schema record = schema.getTypes().get(1);
        assertEquals(Schema.Type.RECORD, record.getType());
        assertEquals("record", record.getName());
    }

    @Test
    void testConvertToSchemaMapsPrimitiveTypes() {
        assertConvertedSchemaType(DataTypes.BOOLEAN().notNull(), Schema.Type.BOOLEAN);
        assertConvertedSchemaType(DataTypes.TINYINT().notNull(), Schema.Type.INT);
        assertConvertedSchemaType(DataTypes.SMALLINT().notNull(), Schema.Type.INT);
        assertConvertedSchemaType(DataTypes.INT().notNull(), Schema.Type.INT);
        assertConvertedSchemaType(DataTypes.BIGINT().notNull(), Schema.Type.LONG);
        assertConvertedSchemaType(DataTypes.FLOAT().notNull(), Schema.Type.FLOAT);
        assertConvertedSchemaType(DataTypes.DOUBLE().notNull(), Schema.Type.DOUBLE);
        assertConvertedSchemaType(DataTypes.CHAR(5).notNull(), Schema.Type.STRING);
        assertConvertedSchemaType(DataTypes.VARCHAR(5).notNull(), Schema.Type.STRING);
        assertConvertedSchemaType(DataTypes.BINARY(5).notNull(), Schema.Type.BYTES);
        assertConvertedSchemaType(DataTypes.VARBINARY(5).notNull(), Schema.Type.BYTES);
        assertConvertedSchemaType(DataTypes.NULL(), Schema.Type.NULL);
    }

    @Test
    void testConvertToSchemaMapsDateAndDecimal() {
        final Schema date =
                AvroSchemaConverter.convertToSchema(DataTypes.DATE().notNull().getLogicalType());
        assertEquals(Schema.Type.INT, date.getType());
        assertEquals("date", date.getLogicalType().getName());

        final Schema decimal =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.DECIMAL(12, 3).notNull().getLogicalType());
        assertEquals(Schema.Type.BYTES, decimal.getType());
        final LogicalTypes.Decimal decimalType =
                assertInstanceOf(LogicalTypes.Decimal.class, decimal.getLogicalType());
        assertEquals(12, decimalType.getPrecision());
        assertEquals(3, decimalType.getScale());
    }

    @Test
    void testConvertToSchemaWrapsNullableTypeInUnion() {
        final Schema nullableInt =
                AvroSchemaConverter.convertToSchema(DataTypes.INT().nullable().getLogicalType());
        assertEquals(Schema.Type.UNION, nullableInt.getType());
        assertEquals(2, nullableInt.getTypes().size());
        assertEquals(Schema.Type.NULL, nullableInt.getTypes().get(0).getType());
        assertEquals(Schema.Type.INT, nullableInt.getTypes().get(1).getType());

        final Schema nonNullableInt =
                AvroSchemaConverter.convertToSchema(DataTypes.INT().notNull().getLogicalType());
        assertEquals(Schema.Type.INT, nonNullableInt.getType());
    }

    @Test
    void testConvertToSchemaMapsTimeAndRejectsTooHighPrecision() {
        final Schema time =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIME(3).notNull().getLogicalType());
        assertEquals(Schema.Type.INT, time.getType());
        assertEquals("time-millis", time.getLogicalType().getName());

        final IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                AvroSchemaConverter.convertToSchema(
                                        DataTypes.TIME(6).notNull().getLogicalType()));
        assertTrue(exception.getMessage().contains("precision"));
    }

    @Test
    void testConvertToSchemaMapsTimestampsWithLegacyMapping() {
        final Schema timestamp =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP(3).notNull().getLogicalType());
        assertEquals(Schema.Type.LONG, timestamp.getType());
        assertEquals("timestamp-millis", timestamp.getLogicalType().getName());

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        AvroSchemaConverter.convertToSchema(
                                DataTypes.TIMESTAMP(6).notNull().getLogicalType()));
    }

    @Test
    void testConvertToSchemaMapsTimestampsWithoutLegacyMapping() {
        final Schema millis =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP(3).notNull().getLogicalType(), false);
        assertEquals(Schema.Type.LONG, millis.getType());
        assertEquals("local-timestamp-millis", millis.getLogicalType().getName());

        final Schema micros =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP(6).notNull().getLogicalType(), false);
        assertEquals(Schema.Type.LONG, micros.getType());
        assertEquals("local-timestamp-micros", micros.getLogicalType().getName());

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        AvroSchemaConverter.convertToSchema(
                                DataTypes.TIMESTAMP(9).notNull().getLogicalType(), false));
    }

    @Test
    void testConvertToSchemaMapsLocalZonedTimestamps() {
        assertThrows(
                UnsupportedOperationException.class,
                () ->
                        AvroSchemaConverter.convertToSchema(
                                DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(3)
                                        .notNull()
                                        .getLogicalType(),
                                true));

        final Schema millis =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(3).notNull().getLogicalType(),
                        false);
        assertEquals(Schema.Type.LONG, millis.getType());
        assertEquals("timestamp-millis", millis.getLogicalType().getName());

        final Schema micros =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(6).notNull().getLogicalType(),
                        false);
        assertEquals(Schema.Type.LONG, micros.getType());
        assertEquals("timestamp-micros", micros.getLogicalType().getName());

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        AvroSchemaConverter.convertToSchema(
                                DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(9)
                                        .notNull()
                                        .getLogicalType(),
                                false));
    }

    @Test
    void testConvertToSchemaMapsArrayAndElementNullability() {
        final ArrayType arrayType =
                (ArrayType)
                        DataTypes.ARRAY(DataTypes.BIGINT().notNull())
                                .notNull()
                                .getLogicalType();

        final Schema array = AvroSchemaConverter.convertToSchema(arrayType);
        assertEquals(Schema.Type.ARRAY, array.getType());
        assertEquals(Schema.Type.LONG, array.getElementType().getType());

        final Schema nullableElements =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.ARRAY(DataTypes.STRING()).notNull().getLogicalType());
        assertEquals(Schema.Type.ARRAY, nullableElements.getType());
        assertEquals(Schema.Type.UNION, nullableElements.getElementType().getType());
        assertEquals(
                Schema.Type.NULL,
                nullableElements.getElementType().getTypes().get(0).getType());
        assertEquals(
                Schema.Type.STRING,
                nullableElements.getElementType().getTypes().get(1).getType());
    }

    @Test
    void testConvertToSchemaMapsMapAndMultiset() {
        final Schema map =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.MAP(DataTypes.STRING().notNull(), DataTypes.INT().notNull())
                                .notNull()
                                .getLogicalType());
        assertEquals(Schema.Type.MAP, map.getType());
        assertEquals(Schema.Type.INT, map.getValueType().getType());

        final Schema multiset =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.MULTISET(DataTypes.STRING().notNull())
                                .notNull()
                                .getLogicalType());
        assertEquals(Schema.Type.MAP, multiset.getType());
        assertEquals(Schema.Type.UNION, multiset.getValueType().getType());
        assertEquals(Schema.Type.NULL, multiset.getValueType().getTypes().get(0).getType());
        assertEquals(Schema.Type.INT, multiset.getValueType().getTypes().get(1).getType());
    }

    @Test
    void testConvertToSchemaRejectsNonStringMapKeys() {
        final MapType mapType =
                new MapType(
                        DataTypes.INT().notNull().getLogicalType(),
                        DataTypes.STRING().notNull().getLogicalType());

        final UnsupportedOperationException exception =
                assertThrows(
                        UnsupportedOperationException.class,
                        () -> AvroSchemaConverter.convertToSchema(mapType));
        assertTrue(exception.getMessage().contains("non-string as key type"));
    }

    @Test
    void testConvertToSchemaRejectsUnsupportedLogicalTypes() {
        final LogicalType rawType =
                new TypeInformationRawType<>(false, Types.GENERIC(Object.class));
        final UnsupportedOperationException rawException =
                assertThrows(
                        UnsupportedOperationException.class,
                        () -> AvroSchemaConverter.convertToSchema(rawType));
        assertTrue(rawException.getMessage().contains("Unsupported to derive Schema for type"));

        assertThrows(
                UnsupportedOperationException.class,
                () ->
                        AvroSchemaConverter.convertToSchema(
                                DataTypes.TIMESTAMP_WITH_TIME_ZONE(3)
                                        .notNull()
                                        .getLogicalType()));
    }

    @Test
    void testExtractValueTypeToAvroMap() {
        final LogicalType valueType = DataTypes.BIGINT().notNull().getLogicalType();
        final MapType mapType =
                new MapType(DataTypes.STRING().notNull().getLogicalType(), valueType);
        assertEquals(valueType, AvroSchemaConverter.extractValueTypeToAvroMap(mapType));

        final MultisetType multisetType =
                new MultisetType(DataTypes.STRING().notNull().getLogicalType());
        final LogicalType multisetValue =
                AvroSchemaConverter.extractValueTypeToAvroMap(multisetType);
        assertInstanceOf(IntType.class, multisetValue);
        assertTrue(multisetValue.isNullable());

        final MapType invalidMapType =
                new MapType(
                        DataTypes.INT().notNull().getLogicalType(),
                        DataTypes.STRING().notNull().getLogicalType());
        assertThrows(
                UnsupportedOperationException.class,
                () -> AvroSchemaConverter.extractValueTypeToAvroMap(invalidMapType));
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static void assertConvertedSchemaType(DataType dataType, Schema.Type expectedType) {
        final Schema schema = AvroSchemaConverter.convertToSchema(dataType.getLogicalType());
        assertEquals(expectedType, schema.getType(), "unexpected schema for " + dataType);
    }
}
