import org.apache.flink.core.fs.Path;
import org.apache.flink.formats.parquet.vector.ParquetColumnarRowSplitReader;
import org.apache.flink.formats.parquet.vector.ParquetSplitReaderUtil;
import org.apache.flink.table.data.columnar.ColumnarRowData;
import org.apache.flink.table.types.logical.*;
import org.apache.hadoop.conf.Configuration;
import org.apache.parquet.example.data.Group;
import org.apache.parquet.example.data.simple.SimpleGroupFactory;
import org.apache.parquet.hadoop.ParquetWriter;
import org.apache.parquet.hadoop.example.ExampleParquetWriter;
import org.apache.parquet.hadoop.metadata.CompressionCodecName;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.MessageTypeParser;
import java.nio.file.Files;
import java.util.*;

public class Probe2 {
  public static void main(String[] a) throws Exception {
    java.nio.file.Path dir = Files.createTempDirectory("pq");
    java.nio.file.Path file = dir.resolve("data.parquet");
    MessageType schema = MessageTypeParser.parseMessageType("message test { required int32 id; optional binary name (UTF8); }");
    Configuration conf = new Configuration();
    try (ParquetWriter<Group> w = ExampleParquetWriter.builder(new org.apache.hadoop.fs.Path(file.toUri())).withType(schema).withConf(conf).withCompressionCodec(CompressionCodecName.UNCOMPRESSED).build()) {
      SimpleGroupFactory f = new SimpleGroupFactory(schema);
      Group g1 = f.newGroup(); g1.add("id", 1); g1.add("name", "alice"); w.write(g1);
      Group g2 = f.newGroup(); g2.add("id", 2); w.write(g2);
      Group g3 = f.newGroup(); g3.add("id", 3); g3.add("name", "carol"); w.write(g3);
    }
    DataType[] types = new DataType[]{DataType.of(new IntType()), DataType.of(new VarCharType()), DataType.of(new VarCharType())};
    String[] names = new String[]{"id","name","part"};
    Map<String,Object> parts = new HashMap<>(); parts.put("part","p1");
    try (ParquetColumnarRowSplitReader r = ParquetSplitReaderUtil.genPartColumnarRowReader(false, true, conf, names, types, parts, new int[]{0,1,2}, 2, new Path(file.toUri()), 0, Files.size(file))) {
      while (!r.reachedEnd()) {
        ColumnarRowData row = r.nextRecord();
        System.out.println(row.getInt(0)+" / "+(row.isNullAt(1)?null:row.getString(1))+" / "+row.getString(2));
      }
    }
    System.out.println("OK");
  }
}
EOF
