    @Test
    void testCreateVectorFromConstantForCharacterAndBinaryTypes() {
        int batchSize = 3;

        ColumnVector stringVector = createVectorFromConstant(new VarCharType(), "hello", batchSize);
        HeapBytesVector stringHeap = assertInstanceOf(HeapBytesVector.class, stringVector);
        for (int i = 0; i < batchSize; i++) {
            assertFalse(stringHeap.isNullAt(i));
            assertArrayEquals("hello".getBytes(StandardCharsets.UTF_8), stringHeap.getBytes(i).getBytes());
        }

        byte[] binary = new byte[] {1, 2, 3, -1};
        ColumnVector binaryVector = createVectorFromConstant(new VarBinaryType(), binary, batchSize);
        HeapBytesVector binaryHeap = assertInstanceOf(HeapBytesVector.class, binaryVector);
        for (int i = 0; i < batchSize; i++) {
            assertArrayEquals(binary, binaryHeap.getBytes(i).getBytes());
        }

        ColumnVector charVector = createVectorFromConstant(new CharType(4), null, batchSize);
        assertAllNull(charVector, batchSize);
    }

    @Test
    void testCreateVectorFromConstantConvertsNumberTypes() {
        int batchSize = 2;

        HeapBooleanVector bool =
                assertInstanceOf(
                        HeapBooleanVector.class,
                        createVectorFromConstant(new BooleanType(), Boolean.TRUE, batchSize));
        HeapByteVector tiny =
                assertInstanceOf(
                        HeapByteVector.class,
                        createVectorFromConstant(new TinyIntType(), (short) 7, batchSize));
        HeapShortVector small =
                assertInstanceOf(
                        HeapShortVector.class,
                        createVectorFromConstant(new SmallIntType(), 300, batchSize));
        HeapIntVector integer =
                assertInstanceOf(
                        HeapIntVector.class,
                        createVectorFromConstant(new IntType(), 42L, batchSize));
        HeapLongVector bigint =
                assertInstanceOf(
                        HeapLongVector.class,
                        createVectorFromConstant(new BigIntType(), 12345, batchSize));
        HeapFloatVector floatVector =
                assertInstanceOf(
                        HeapFloatVector.class,
                        createVectorFromConstant(new FloatType(), 1.5d, batchSize));
        HeapDoubleVector doubleVector =
                assertInstanceOf(
                        HeapDoubleVector.class,
                        createVectorFromConstant(new DoubleType(), 2.5f, batchSize));

        for (int i = 0; i < batchSize; i++) {
            assertTrue(bool.getBoolean(i));
            assertEquals((byte) 7, tiny.getByte(i));
            assertEquals((short) 300, small.getShort(i));
            assertEquals(42, integer.getInt(i));
            assertEquals(12345L, bigint.getLong(i));
            assertEquals(1.5f, floatVector.getFloat(i));
            assertEquals(2.5d, doubleVector.getDouble(i));
        }
    }

