        ColumnVector decimal64 =
                createVectorFromConstant(
                        new DecimalType(15, 2), new BigDecimal("1234567890123.45"), batchSize);
        ParquetDecimalVector decimal64Vector =
                assertInstanceOf(ParquetDecimalVector.class, decimal64);
        assertInstanceOf(HeapLongVector.class, decimal64Vector.getVector());
        assertEquals(
                DecimalData.fromBigDecimal(new BigDecimal("1234567890123.45"), 15, 2),
