    @Test
    void testLookupColumnByNameExactCaseInsensitiveAndMissing() {
        MessageColumnIO columnIO =
                columnIO(
                        parse(
                                "message test { required int32 id; optional binary Name (UTF8); }"));

        ColumnIO exact = lookupColumnByName(columnIO, "id");
        assertEquals("id", exact.getName());
        assertSame(exact, columnIO.getChild("id"));

        ColumnIO caseInsensitive = lookupColumnByName(columnIO, "name");
        assertEquals("Name", caseInsensitive.getName());
        assertSame(caseInsensitive, columnIO.getChild("Name"));

        FlinkRuntimeException exception =
                assertThrows(
                        FlinkRuntimeException.class,
                        () -> lookupColumnByName(columnIO, "does_not_exist"));
        assertEquals("Can not find column io for parquet reader.", exception.getMessage());
    }

    @Test
    void testGetMapKeyValueColumnDescendsThroughSingleChildGroups() {
        MessageType schema =
                parse(
                        "message test { optional group mp (MAP) { repeated group key_value {"
                                + " required binary key (UTF8); optional int32 value; } } }");
        GroupColumnIO mapColumn = (GroupColumnIO) columnIO(schema).getChild("mp");

        GroupColumnIO keyValue = getMapKeyValueColumn(mapColumn);
        assertEquals("key_value", keyValue.getName());
        assertEquals(2, keyValue.getChildrenCount());
        assertSame(mapColumn.getChild(0), keyValue);

        MessageType chained =
                parse(
                        "message test { optional group outer { optional group inner {"
                                + " required int32 a; required int32 b; } } }");
        GroupColumnIO outer = (GroupColumnIO) columnIO(chained).getChild("outer");
        GroupColumnIO inner = getMapKeyValueColumn(outer);
        assertEquals("inner", inner.getName());
        assertEquals(2, inner.getChildrenCount());
    }

    @Test
