    @Test
    void testBuildFieldsListForPrimitivesAndNestedRow() {
        MessageType schema =
                parse(
                        "message test { required int32 id; optional binary name (UTF8);"
                                + " optional group nested { required int64 value; } }");
        RowType rowType =
                RowType.of(
                        new LogicalType[] {
                            new IntType(false),
                            new VarCharType(),
                            RowType.of(
                                    new LogicalType[] {new BigIntType(false)},
                                    new String[] {"value"})
                        },
                        new String[] {"id", "name", "nested"});

        List<ParquetField> fields =
                buildFieldsList(rowType.getFields(), rowType.getFieldNames(), columnIO(schema));

        assertEquals(3, fields.size());

        ParquetPrimitiveField id = assertInstanceOf(ParquetPrimitiveField.class, fields.get(0));
        assertTrue(id.isRequired());
        assertEquals(new IntType(false), id.getType());
        assertEquals(0, id.getRepetitionLevel());
        assertEquals(0, id.getDefinitionLevel());
        assertArrayEquals(new String[] {"id"}, id.getDescriptor().getPath());

        ParquetPrimitiveField name = assertInstanceOf(ParquetPrimitiveField.class, fields.get(1));
        assertFalse(name.isRequired());
        assertEquals(new VarCharType(), name.getType());
        assertEquals(0, name.getRepetitionLevel());
        assertEquals(1, name.getDefinitionLevel());
        assertArrayEquals(new String[] {"name"}, name.getDescriptor().getPath());

        ParquetGroupField nested = assertInstanceOf(ParquetGroupField.class, fields.get(2));
        assertFalse(nested.isRequired());
        assertInstanceOf(RowType.class, nested.getType());
        assertEquals(1, nested.getChildren().size());
        ParquetPrimitiveField value =
                assertInstanceOf(ParquetPrimitiveField.class, nested.getChildren().get(0));
        assertTrue(value.isRequired());
        assertArrayEquals(new String[] {"nested", "value"}, value.getDescriptor().getPath());
    }

