    // ----------------------------------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------------------------------

    private static MessageType parse(String schema) {
        return MessageTypeParser.parseMessageType(schema);
    }

    private static MessageColumnIO columnIO(MessageType schema) {
        return new ColumnIOFactory().getColumnIO(schema);
    }

    private static PageReadStore pages() {
        PageReadStore pages = mock(PageReadStore.class);
        PageReader pageReader = mock(PageReader.class);
        when(pageReader.readDictionaryPage()).thenReturn(null);
        when(pageReader.getTotalValueCount()).thenReturn(1L);
        when(pages.getPageReader(any(ColumnDescriptor.class))).thenReturn(pageReader);
        return pages;
    }

    private static void assertAllNull(ColumnVector vector, int batchSize) {
        assertNotNull(vector);
        for (int i = 0; i < batchSize; i++) {
            assertTrue(vector.isNullAt(i), "Expected null at row " + i);
        }
    }

    private static java.nio.file.Path writeThreeRowParquetFile(java.nio.file.Path dir)
            throws Exception {
        java.nio.file.Path file = dir.resolve("data.parquet");
        MessageType schema =
                parse("message test { required int32 id; optional binary name (UTF8); }");
        Configuration conf = new Configuration();

        try (ParquetWriter<Group> writer =
                ExampleParquetWriter.builder(new org.apache.hadoop.fs.Path(file.toUri()))
                        .withType(schema)
                        .withConf(conf)
                        .withCompressionCodec(CompressionCodecName.UNCOMPRESSED)
                        .build()) {
            SimpleGroupFactory factory = new SimpleGroupFactory(schema);

            Group first = factory.newGroup();
            first.add("id", 1);
            first.add("name", "alice");
            writer.write(first);

            Group second = factory.newGroup();
            second.add("id", 2);
            writer.write(second);

            Group third = factory.newGroup();
            third.add("id", 3);
            third.add("name", "carol");
            writer.write(third);
        }
        return file;
    }
