    }

    @Test
    void testCreateWritableColumnVectorForArrayOfRow() {
        RowType nestedRow =
                RowType.of(
                        new LogicalType[] {new IntType(), new VarCharType()},
                        new String[] {"x", "y"});
        RowType rowType =
                RowType.of(
