        assertEquals(2, element.getFields().length);
        assertInstanceOf(HeapIntVector.class, element.getFields()[0]);
        assertInstanceOf(HeapBytesVector.class, element.getFields()[1]);
    }

    // ----------------------------------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------------------------------

    private static MessageType parse(String schema) {
        return MessageTypeParser.parseMessageType(schema);
    }

    private static MessageColumnIO columnIO(MessageType schema) {
        return new ColumnIOFactory().getColumnIO(schema);
    }

    private static PageReadStore pages() {
        PageReader pageReader =
                new PageReader() {
                    @Override
                    public DictionaryPage readDictionaryPage() {
                        return null;
