    private static CheckpointException checkpointFailure(CompletableFuture<?> future) {
        try {
            future.get(10, TimeUnit.SECONDS);
            fail("The future should have completed exceptionally.");
            return null;
        } catch (ExecutionException e) {
            assertThat(e.getCause()).isInstanceOf(CheckpointException.class);
            return (CheckpointException) e.getCause();
        } catch (Exception e) {
            throw new AssertionError("Unexpected exception while waiting for failure", e);
        }
    }

    private static TestCheckpointPlan createPlan(Execution execution) {
        return new TestCheckpointPlan(execution);
    }

    private static final class TestContext implements AutoCloseable {
        private final JobID job = new JobID();
        private final ExecutionAttemptID attemptId = new ExecutionAttemptID();
        private final ManualClock clock = new ManualClock();
        private final TestingScheduledExecutor timer = new TestingScheduledExecutor();
        private final StandaloneCompletedCheckpointStore store =
                new StandaloneCompletedCheckpointStore(2);
        private final CheckpointsCleaner checkpointsCleaner = new CheckpointsCleaner(false);
        private final CheckpointStatsTracker statsTracker = mock(CheckpointStatsTracker.class);
        private final CheckpointStorage storage = mock(CheckpointStorage.class);
        private final CheckpointStorageAccess storageAccess = mock(CheckpointStorageAccess.class);
        private final CheckpointStorageLocation storageLocation =
                mock(CheckpointStorageLocation.class);
        private final CheckpointMetadataOutputStream metadataOutputStream =
                mock(CheckpointMetadataOutputStream.class);
        private final CompletedCheckpointStorageLocation completedStorageLocation =
                mock(CompletedCheckpointStorageLocation.class);
        private final StreamStateHandle metadataHandle = mock(StreamStateHandle.class);
        private final Execution execution = mock(Execution.class);
        private final ExecutionVertex executionVertex = mock(ExecutionVertex.class);
        private final ExecutionJobVertex executionJobVertex = mock(ExecutionJobVertex.class);
        private final CheckpointCoordinator coordinator;

        private TestContext(CheckpointCoordinatorConfiguration configuration) {
            try {
                when(storage.createCheckpointStorage(job)).thenReturn(storageAccess);
                when(storageAccess.initializeLocationForCheckpoint(anyLong()))
                        .thenReturn(storageLocation);
                when(storageAccess.initializeLocationForSavepoint(anyLong(), any()))
                        .thenReturn(storageLocation);
                when(storageLocation.getLocationReference())
                        .thenReturn(CheckpointStorageLocationReference.getDefault());
                when(storageLocation.createMetadataOutputStream()).thenReturn(metadataOutputStream);
                when(metadataOutputStream.closeAndFinalizeCheckpoint())
                        .thenReturn(completedStorageLocation);
                when(completedStorageLocation.getExternalPointer()).thenReturn("test-location");
                when(completedStorageLocation.getMetadataHandle()).thenReturn(metadataHandle);

                when(execution.getAttemptId()).thenReturn(attemptId);
                when(execution.getVertex()).thenReturn(executionVertex);
                when(execution.triggerCheckpoint(anyLong(), anyLong(), any()))
                        .thenReturn(CompletableFuture.completedFuture(Acknowledge.get()));
                when(execution.triggerSynchronousSavepoint(anyLong(), anyLong(), any()))
                        .thenReturn(CompletableFuture.completedFuture(Acknowledge.get()));
                when(executionVertex.getJobVertex()).thenReturn(executionJobVertex);
                when(executionJobVertex.getOperatorIDs()).thenReturn(emptyList());
                when(statsTracker.reportPendingCheckpoint(anyLong(), anyLong(), any(), any()))
                        .thenReturn(null);

                coordinator =
                        new CheckpointCoordinator(
                                job,
                                configuration,
                                emptyList(),
                                new StandaloneCheckpointIDCounter(),
                                store,
                                storage,
                                Runnable::run,
                                checkpointsCleaner,
                                timer,
                                new CheckpointFailureManager(
                                        CheckpointFailureManager
                                                .UNLIMITED_TOLERABLE_FAILURE_NUMBER,
                                        new NoOpFailJobCallback()),
                                () ->
                                        CompletableFuture.completedFuture(
                                                createPlan(execution)),
                                clock,
                                statsTracker,
                                VertexFinishedStateChecker::new);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        private boolean acknowledge(long checkpointId) throws CheckpointException {
            return coordinator.receiveAcknowledgeMessage(
                    new AcknowledgeCheckpoint(job, attemptId, checkpointId), "test-location");
        }

        @Override
        public void close() throws Exception {
            if (!coordinator.isShutdown()) {
                coordinator.shutdown();
            }
        }
    }

