    /**
     * A deterministic {@link ScheduledExecutor} that executes ordinary tasks immediately and keeps
     * scheduled tasks until the test explicitly runs them.
     */
    private static final class TestingScheduledExecutor implements ScheduledExecutor {
        private final Deque<TestScheduledTask> tasks = new ArrayDeque<>();
        private long lastDelayMillis = -1L;

        @Override
        public void execute(Runnable command) {
            command.run();
        }

        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
            lastDelayMillis = unit.toMillis(delay);
            TestScheduledTask task = new TestScheduledTask(command);
            tasks.add(task);
            return task;
        }

        @Override
        public <V> ScheduledFuture<V> schedule(
                Callable<V> callable, long delay, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        @Override
        public ScheduledFuture<?> scheduleAtFixedRate(
                Runnable command, long initialDelay, long period, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        @Override
        public ScheduledFuture<?> scheduleWithFixedDelay(
                Runnable command, long initialDelay, long delay, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        private int getScheduledTaskCount() {
            return tasks.size();
        }

        private long getLastDelayMillis() {
            return lastDelayMillis;
        }

        private void runNextScheduledTask() {
            TestScheduledTask task = tasks.pollFirst();
            assertThat(task).isNotNull();
            task.run();
        }
    }

    private static final class TestScheduledTask
            implements ScheduledFuture<Object>, Runnable {
        private final Runnable command;
        private boolean cancelled;

        private TestScheduledTask(Runnable command) {
            this.command = command;
        }

        @Override
        public void run() {
            if (!cancelled) {
                command.run();
            }
        }

        @Override
        public long getDelay(TimeUnit unit) {
            return 0L;
        }

        @Override
        public int compareTo(Delayed other) {
            return Long.compare(getDelay(TimeUnit.NANOSECONDS), other.getDelay(TimeUnit.NANOSECONDS));
        }

        @Override
        public boolean cancel(boolean mayInterruptIfRunning) {
            cancelled = true;
            return true;
        }

        @Override
        public boolean isCancelled() {
            return cancelled;
        }

        @Override
        public boolean isDone() {
            return cancelled;
        }

        @Override
        public Object get() {
            return null;
        }

        @Override
        public Object get(long timeout, TimeUnit unit) {
            return null;
        }
    }
