    private static final class TestingScheduledExecutor implements ScheduledExecutor {
        private final Deque<TestScheduledTask> tasks = new ArrayDeque<>();
        private long lastDelayMillis = -1L;

        @Override
        public void execute(Runnable command) {
            command.run();
        }

        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
            lastDelayMillis = unit.toMillis(delay);
            TestScheduledTask task = new TestScheduledTask(command);
            tasks.add(task);
            return task;
        }

