    @Test
    void testMasterStateRoundTrip() throws Exception {
        final MasterState state = new MasterState("the-master-state", new byte[] {1, 2, 3}, 42);

        final byte[] data =
                TestSerializer.toBytes(
                        dos -> TestSerializer.INSTANCE.serializeMasterState(state, dos));
        final MasterState deserialized =
                TestSerializer.fromBytes(data, TestSerializer.INSTANCE::deserializeMasterState);

        assertThat(deserialized.name()).isEqualTo("the-master-state");
        assertThat(deserialized.version()).isEqualTo(42);
        assertThat(deserialized.bytes()).containsExactly(1, 2, 3);
    }

    @Test
    void testMasterStateWithEmptyNameAndPayloadRoundTrip() throws Exception {
        final MasterState state = new MasterState("", new byte[0], 0);

        final byte[] data =
                TestSerializer.toBytes(
