        assertThat(deserialized.name()).isEmpty();
        assertThat(deserialized.version()).isZero();
        assertThat(deserialized.bytes()).isEmpty();
    }

    @Test
    void testDeserializeMasterStateRejectsWrongMagicNumber() throws Exception {
        final byte[] data =
                TestSerializer.toBytes(
                        dos -> {
                            dos.writeInt(0x12345678);
