    /**
     * Minimal serializer that pins down the operator state part of the metadata format, so that the
     * behaviour of {@link MetadataV2V3SerializerBase} can be exercised end to end.
     */
    private static final class TestSerializer extends MetadataV2V3SerializerBase {

        private static final TestSerializer INSTANCE = new TestSerializer();

        @Override
        protected void serializeOperatorState(
                OperatorState operatorState, DataOutputStream dos, SerializationContext context)
                throws IOException {
            dos.writeUTF(operatorState.getOperatorName().orElse(""));
            dos.writeUTF(operatorState.getOperatorUid().orElse(""));
            dos.writeInt(operatorState.getParallelism());
            dos.writeInt(operatorState.getMaxParallelism());
            dos.writeInt(operatorState.getNumberCollectedStates());
            for (Map.Entry<Integer, OperatorSubtaskState> subtaskState :
                    operatorState.getSubtaskStates().entrySet()) {
                dos.writeInt(subtaskState.getKey());
                serializeSubtaskState(subtaskState.getValue(), dos, context);
            }
        }

        @Override
        protected OperatorState deserializeOperatorState(
                DataInputStream dis, DeserializationContext context) throws IOException {
            final String operatorName = dis.readUTF();
            final String operatorUid = dis.readUTF();
            final int parallelism = dis.readInt();
            final int maxParallelism = dis.readInt();
            final int numberOfStates = dis.readInt();

            final OperatorState operatorState =
                    new OperatorState(
                            operatorName.isEmpty() ? null : operatorName,
                            operatorUid.isEmpty() ? null : operatorUid,
                            new OperatorID(),
                            parallelism,
                            maxParallelism);

            for (int i = 0; i < numberOfStates; i++) {
                final int subtaskIndex = dis.readInt();
                operatorState.putState(subtaskIndex, deserializeSubtaskState(dis, context));
            }
            return operatorState;
        }

        // --- byte plumbing ---

        @FunctionalInterface
        private interface ThrowingWriter {
            void write(DataOutputStream dos) throws IOException;
        }

        @FunctionalInterface
        private interface ThrowingReader<T> {
            T read(DataInputStream dis) throws IOException;
        }

        static DataOutputStream output() {
            return new DataOutputStream(new ByteArrayOutputStream());
        }

        static DataInputStream input(byte[] data) {
            return new DataInputStream(new ByteArrayInputStream(data));
        }

        static byte[] toBytes(ThrowingWriter writer) throws IOException {
            final ByteArrayOutputStream baos = new ByteArrayOutputStream();
            try (DataOutputStream dos = new DataOutputStream(baos)) {
                writer.write(dos);
            }
            return baos.toByteArray();
        }

        static <T> T fromBytes(byte[] data, ThrowingReader<T> reader) throws IOException {
            try (DataInputStream dis = input(data)) {
                final T result = reader.read(dis);
                assertThat(dis.available())
                        .as("bytes left unread after deserialization")
                        .isZero();
                return result;
            }
        }

        static SerializationContext withoutExclusiveDir() {
            return SerializationContext.withoutExclusiveDir();
        }

        static byte[] keyedHandleBytes(KeyedStateHandle handle, SerializationContext context)
                throws IOException {
            return toBytes(dos -> serializeKeyedStateHandle(handle, dos, context));
        }

        static KeyedStateHandle keyedHandle(byte[] data, @Nullable DeserializationContext context)
                throws IOException {
            return fromBytes(data, dis -> deserializeKeyedStateHandle(dis, context));
        }

        static byte[] streamHandleBytes(StreamStateHandle handle, SerializationContext context)
                throws IOException {
            return toBytes(dos -> serializeStreamStateHandle(handle, dos, context));
        }

        static StreamStateHandle streamHandle(byte[] data, @Nullable DeserializationContext context)
                throws IOException {
            return fromBytes(data, dis -> deserializeStreamStateHandle(dis, context));
        }

        static byte[] operatorHandleBytes(
                OperatorStateHandle handle, SerializationContext context) throws IOException {
            return toBytes(dos -> INSTANCE.serializeOperatorStateHandle(handle, dos, context));
        }

        static OperatorStateHandle operatorHandle(
                byte[] data, @Nullable DeserializationContext context) throws IOException {
            return fromBytes(data, dis -> INSTANCE.deserializeOperatorStateHandle(dis, context));
        }
    }
