    private java.nio.file.Path createCheckpointDirectory() throws IOException {
        final java.nio.file.Path checkpointDir = temporaryDirectory.resolve("chk-1");
        Files.createDirectories(checkpointDir);
        final java.nio.file.Path metadataFile = checkpointDir.resolve("_metadata");
        if (!Files.exists(metadataFile)) {
            Files.createFile(metadataFile);
        }
        return checkpointDir;
    }

