    /**
     * Obtains a production {@link SequenceNumber} instance. The factory method is package private
     * in the changelog package, so it is accessed reflectively.
     */
    private static SequenceNumber sequenceNumberOf(long number) {
        try {
            final Method of = SequenceNumber.class.getDeclaredMethod("of", long.class);
            of.setAccessible(true);
            return (SequenceNumber) of.invoke(null, number);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("Could not create a SequenceNumber", e);
        }
    }

