/** Tests for {@link CompactingHashTable}. */
class CompactingHashTableTests {

    private static final int SEGMENT_SIZE = 4096;

    private final List<CompactingHashTable<TestRecord>> tables = new ArrayList<>();

    @AfterEach
    void closeTables() throws IOException {
        for (CompactingHashTable<TestRecord> table : tables) {
            table.close();
        }
        tables.clear();
    }

    @Test
    void constructorRejectsNullAndInsufficientMemory() {
        assertThrows(
                NullPointerException.class,
                () ->
                        new CompactingHashTable<TestRecord>(
                                TestRecordSerializer.INSTANCE,
                                new TestRecordComparator(false),
                                null));

        IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                new CompactingHashTable<TestRecord>(
                                        TestRecordSerializer.INSTANCE,
                                        new TestRecordComparator(false),
                                        memorySegments(32, SEGMENT_SIZE)));
        assertTrue(exception.getMessage().contains("at least 33"));
    }

    @Test
    void constructorRejectsInvalidSegmentSizes() {
        IllegalArgumentException notPowerOfTwo =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                new CompactingHashTable<TestRecord>(
                                        TestRecordSerializer.INSTANCE,
                                        new TestRecordComparator(false),
                                        memorySegments(33, 1000)));
        assertTrue(notPowerOfTwo.getMessage().contains("power of 2"));

        IllegalArgumentException tooSmall =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                new CompactingHashTable<TestRecord>(
                                        TestRecordSerializer.INSTANCE,
                                        new TestRecordComparator(false),
                                        memorySegments(33, 64)));
        assertTrue(tooSmall.getMessage().contains("at least 128"));
    }

    @Test
    void openAndCloseControlAccessToMemory() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(33, new TestRecordComparator(false));

        table.open();
        assertThrows(IllegalStateException.class, table::open);
        IllegalStateException openException =
                assertThrows(IllegalStateException.class, table::getFreeMemory);
        assertTrue(openException.getMessage().contains("while join is open"));

        table.close();
        assertEquals(33, table.getFreeMemory().size());

        // Closing is idempotent and must not return the same memory twice.
        table.close();
        assertEquals(33, table.getFreeMemory().size());

        // The table can be opened again and still owns exactly its original memory.
        table.open();
        table.close();
        assertEquals(33, table.getFreeMemory().size());
    }

    @Test
    void operationsOnClosedTableDoNotChangeItsContents() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(33, new TestRecordComparator(false));
        TestRecord initial = new TestRecord(1, 11L);

        // Mutations before open are ignored.
        table.insert(initial);
        table.insertOrReplaceRecord(initial);
        assertNull(table.getEntryIterator().next());

        table.open();
        assertTrue(collectRecords(table).isEmpty());
        table.insert(initial);
        assertEquals(11L, collectRecords(table).get(1));

        table.close();
        table.insert(new TestRecord(2, 22L));
        table.insertOrReplaceRecord(new TestRecord(2, 33L));
        assertNull(table.getEntryIterator().next());
        assertNull(newProber(table, false).getMatchFor(new TestRecord(1, 0L)));

        // Reopening starts with an empty table and the same memory pool.
        table.open();
        assertTrue(collectRecords(table).isEmpty());
        table.close();
        assertEquals(33, table.getFreeMemory().size());
    }

    @Test
    void insertsAndFindsRecordsWithAndWithoutReuse() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(false));
        table.open();

        Map<Integer, Long> expected = new TreeMap<>();
        for (int i = 0; i < 250; i++) {
            long value = 10_000L + i;
            table.insert(new TestRecord(i, value));
            expected.put(i, value);
        }

        assertEquals(expected, collectRecords(table));

        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, false);
        for (Map.Entry<Integer, Long> entry : expected.entrySet()) {
            TestRecord probe = new TestRecord(entry.getKey(), -1L);

            TestRecord match = prober.getMatchFor(probe);
            assertNotNull(match);
            assertEquals(entry.getKey().intValue(), match.key);
            assertEquals(entry.getValue().longValue(), match.value);

            TestRecord reuse = new TestRecord(-1, -1L);
            TestRecord reusedMatch = prober.getMatchFor(probe, reuse);
            assertSame(reuse, reusedMatch);
            assertEquals(entry.getKey().intValue(), reusedMatch.key);
            assertEquals(entry.getValue().longValue(), reusedMatch.value);
        }

        assertNull(prober.getMatchFor(new TestRecord(Integer.MIN_VALUE, -1L)));
        assertNull(
                prober.getMatchFor(
                        new TestRecord(Integer.MIN_VALUE, -1L), new TestRecord(-1, -1L)));
    }

    @Test
    void insertOrReplaceUpdatesExistingKeyAndAppendsNewKey() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(false));
        table.open();

        table.insert(new TestRecord(1, 10L));
        table.insert(new TestRecord(2, 20L));
        table.insertOrReplaceRecord(new TestRecord(1, 99L));
        table.insertOrReplaceRecord(new TestRecord(3, 30L));

        Map<Integer, Long> expected = new TreeMap<>();
        expected.put(1, 99L);
        expected.put(2, 20L);
        expected.put(3, 30L);
        assertEquals(expected, collectRecords(table));

        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, false);
        assertEquals(99L, prober.getMatchFor(new TestRecord(1, -1L)).value);
        assertEquals(20L, prober.getMatchFor(new TestRecord(2, -1L)).value);
        assertEquals(30L, prober.getMatchFor(new TestRecord(3, -1L)).value);
    }

    @Test
    void buildTableWithUniqueKeyRetainsLastRecordForDuplicateKeys() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(false));
        table.open();

        table.buildTableWithUniqueKey(
                iterator(
                        new TestRecord(1, 10L),
                        new TestRecord(2, 20L),
                        new TestRecord(1, 30L),
                        new TestRecord(3, 30L),
                        new TestRecord(2, 40L)));

        Map<Integer, Long> expected = new TreeMap<>();
        expected.put(1, 30L);
        expected.put(2, 40L);
        expected.put(3, 30L);
        assertEquals(expected, collectRecords(table));
    }

    @Test
    void updateMatchReplacesMatchedRecordWithoutAddingAnotherEntry() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(false));
        table.open();

        table.insert(new TestRecord(1, 10L));
        table.insert(new TestRecord(2, 20L));

        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, false);
        TestRecord match = prober.getMatchFor(new TestRecord(1, -1L));
        assertNotNull(match);
        assertEquals(10L, match.value);

        prober.updateMatch(new TestRecord(1, 77L));

        Map<Integer, Long> expected = new TreeMap<>();
        expected.put(1, 77L);
        expected.put(2, 20L);
        assertEquals(expected, collectRecords(table));
        assertEquals(77L, prober.getMatchFor(new TestRecord(1, -1L)).value);
    }

    @Test
    void handlesHashCollisionsAndOverflowBuckets() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(true));
        table.open();

        Map<Integer, Long> expected = new TreeMap<>();
        for (int i = 0; i < 400; i++) {
            table.insert(new TestRecord(i, i + 1_000L));
            expected.put(i, i + 1_000L);
        }

        // All these records have the same hash code, so this exercises collision handling and
        // chained overflow buckets.
        assertEquals(expected, collectRecords(table));

        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, true);
        for (int i = 0; i < 400; i += 17) {
            TestRecord result = prober.getMatchFor(new TestRecord(i, -1L));
            assertNotNull(result);
            assertEquals(i, result.key);
            assertEquals(expected.get(i).longValue(), result.value);
        }

        // The modified entry is in an overflow bucket and must replace, not duplicate, the record.
        TestRecord toUpdate = prober.getMatchFor(new TestRecord(211, -1L));
        assertNotNull(toUpdate);
        prober.updateMatch(new TestRecord(211, 42L));
        expected.put(211, 42L);

        assertEquals(expected, collectRecords(table));
        assertEquals(42L, prober.getMatchFor(new TestRecord(211, -1L)).value);
        assertNull(prober.getMatchFor(new TestRecord(-1, -1L)));
    }

    @Test
    void compactingPartitionsPreservesAllLiveRecords() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(true));
        table.open();

        Map<Integer, Long> expected = new TreeMap<>();
        for (int i = 0; i < 300; i++) {
            table.insert(new TestRecord(i, i + 5_000L));
            expected.put(i, i + 5_000L);
        }
        for (int i = 0; i < 300; i += 3) {
            table.insertOrReplaceRecord(new TestRecord(i, i + 9_000L));
            expected.put(i, i + 9_000L);
        }

        table.compactPartitions();

        assertEquals(expected, collectRecords(table));
        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, true);
        for (int i = 0; i < 300; i += 11) {
            TestRecord match = prober.getMatchFor(new TestRecord(i, -1L));
            assertNotNull(match);
            assertEquals(expected.get(i).longValue(), match.value);
        }
    }

    @Test
    void resizingHashTablePreservesAllRecords() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(64, new TestRecordComparator(false));
        table.open();

        Map<Integer, Long> expected = new TreeMap<>();
        for (int i = 0; i < 200; i++) {
            table.insert(new TestRecord(i, i + 7_000L));
            expected.put(i, i + 7_000L);
        }

        assertTrue(table.resizeHashTable());
        assertEquals(expected, collectRecords(table));

        AbstractHashTableProber<TestRecord, TestRecord> prober = newProber(table, false);
        for (int i = 0; i < 200; i += 7) {
            TestRecord match = prober.getMatchFor(new TestRecord(i, -1L));
            assertNotNull(match);
            assertEquals(expected.get(i).longValue(), match.value);
        }
    }

    @Test
    void abortStopsBuildTableWithUniqueKeyFromConsumingInput() throws Exception {
        CompactingHashTable<TestRecord> table = newTable(33, new TestRecordComparator(false));
        table.open();

        CountingIterator input =
                new CountingIterator(
                        new TestRecord(1, 10L),
                        new TestRecord(2, 20L),
                        new TestRecord(3, 30L));

        table.abort();
        table.buildTableWithUniqueKey(input);

        assertEquals(0, input.nextCalls);
        assertTrue(collectRecords(table).isEmpty());
        assertFalse(input.exhausted());
    }

    private CompactingHashTable<TestRecord> newTable(
            int numberOfSegments, TestRecordComparator comparator) {
        CompactingHashTable<TestRecord> table =
                new CompactingHashTable<>(
                        TestRecordSerializer.INSTANCE,
                        comparator,
                        memorySegments(numberOfSegments, SEGMENT_SIZE));
        tables.add(table);
        return table;
    }

    private static AbstractHashTableProber<TestRecord, TestRecord> newProber(
            CompactingHashTable<TestRecord> table, boolean constantHash) {
        return table.getProber(
                new TestRecordComparator(constantHash), new TestRecordPairComparator());
    }

    private static Map<Integer, Long> collectRecords(CompactingHashTable<TestRecord> table)
            throws IOException {
        Map<Integer, Long> result = new TreeMap<>();
        MutableObjectIterator<TestRecord> iterator = table.getEntryIterator();
        TestRecord record;
        while ((record = iterator.next()) != null) {
            Long previous = result.put(record.key, record.value);
            assertNull(previous, "Duplicate entry for key " + record.key);
        }
        return result;
    }

    private static List<MemorySegment> memorySegments(int count, int segmentSize) {
        List<MemorySegment> segments = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            segments.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        }
        return segments;
    }

    private static MutableObjectIterator<TestRecord> iterator(TestRecord... records) {
        return new MutableObjectIterator<TestRecord>() {
            private int index;

            @Override
            public TestRecord next(TestRecord reuse) {
                return next();
            }

