    private static Map<Integer, Long> collectRecords(CompactingHashTable<TestRecord> table)
            throws IOException {
        Map<Integer, Long> result = new TreeMap<>();
        MutableObjectIterator<TestRecord> iterator = table.getEntryIterator();
        TestRecord record;
        while ((record = iterator.next()) != null) {
            Long previous = result.put(record.key, record.value);
            assertNull(previous, "Duplicate entry for key " + record.key);
        }
        return result;
