                    if (fieldContents != null && !(fieldContents instanceof Serializable)) {
                        throw new NonSerializableUserCodeException(
                                "User-defined object "
                                        + userCodeObject
                                        + " ("
                                        + userCodeObject.getClass().getName()
                                        + ") contains non-serializable field "
                                        + f.getName()
                                        + " = "
                                        + f.get(current));
