public void cancel() throws Exception {
    this.running = false;

    if (LOG.isDebugEnabled()) {
        LOG.debug(formatLogString("Cancelling task code"));
    }

    try {
        if (this.driver != null) {
            this.driver.cancel();
        }
    } finally {
        closeLocalStrategiesAndCaches();
    }
