    private Configuration newInvokableConfiguration(boolean forwardOutput) {
        TaskConfig config = new TaskConfig(new Configuration());
        config.setDriver(RecordingDriver.class);
        config.setStubWrapper(new UserCodeClassWrapper<>(RecordingRichFunction.class));
        if (forwardOutput) {
            config.addOutputShipStrategy(ShipStrategyType.FORWARD);
            config.setOutputSerializer(new IntegerSerializerFactory());
        }
        return config.getConfiguration();
    }

