    /** Driver instantiated reflectively by {@link BatchTask#invoke()}. */
    @SuppressWarnings("rawtypes")
    public static class RecordingDriver implements Driver<Function, Object> {

        private static final List<String> EVENTS = new ArrayList<>();
        private static boolean failPrepare;

        private static void reset() {
            EVENTS.clear();
            failPrepare = false;
        }

        @Override
        public void setup(TaskContext<Function, Object> context) {
            EVENTS.add("setup");
        }

        @Override
        public int getNumberOfInputs() {
            return 0;
        }

        @Override
        public int getNumberOfDriverComparators() {
            return 0;
        }

        @Override
        public Class<Function> getStubType() {
            return Function.class;
        }

        @Override
        public void prepare() throws Exception {
            EVENTS.add("prepare");
            if (failPrepare) {
                throw new IllegalStateException("prepare failed");
            }
        }

        @Override
        public void run() throws Exception {
            EVENTS.add("run");
        }

        @Override
        public void cleanup() throws Exception {
            EVENTS.add("cleanup");
        }

        @Override
        public void cancel() throws Exception {
            EVENTS.add("cancel");
        }
    }

    /** Rich user function recording its life-cycle calls. */
    public static class RecordingRichFunction implements RichFunction {

        private static final List<String> EVENTS = new ArrayList<>();
        private static boolean failOpen;
        private static boolean failClose;

        private RuntimeContext runtimeContext;

        private static void reset() {
            EVENTS.clear();
            failOpen = false;
            failClose = false;
        }

        private List<String> getEvents() {
            return EVENTS;
        }

        @Override
        public void open(OpenContext openContext) throws Exception {
            EVENTS.add("open");
            if (failOpen) {
                throw new IllegalStateException("open failed");
            }
        }

        @Override
        public void close() throws Exception {
            EVENTS.add("close");
            if (failClose) {
                throw new IllegalStateException("close failed");
            }
        }

        @Override
        public RuntimeContext getRuntimeContext() {
            return runtimeContext;
        }

        @Override
        public IterationRuntimeContext getIterationRuntimeContext() {
            throw new UnsupportedOperationException();
        }

        @Override
        public void setRuntimeContext(RuntimeContext runtimeContext) {
            this.runtimeContext = runtimeContext;
        }
    }

