    @Test
    void getOutputCollectorCreatesWriterForEveryConfiguredOutputAtTheGivenOffset()
            throws Exception {
        TaskConfig config = new TaskConfig(new Configuration());
        config.addOutputShipStrategy(ShipStrategyType.FORWARD);
        config.addOutputShipStrategy(ShipStrategyType.FORWARD);
        config.setOutputSerializer(new IntegerSerializerFactory());

        ResultPartitionWriter firstWriter = mock(ResultPartitionWriter.class);
        ResultPartitionWriter secondWriter = mock(ResultPartitionWriter.class);
        when(firstWriter.getNumberOfSubpartitions()).thenReturn(1);
        when(secondWriter.getNumberOfSubpartitions()).thenReturn(1);
        when(environment.getWriter(3)).thenReturn(firstWriter);
        when(environment.getWriter(4)).thenReturn(secondWriter);

        List<RecordWriter<?>> eventualOutputs = new ArrayList<>();
        OutputCollector<Integer> collector =
                (OutputCollector<Integer>)
                        BatchTask.getOutputCollector(
                                newTask(), config, classLoader, eventualOutputs, 3, 2);

        assertNotNull(collector);
        assertEquals(2, collector.getWriters().size());
        assertEquals(2, eventualOutputs.size());
        verify(environment).getWriter(3);
        verify(environment).getWriter(4);
    }

