    @Test
    void initOutputsInstantiatesChainedTaskAndReturnsItsCollector() throws Exception {
        TaskConfig config = new TaskConfig(new Configuration());
        config.addOutputShipStrategy(ShipStrategyType.FORWARD);
        config.setOutputSerializer(new IntegerSerializerFactory());
        TaskConfig chainedConfig = new TaskConfig(new Configuration());
        config.addChainedTask(TestChainedDriver.class, chainedConfig, "chained task");

        List<ChainedDriver<?, ?>> chainedTasks = new ArrayList<>();
        Object collector =
                BatchTask.initOutputs(
                        newTask(),
