        doThrow(new IllegalStateException("prepare failed")).when(driver).prepare();
        task.setDriverField(driver);
        task.setChainedTasksField(new ArrayList<>());
        task.setConfigField(new TaskConfig(new Configuration()));

        Exception thrown = assertThrows(Exception.class, task::callRun);

        assertTrue(thrown.getMessage().contains("The data preparation for task 'Test Task'"));
        assertTrue(thrown.getMessage().contains("prepare failed"));
        assertInstanceOf(IllegalStateException.class, thrown.getCause());
        verify(driver).cleanup();
        verify(driver, never()).run();
    }

    @Test
    void runReturnsAfterPreparationWhenTaskGetsCancelledAsynchronously() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        doAnswer(
                        invocation -> {
                            task.setRunning(false);
                            return null;
                        })
                .when(driver)
                .prepare();
        RecordingRichFunction function = new RecordingRichFunction();
        org.apache.flink.util.Collector<Object> output = mock(org.apache.flink.util.Collector.class);
        task.setDriverField(driver);
        task.setStubField(function);
        task.setOutputField(output);
        task.setChainedTasksField(new ArrayList<>());
        task.setConfigField(new TaskConfig(new Configuration()));

        task.callRun();

        verify(driver, never()).run();
        verify(output, never()).close();
        verify(driver).cleanup();
        assertTrue(function.getEvents().isEmpty());
    }

    @Test
    void runWrapsStubOpenFailuresAndDoesNotRunTheDriver() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        RecordingRichFunction function = new RecordingRichFunction();
        RecordingRichFunction.failOpen = true;
        org.apache.flink.util.Collector<Object> output = mock(org.apache.flink.util.Collector.class);
        task.setDriverField(driver);
        task.setStubField(function);
        task.setOutputField(output);
        task.setChainedTasksField(new ArrayList<>());
        task.setConfigField(new TaskConfig(new Configuration()));

        Exception thrown = assertThrows(Exception.class, task::callRun);

        assertTrue(thrown.getMessage().contains("The user defined 'open()' method caused"));
        verify(driver, never()).run();
        verify(output, never()).close();
        verify(driver).cleanup();
        assertEquals(Collections.singletonList("open"), function.getEvents());
    }

    @Test
    void runPropagatesCancelTaskExceptions() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        CancelTaskException cancellation = new CancelTaskException("cancelled");
        doThrow(cancellation).when(driver).run();
        task.setDriverField(driver);
        task.setChainedTasksField(new ArrayList<>());
        task.setOutputField(mock(org.apache.flink.util.Collector.class));
        task.setConfigField(new TaskConfig(new Configuration()));

        CancelTaskException thrown = assertThrows(CancelTaskException.class, task::callRun);

        assertSame(cancellation, thrown);
        verify(driver).cleanup();
    }

    @Test
    void runSuppressesOrdinaryFailuresIfTaskWasCancelledWhileRunning() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        doAnswer(
                        invocation -> {
                            task.setRunning(false);
                            throw new IllegalStateException("failure during cancellation");
