        task.setConfigField(new TaskConfig(new Configuration()));

        assertDoesNotThrow(task::callRun);

        verify(driver).cleanup();
    }

    // ------------------------------------------------------------------------
    //  Full invoke lifecycle
    // ------------------------------------------------------------------------

    @Test
    void invokeRunsTheCompleteTaskLifecycle() throws Exception {
        taskConfiguration = newInvokableConfiguration(true);
        TestBatchTask task = newTask();

        task.invoke();

        assertEquals(
                Arrays.asList("setup", "prepare", "open", "run", "close", "cleanup"),
                RecordingDriver.EVENTS);
        assertInstanceOf(RecordingRichFunction.class, task.getStub());
        assertNotNull(task.getOutputCollector());
        verify(partitionWriter).flushAll();
        verify(broadcastVariableManager).releaseAllReferencesFromTask(task);
    }

    @Test
    void invokeFailsWhenTheDriverClassIsMissing() {
        taskConfiguration = new Configuration();
        TestBatchTask task = newTask();

        assertThrows(Exception.class, task::invoke);
    }

    @Test
    void invokeWrapsDriverPreparationFailures() {
        taskConfiguration = newInvokableConfiguration(true);
        RecordingDriver.failPrepare = true;
        TestBatchTask task = newTask();

        Exception thrown = assertThrows(Exception.class, task::invoke);

        assertTrue(thrown.getMessage().contains("The data preparation for task 'Test Task'"));
        assertTrue(thrown.getMessage().contains("prepare failed"));
