    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void readAndSetBroadcastInputMaterializesVariableAndStoresItInContext() throws Exception {
        TestBatchTask task = newTask();
        TypeSerializerFactory<?> serializerFactory = mock(TypeSerializerFactory.class);
        task.setBroadcastInputSerializersField(new TypeSerializerFactory<?>[] {serializerFactory});
        MutableReader<?> reader = mock(MutableReader.class);
        task.setBroadcastInputReadersField(new MutableReader<?>[] {reader});
        BroadcastVariableMaterialization<?, ?> materialization =
                mock(BroadcastVariableMaterialization.class);
        when(broadcastVariableManager.materializeBroadcastVariable(
                        "broadcast", 1, task, reader, serializerFactory))
                .thenReturn((BroadcastVariableMaterialization) materialization);
        DistributedRuntimeUDFContext context = mock(DistributedRuntimeUDFContext.class);

        task.readAndSetBroadcastInput(0, "broadcast", context, 1);

        verify(broadcastVariableManager)
                .materializeBroadcastVariable("broadcast", 1, task, reader, serializerFactory);
        verify(context).setBroadcastVariable("broadcast", materialization);
    }

    @Test
    void releaseBroadcastVariablesReleasesReferenceAndClearsContext() {
        TestBatchTask task = newTask();
        DistributedRuntimeUDFContext context = mock(DistributedRuntimeUDFContext.class);

        task.releaseBroadcastVariables("broadcast", 2, context);

        verify(broadcastVariableManager).releaseReference("broadcast", 2, task);
        verify(context).clearBroadcastVariable("broadcast");
    }

    // ------------------------------------------------------------------------
    //  Initialization
    // ------------------------------------------------------------------------

    @Test
    void initializeWrapsDriverSetupFailures() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        doThrow(new IllegalStateException("setup failed")).when(driver).setup(task);
        task.setDriverField(driver);

        Exception thrown = assertThrows(Exception.class, task::initialize);

        assertTrue(thrown.getMessage().contains("The driver setup for 'Test Task'"));
        assertTrue(thrown.getMessage().contains("setup failed"));
        assertInstanceOf(IllegalStateException.class, thrown.getCause());
    }

    @Test
    void initializeLeavesStubUnsetWhenDriverHasNoUserCode() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        when(driver.getStubType()).thenReturn(null);
        task.setDriverField(driver);

        task.initialize();

        assertNull(task.getStub());
    }

    @Test
    void initializeInstantiatesStubAndInjectsRuntimeContext() throws Exception {
        TestBatchTask task = newTask();
        Driver<Function, Object> driver = mock(Driver.class);
        when(driver.getStubType()).thenReturn(Function.class);
        task.setDriverField(driver);
