        assertEquals("7", taskStore.getMetric("0.numRecords"));
        assertNull(taskStore.getMetric("numRecords"));

        SubtaskMetricStore subtaskStore = taskStore.getSubtaskMetricStore(0);
        assertNotNull(subtaskStore);
        assertEquals("7", subtaskStore.getMetric("numRecords"));
