    @Test
    void snapshotCollectionsAreUnmodifiable() {
        MetricStore metricStore = new MetricStore();
        metricStore.add(new GaugeDump(taskScope(0, 0), "metric", "value"));
        metricStore.add(
                new CounterDump(
                        new TaskManagerQueryScopeInfo(TASK_MANAGER_ID), "tmMetric", 1L));

        ComponentMetricStore jobManagerStore = metricStore.getJobManagerMetricStore();
        assertThrows(
                UnsupportedOperationException.class,
                () -> jobManagerStore.metrics.put("other", "value"));

        TaskManagerMetricStore taskManagerStore =
                metricStore.getTaskManagerMetricStore(TASK_MANAGER_ID);
        assertThrows(
                UnsupportedOperationException.class,
                () -> taskManagerStore.garbageCollectorNames.add("gc"));
        assertThrows(
                UnsupportedOperationException.class,
                () -> taskManagerStore.metrics.put("other", "value"));

        assertThrows(
                UnsupportedOperationException.class,
                () -> metricStore.getTaskManagers().put("other", taskManagerStore));

        TaskMetricStore taskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertThrows(
                UnsupportedOperationException.class,
                () -> taskStore.metrics.put("other", "value"));
        assertThrows(
                UnsupportedOperationException.class,
                () -> taskStore.getAllSubtaskMetricStores().put(1, null));

        JobMetricStoreSnapshot jobsSnapshot = metricStore.getJobs();
        assertThrows(
                UnsupportedOperationException.class,
                () -> jobsSnapshot.values().removeIf(store -> true));
        assertThrows(
                UnsupportedOperationException.class,
                () ->
                        jobsSnapshot
                                .getSubtaskMetricStore(JOB_ID, VERTEX_ID, 0)
                                .metrics
                                .put("other", "value"));
        assertThrows(
                UnsupportedOperationException.class,
                () ->
                        jobsSnapshot
                                .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 0)
                                .metrics
                                .put("other", "value"));
    }

