        MemorySegment currBuff;
        while (this.writeBehindBuffersAvailable > 0
                && (currBuff = this.writeBehindBuffers.poll()) != null) {
            this.availableMemory.add(currBuff);
            this.writeBehindBuffersAvailable--;
