        final List<MemorySegment> memorySegments = memManager.allocatePages(ownerTask, numPages);

        return new MutableHashTable<BT, PT>(
                buildSideSerializer,
                probeSideSerializer,
                buildSideComparator,
                probeSideComparator,
                pairComparator,
                memorySegments,
                ioManager,
                useBloomFilters);
    }
}
