public void prepareProbePhase(
        IOManager ioAccess,
        FileIOChannel.Enumerator probeChannelEnumerator,
        LinkedBlockingQueue<MemorySegment> bufferReturnQueue)
        throws IOException {
    if (isInMemory()) {
        return;
    }
    // ATTENTION: The following lines are duplicated code from finalizeBuildPhase
    this.probeSideChannel =
            ioAccess.createBlockChannelWriter(probeChannelEnumerator.next(), bufferReturnQueue);
