        Collection<IntermediateDataSetID> dataSetsToRelease, Duration timeout) {
    partitionTracker.stopTrackingAndReleaseClusterPartitions(dataSetsToRelease);
    return CompletableFuture.completedFuture(Acknowledge.get());
