    try (MdcCloseable ignored = MdcUtils.withContext(MdcUtils.asContextData(jobId))) {
        jobTable.getConnection(jobId)
                .ifPresent(
                        jobManagerConnection ->
                                disconnectAndTryReconnectToJobManager(
                                        jobManagerConnection, cause, true));
