    try {
        task.deliverOperatorEvent(operatorId, evt);
        return CompletableFuture.completedFuture(Acknowledge.get());
    } catch (Throwable t) {
        ExceptionUtils.rethrowIfFatalError(t);
        return FutureUtils.completedExceptionally(t);
    }
}

