    @Test
    void testGetAndRetainPartitionWithMetricsFiltersPartitionsWithoutMetrics() throws Exception {
        final TestContext context = newContext();
        final JobID jobId = new JobID();
        final ResultPartitionID partitionWithMetrics = new ResultPartitionID();
        final ResultPartitionID partitionWithoutMetrics = new ResultPartitionID();

        final TaskExecutorPartitionInfo infoWithMetrics =
                new TaskExecutorPartitionInfo(
                        new UnknownShuffleDescriptor(partitionWithMetrics),
                        new IntermediateDataSetID(),
                        1);
        final TaskExecutorPartitionInfo infoWithoutMetrics =
                new TaskExecutorPartitionInfo(
                        new UnknownShuffleDescriptor(partitionWithoutMetrics),
                        new IntermediateDataSetID(),
                        1);
        when(context.partitionTracker.getTrackedPartitionsFor(jobId))
                .thenReturn(Arrays.asList(infoWithMetrics, infoWithoutMetrics));

        final ShuffleMetrics metrics = mock(ShuffleMetrics.class);
        when(context.shuffleEnvironment.getMetricsIfPartitionOccupyingLocalResource(
                        partitionWithMetrics))
                .thenReturn(Optional.of(metrics));
        when(context.shuffleEnvironment.getMetricsIfPartitionOccupyingLocalResource(
                        partitionWithoutMetrics))
                .thenReturn(Optional.empty());

        final Collection<PartitionWithMetrics> partitions =
                get(context.taskExecutor.getAndRetainPartitionWithMetrics(jobId));

        assertEquals(1, partitions.size());
        final PartitionWithMetrics partition = partitions.iterator().next();
        assertSame(infoWithMetrics.getShuffleDescriptor(), partition.getPartition());
        assertSame(metrics, partition.getPartitionMetrics());
    }

