        private TaskExecutor createTaskExecutor() {
            return new TaskExecutor(
                    rpcService,
                    taskManagerConfiguration,
                    haServices,
                    taskExecutorServices,
                    ExternalResourceInfoProvider.NO_EXTERNAL_RESOURCES,
                    heartbeatServices,
                    UnregisteredMetricGroups.createUnregisteredTaskManagerMetricGroup(),
                    metricQueryServiceAddress,
                    taskExecutorBlobService,
                    fatalErrorHandler,
                    partitionTracker,
                    new DelegationTokenReceiverRepository(configuration, null));
        }

        void setMetricQueryServiceAddress(String metricQueryServiceAddress) {
            this.metricQueryServiceAddress = metricQueryServiceAddress;
        }

        /** Recreates the {@link TaskExecutor} (needed when configuration values changed). */
        void restart() {
            this.taskExecutor = createTaskExecutor();
        }

        void start() throws Exception {
            rpcServer().executeInMainThread(() -> taskExecutor.internalCallOnStart());
        }

        void stop() throws Exception {
            final CompletableFuture<Void> stopFuture =
                    rpcServer().executeInMainThread(() -> taskExecutor.internalCallOnStop());
            get(stopFuture);
        }

        TestRpcServer rpcServer() {
            return rpcService.getRpcServer();
        }

        Task addTask(JobID jobId, ExecutionAttemptID attemptId) {
            final Task task = mock(Task.class);
            when(task.getJobID()).thenReturn(jobId);
            when(task.getExecutionId()).thenReturn(attemptId);
            when(taskSlotTable.getTask(attemptId)).thenReturn(task);
            return task;
        }

        JobMasterGateway connectJob(JobID jobId, JobMasterId jobMasterId) {
            return connectJob(jobId, jobMasterId, ResourceID.generate());
        }

        JobMasterGateway connectJob(
                JobID jobId, JobMasterId jobMasterId, ResourceID jobManagerResourceId) {
            try {
                final JobTable.Job job =
                        jobTable.getOrCreateJob(
                                jobId, () -> mock(JobTable.JobServices.class));
                final JobMasterGateway jobMasterGateway = mock(JobMasterGateway.class);
                when(jobMasterGateway.getFencingToken()).thenReturn(jobMasterId);
                job.connect(
                        jobManagerResourceId,
                        jobMasterGateway,
                        mock(TaskManagerActions.class),
                        mock(CheckpointResponder.class),
                        mock(GlobalAggregateManager.class),
                        mock(PartitionProducerStateChecker.class));
                return jobMasterGateway;
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        String getUploadedContent() throws Exception {
            return uploadedContent == null
                    ? null
                    : new String(uploadedContent.toByteArray(), StandardCharsets.UTF_8);
        }

        @Override
        public void close() throws Exception {
            ioExecutor.shutdownNow();
