        private final List<Long> scheduledDelays = new ArrayList<>();

        private MainThreadValidatorUtil mainThreadValidator;
        private boolean inMainThread;

        void setEndpoint(RpcEndpoint rpcEndpoint) {
            this.mainThreadValidator = new MainThreadValidatorUtil(rpcEndpoint);
        }

        <T> T executeInMainThread(Callable<T> callable) throws Exception {
            if (inMainThread || mainThreadValidator == null) {
                return callable.call();
            }
            inMainThread = true;
            mainThreadValidator.enterMainThread();
            try {
                return callable.call();
            } finally {
                mainThreadValidator.exitMainThread();
                inMainThread = false;
            }
        }

        void executeInMainThread(Runnable runnable) throws Exception {
            executeInMainThread(
                    () -> {
                        runnable.run();
                        return null;
                    });
        }

        List<Long> getScheduledDelays() {
            return scheduledDelays;
        }

        void completeTermination() {
            terminationFuture.complete(null);
        }

        @Override
        public void runAsync(Runnable runnable) {
            try {
                executeInMainThread(runnable);
            } catch (RuntimeException | Error e) {
                throw e;
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public <V> CompletableFuture<V> callAsync(Callable<V> callable, Duration callTimeout) {
            try {
                return CompletableFuture.completedFuture(executeInMainThread(callable));
            } catch (Throwable t) {
                final CompletableFuture<V> future = new CompletableFuture<>();
                future.completeExceptionally(t);
                return future;
            }
        }

