/**
 * Tests for the externally observable behaviour of the {@link TaskExecutor}.
 *
 * <p>The {@link TaskExecutor} under test is always a real instance. Only the surrounding services
 * (RPC plumbing, task slot table, shuffle environment, blob service, high availability services,
 * ...) are replaced by lightweight, deterministic stand-ins.
 */
class TaskExecutorTests {

    private static final Duration TIMEOUT = Duration.ofSeconds(30);

    @TempDir private File tempDirectory;

    private final List<TestContext> contexts = new ArrayList<>();

    @AfterEach
    void tearDown() throws Exception {
        Exception exception = null;
        for (TestContext context : contexts) {
            try {
                context.close();
            } catch (Exception e) {
                exception = e;
            }
        }
        contexts.clear();
        if (exception != null) {
            throw exception;
        }
    }

    // ------------------------------------------------------------------------
    //  Construction and simple properties
    // ------------------------------------------------------------------------

    @Test
    void testConstructorRejectsTaskManagerWithoutSlots() {
        final Configuration configuration = new Configuration();
        final TaskManagerConfiguration oneSlotConfiguration =
                TestContext.createTaskManagerConfiguration(configuration, tempDirectory);

        final TaskManagerConfiguration zeroSlotsConfiguration =
                new TaskManagerConfiguration(
                        0,
                        oneSlotConfiguration.getDefaultSlotResourceProfile(),
                        oneSlotConfiguration.getTotalResourceProfile(),
                        oneSlotConfiguration.getTmpDirectories(),
                        oneSlotConfiguration.getRpcTimeout(),
                        oneSlotConfiguration.getSlotTimeout(),
                        oneSlotConfiguration.getMaxRegistrationDuration(),
                        configuration,
                        false,
                        null,
                        null,
                        null,
                        "localhost",
                        tempDirectory,
                        oneSlotConfiguration.getRetryingRegistrationConfiguration());

        final IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () -> newContext(configuration, zeroSlotsConfiguration));
        assertTrue(exception.getMessage().contains("number of slots"));
    }

    @Test
    void testGetResourceIDReturnsTaskManagerResourceID() {
        final TestContext context = newContext();

        assertEquals(
                context.unresolvedTaskManagerLocation.getResourceID(),
                context.taskExecutor.getResourceID());
    }

    @Test
    void testRequestMetricQueryServiceAddressReturnsConfiguredAddress() throws Exception {
        final TestContext context = newContext();

        final SerializableOptional<String> address =
                get(context.taskExecutor.requestMetricQueryServiceAddress(TIMEOUT));

        assertTrue(address.isPresent());
        assertEquals("localhost:1234", address.get());
    }

    @Test
    void testRequestMetricQueryServiceAddressIsEmptyIfNotConfigured() throws Exception {
        final Configuration configuration = new Configuration();
        final TestContext context = newContext(configuration);
        context.setMetricQueryServiceAddress(null);
        context.restart();

        final SerializableOptional<String> address =
                get(context.taskExecutor.requestMetricQueryServiceAddress(TIMEOUT));

        assertFalse(address.isPresent());
    }

    @Test
    void testCanBeReleasedWithoutPartitionsOccupyingLocalResources() throws Exception {
        final TestContext context = newContext();
        when(context.shuffleEnvironment.getPartitionsOccupyingLocalResources())
                .thenReturn(Collections.emptyList());

        assertTrue(get(context.taskExecutor.canBeReleased()));
    }

    @Test
    void testCanNotBeReleasedWithPartitionsOccupyingLocalResources() throws Exception {
        final TestContext context = newContext();
        when(context.shuffleEnvironment.getPartitionsOccupyingLocalResources())
                .thenReturn(Collections.singletonList(new ResultPartitionID()));

        assertFalse(get(context.taskExecutor.canBeReleased()));
    }

    @Test
    void testGetResourceManagerHeartbeatManagerIsExposedForTesting() {
        final TestContext context = newContext();

        assertSame(
                context.heartbeatServices.getResourceManagerHeartbeatManager(),
                context.taskExecutor.getResourceManagerHeartbeatManager());
        assertNull(context.taskExecutor.getResourceManagerConnection());
    }

    // ------------------------------------------------------------------------
    //  Log and file uploads
    // ------------------------------------------------------------------------

    @Test
    void testRequestLogListReturnsEmptyListIfNoLogPathIsConfigured() throws Exception {
        final TestContext context = newContext();

        final Collection<LogInfo> logInfos = get(context.taskExecutor.requestLogList(TIMEOUT));

        assertNotNull(logInfos);
        assertTrue(logInfos.isEmpty());
    }

    @Test
    void testRequestLogListReturnsContainedFiles() throws Exception {
        final File logDirectory = createLogDirectory();
        final File logFile = writeFile(logDirectory, "taskmanager.log", "the-log");
        writeFile(logDirectory, "taskmanager.out", "the-out");
        assertTrue(new File(logDirectory, "sub-directory").mkdir());

        final TestContext context = newContext(logConfiguration(logFile));

        final Collection<LogInfo> logInfos = get(context.taskExecutor.requestLogList(TIMEOUT));

        final Map<String, LogInfo> byName =
                logInfos.stream().collect(Collectors.toMap(LogInfo::getName, info -> info));
        assertEquals(2, byName.size());
        assertEquals("the-log".length(), byName.get("taskmanager.log").getSize());
        assertEquals(logFile.lastModified(), byName.get("taskmanager.log").getMtime());
        assertTrue(byName.containsKey("taskmanager.out"));
    }

    @Test
    void testRequestLogListFailsIfLogDirectoryDoesNotExist() {
        final File logFile = new File(new File(tempDirectory, "does-not-exist"), "taskmanager.log");
        final TestContext context = newContext(logConfiguration(logFile));

        final Throwable throwable = failureOf(context.taskExecutor.requestLogList(TIMEOUT));

        assertTrue(
                throwable.getMessage().contains("There isn't a log file in TaskExecutor"),
                "Unexpected failure: " + throwable);
