import org.apache.curator.test.TestingServer;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.runtime.leaderretrieval.DefaultLeaderRetrievalService;
import org.apache.flink.runtime.leaderelection.LeaderInformation;
import org.apache.flink.runtime.util.ZooKeeperUtils;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.CuratorFramework;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.CuratorFrameworkFactory;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.recipes.cache.TreeCache;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.recipes.cache.TreeCacheSelector;
import org.apache.flink.shaded.curator5.org.apache.curator.retry.RetryOneTime;
import org.apache.flink.shaded.zookeeper3.org.apache.zookeeper.CreateMode;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Proto2 {
    public static void main(String[] args) throws Exception {
        TestingServer server = new TestingServer(true);
        CuratorFramework client = CuratorFrameworkFactory.builder()
            .connectString(server.getConnectString())
            .retryPolicy(new RetryOneTime(100))
            .namespace("testns")
            .build();
        client.start();
        client.blockUntilConnected();

        client.create().creatingParentsIfNeeded().forPath("/node", "root".getBytes());
        client.create().creatingParentsIfNeeded().forPath("/node/child", "child".getBytes());

        TreeCache def = ZooKeeperUtils.createTreeCache(client, "/node", () -> {});
        def.start();
        await(() -> def.getCurrentData("/node") != null);
        System.out.println("default: node=" + (def.getCurrentData("/node") != null)
            + " child=" + (def.getCurrentData("/node/child") != null)
            + " children=" + def.getCurrentChildren("/node"));

        TreeCacheSelector sel = new TreeCacheSelector() {
            public boolean traverseChildren(String p) { return true; }
            public boolean acceptChild(String p) { return true; }
        };
        TreeCache custom = ZooKeeperUtils.createTreeCache(client, "/node", sel);
        custom.start();
        await(() -> custom.getCurrentData("/node/child") != null);
        System.out.println("custom: node=" + (custom.getCurrentData("/node") != null)
            + " child=" + (custom.getCurrentData("/node/child") != null)
            + " children=" + custom.getCurrentChildren("/node"));
        def.close(); custom.close();

        // callback events
        AtomicInteger count = new AtomicInteger();
        CountDownLatch latch = new CountDownLatch(3);
        TreeCache watched = ZooKeeperUtils.createTreeCache(client, "/watched", () -> { count.incrementAndGet(); latch.countDown(); });
        watched.start();
        client.create().creatingParentsIfNeeded().forPath("/watched", "v1".getBytes());
        System.out.println("after create latch=" + latch.getCount());
        client.setData().forPath("/watched", "v2".getBytes());
        System.out.println("after update latch=" + latch.getCount());
        client.delete().forPath("/watched");
        System.out.println("delete await=" + latch.await(10, TimeUnit.SECONDS) + " count=" + count.get());
        watched.close();

        // leader retrieval
        String path = "/leader";
        DefaultLeaderRetrievalService service = ZooKeeperUtils.createLeaderRetrievalService(client, path, new Configuration());
        CompletableFuture<LeaderInformation> got = new CompletableFuture<>();
        service.start(new org.apache.flink.runtime.leaderretrieval.LeaderRetrievalListener() {
            public void notifyLeaderAddress(String addr, UUID sid) {
                if (addr != null) got.complete(LeaderInformation.known(sid, addr));
            }
            public void handleError(Exception e) { got.completeExceptionally(e); }
        });
        LeaderInformation info = LeaderInformation.known(UUID.randomUUID(), "localhost:6123");
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(info, client, () -> true, ZooKeeperUtils.generateConnectionInformationPath(path));
        System.out.println("retrieved=" + got.get(15, TimeUnit.SECONDS));
        service.stop();
        client.close();
        server.close();
        System.out.println("DONE");
    }

    static void await(java.util.function.BooleanSupplier c) throws Exception {
        long deadline = System.currentTimeMillis() + 10000;
        while (!c.getAsBoolean()) {
            if (System.currentTimeMillis() > deadline) throw new AssertionError("timeout");
            Thread.sleep(20);
        }
    }
}
