import org.apache.flink.shaded.curator5.org.apache.curator.retry.RetryOneTime;
import org.apache.flink.shaded.zookeeper3.org.apache.zookeeper.CreateMode;
import org.apache.flink.shaded.zookeeper3.org.apache.zookeeper.data.Stat;
import java.util.UUID;

public class Proto3 {
    static CuratorFramework newClient(TestingServer s, String ns) throws Exception {
        CuratorFramework c = CuratorFrameworkFactory.builder().connectString(s.getConnectString())
            .retryPolicy(new RetryOneTime(100)).namespace(ns).build();
        c.start(); c.blockUntilConnected(); return c;
    }
    public static void main(String[] args) throws Exception {
        TestingServer server = new TestingServer(true);
        String ns = "ns-" + UUID.randomUUID();
        CuratorFramework c1 = newClient(server, ns);
        String p = "/leader/connection_info";
        LeaderInformation info = LeaderInformation.known(UUID.randomUUID(), "host:1");
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(info, c1, () -> true, p);
        Stat st = c1.checkExists().forPath(p);
        long s1 = c1.getZookeeperClient().getZooKeeper().getSessionId();
        System.out.println("ephemeral=" + st.getEphemeralOwner() + " expected=" + s1 + " len=" + st.getDataLength());
        System.out.println("read=" + ZooKeeperUtils.readLeaderInformation(c1.getData().forPath(p)).equals(info));

        LeaderInformation info2 = LeaderInformation.known(UUID.randomUUID(), "host:2");
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(info2, c1, () -> true, p);
        System.out.println("after update read2=" + ZooKeeperUtils.readLeaderInformation(c1.getData().forPath(p)).equals(info2)
            + " ephemeral same=" + (c1.checkExists().forPath(p).getEphemeralOwner() == s1));

        ZooKeeperUtils.writeLeaderInformationToZooKeeper(LeaderInformation.empty(), c1, () -> true, p);
        Stat st2 = c1.checkExists().forPath(p);
        System.out.println("empty len=" + st2.getDataLength() + " readEmpty=" + ZooKeeperUtils.readLeaderInformation(c1.getData().forPath(p)).isEmpty());

        String p2 = "/noleader/connection_info";
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(info, c1, () -> false, p2);
        System.out.println("no leadership exists=" + (c1.checkExists().forPath(p2) != null));

        // other session
        String p3 = "/other/connection_info";
        CuratorFramework c2 = newClient(server, ns);
        c2.create().creatingParentsIfNeeded().withMode(CreateMode.EPHEMERAL).forPath(p3, "junk".getBytes());
        long s2 = c2.getZookeeperClient().getZooKeeper().getSessionId();
        System.out.println("other owner is c2=" + (c1.checkExists().forPath(p3).getEphemeralOwner() == s2));
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(info, c1, () -> true, p3);
        Stat st3 = c1.checkExists().forPath(p3);
        System.out.println("after takeover owner c1=" + (st3.getEphemeralOwner() == s1)
            + " read=" + ZooKeeperUtils.readLeaderInformation(c1.getData().forPath(p3)).equals(info));
        c2.close(); c1.close(); server.close();
        System.out.println("DONE");
    }
}
