import org.apache.flink.configuration.HighAvailabilityOptions;
import org.apache.flink.core.execution.RecoveryClaimMode;
import org.apache.flink.runtime.checkpoint.CheckpointIDCounter;
import org.apache.flink.runtime.checkpoint.CompletedCheckpointStore;
import org.apache.flink.runtime.highavailability.zookeeper.CuratorFrameworkWithUnhandledErrorListener;
import org.apache.flink.runtime.jobmanager.ApplicationStore;
import org.apache.flink.runtime.jobmanager.ExecutionPlanStore;
import org.apache.flink.runtime.persistence.filesystem.FileSystemStateStorageHelper;
import org.apache.flink.runtime.state.SharedStateRegistryFactory;
import org.apache.flink.runtime.state.SharedStateRegistryImpl;
import org.apache.flink.runtime.util.ZooKeeperUtils;
import org.apache.flink.runtime.zookeeper.ZooKeeperStateHandleStore;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.CuratorFramework;
import org.apache.flink.shaded.curator5.org.apache.curator.framework.CuratorFrameworkFactory;
import org.apache.flink.shaded.curator5.org.apache.curator.retry.RetryOneTime;
import java.nio.file.Files;
import java.util.UUID;
import java.util.concurrent.Executors;

public class Proto4 {
    public static void main(String[] args) throws Exception {
        TestingServer server = new TestingServer(true);
        String ns = "ns-" + UUID.randomUUID();
        CuratorFramework client = CuratorFrameworkFactory.builder().connectString(server.getConnectString())
            .retryPolicy(new RetryOneTime(100)).namespace(ns).build();
        client.start(); client.blockUntilConnected();

        CuratorFramework nsClient = ZooKeeperUtils.useNamespaceAndEnsurePath(client, "/checkpoints");
        System.out.println("ns=" + nsClient.getNamespace() + " exists=" + (client.checkExists().forPath("/checkpoints") != null));

        client.create().creatingParentsIfNeeded().forPath("/a/b/c", "x".getBytes());
        ZooKeeperUtils.deleteZNode(client, "/a");
        System.out.println("deleted=" + (client.checkExists().forPath("/a") == null));
        ZooKeeperUtils.deleteZNode(client, "/a");
        System.out.println("idempotent ok");

        java.nio.file.Path temp = Files.createTempDirectory("zkutils");
        Configuration config = new Configuration();
        config.set(HighAvailabilityOptions.HA_STORAGE_PATH, temp.toUri().toString());
        config.set(HighAvailabilityOptions.HA_CLUSTER_ID, "/cluster");
        System.out.println("storage path=" + temp.toUri());

        FileSystemStateStorageHelper<String> storage = ZooKeeperUtils.createFileSystemStateStorage(config, "state");
        System.out.println("stored=" + storage.store("hello").retrieveState());
        Files.walk(temp).forEach(p -> System.out.println("file: " + p));

        ZooKeeperStateHandleStore<String> handleStore =
            ZooKeeperUtils.createZooKeeperStateHandleStore(client, "/state-handles", storage);
        org.apache.flink.runtime.state.RetrievableStateHandle<String> h = handleStore.addAndLock("/state-1", "value");
        System.out.println("retrieved=" + h.retrieveState() + " handlePathExists=" + (client.checkExists().forPath("/state-handles/state-1") != null));
        System.out.println("release=" + handleStore.releaseAndTryRemove("/state-1") + " all=" + handleStore.getAllHandles());

        CheckpointIDCounter counter = ZooKeeperUtils.createCheckpointIDCounter(client);
        counter.start();
        System.out.println("ids=" + counter.getAndIncrement() + "," + counter.getAndIncrement() + " get=" + counter.get());
        System.out.println("shutdown=" + counter.shutdown(JobStatus.RUNNING).get());
        CheckpointIDCounter counter2 = ZooKeeperUtils.createCheckpointIDCounter(client);
        counter2.start();
        System.out.println("counter2 first=" + counter2.getAndIncrement());
        System.out.println("shutdown2=" + counter2.shutdown(JobStatus.FINISHED).get());
        System.out.println("counterNodeAfterTerminal=" + (client.checkExists().forPath(ZooKeeperUtils.getCheckpointIdCounterPath()) != null));

        ExecutionPlanStore planStore = ZooKeeperUtils.createExecutionPlans(client, config);
        System.out.println("jobIds=" + planStore.getJobIds() + " recover=" + planStore.recoverExecutionPlan(new JobID())
            + " pathExists=" + (client.checkExists().forPath("/execution-plans") != null));
        planStore.start(jobId -> {}, jobId -> {});
        planStore.stop();
        System.out.println("planStore started/stopped");

        ApplicationStore appStore = ZooKeeperUtils.createApplicationStore(client, config);
        System.out.println("appIds=" + appStore.getApplicationIds() + " recover=" + appStore.recoverApplication(new ApplicationID())
            + " pathExists=" + (client.checkExists().forPath("/applications") != null));
        appStore.start(); appStore.stop();

        SharedStateRegistryFactory factory = (ex, cps, mode) -> new SharedStateRegistryImpl(ex);
        CompletedCheckpointStore cpStore = ZooKeeperUtils.createCompletedCheckpoints(
            client, config, 2, factory, Executors.directExecutor(), Executors.directExecutor(), RecoveryClaimMode.CLAIM);
        System.out.println("cps=" + cpStore.getAllCheckpoints() + " latest=" + cpStore.getLatestCheckpoint()
            + " ext=" + cpStore.requiresExternalizedCheckpoints()
            + " pathExists=" + (client.checkExists().forPath("/checkpoints") != null)
            + " registry=" + (cpStore.getSharedStateRegistry() != null));

        client.close(); server.close();

        // config-based start
        Configuration zkConfig = new Configuration();
        zkConfig.set(HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM, server.getConnectString());
        System.out.println("server closed but config ok");
        System.out.println("DONE");
    }
}
