            + " pathExists=" + (client.checkExists().forPath("/applications") != null));
        appStore.start(); appStore.stop();

        SharedStateRegistryFactory factory = (ex, cps, mode) -> new SharedStateRegistryImpl(ex);
        CompletedCheckpointStore cpStore = ZooKeeperUtils.createCompletedCheckpoints(
