package org.apache.flink.runtime.util;

imports...

/** Tests for {@link ZooKeeperUtils}. */
class ZooKeeperUtilsTests {

    private static TestingServer testingServer;

    private CuratorFramework client;
    private String namespace;

    @BeforeAll
    static void startZooKeeperServer() throws Exception {
        testingServer = new TestingServer();
    }

    @AfterAll
    static void stopZooKeeperServer() throws Exception {
        if (testingServer != null) {
            testingServer.close();
        }
    }

    @BeforeEach
    void createZooKeeperClient() throws Exception {
        namespace = "zoo-keeper-utils-" + UUID.randomUUID();
        client = createClient(namespace);
    }

    @AfterEach
    void closeZooKeeperClient() {
        if (client != null) {
            client.close();
        }
    }

    private CuratorFramework createClient(String namespace) throws Exception {
        final CuratorFramework curatorFramework =
                CuratorFrameworkFactory.builder()
                        .connectString(testingServer.getConnectString())
                        .namespace(namespace)
                        .retryPolicy(new RetryOneTime(100))
                        .build();
        curatorFramework.start();
        curatorFramework.blockUntilConnected();
        return curatorFramework;
    }

    private static void awaitCondition(BooleanSupplier condition) throws Exception {
        final long deadline = System.currentTimeMillis() + 30_000L;
        while (!condition.getAsBoolean()) {
            if (System.currentTimeMillis() > deadline) {
                fail("Condition was not fulfilled within the timeout.");
            }
            Thread.sleep(20L);
        }
    }

    private static void awaitCounter(AtomicInteger counter, int expectedMinimum) throws Exception {
        awaitCondition(() -> counter.get() >= expectedMinimum);
    }
