    @Test
    @SuppressWarnings("unchecked")
    void testStartCuratorFrameworkRegistersUnhandledErrorListener() throws Exception {
        final CuratorFramework curatorFramework = mock(CuratorFramework.class);
        final Listenable<UnhandledErrorListener> unhandledErrorListenable =
                mock(Listenable.class);
        final CuratorFrameworkFactory.Builder builder =
                mock(CuratorFrameworkFactory.Builder.class);
        final FatalErrorHandler fatalErrorHandler = mock(FatalErrorHandler.class);

        when(builder.build()).thenReturn(curatorFramework);
        when(curatorFramework.getUnhandledErrorListenable())
                .thenReturn(unhandledErrorListenable);

        final CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper =
                ZooKeeperUtils.startCuratorFramework(builder, fatalErrorHandler);

        verify(curatorFramework).start();
        assertThat(curatorFrameworkWrapper.asCuratorFramework()).isSameAs(curatorFramework);

        final org.mockito.ArgumentCaptor<UnhandledErrorListener> listenerCaptor =
                forClass(UnhandledErrorListener.class);
        verify(unhandledErrorListenable).addListener(listenerCaptor.capture());

        final Throwable failure = new RuntimeException("expected failure");
        listenerCaptor.getValue().onError("unhandled error", failure);
        verify(fatalErrorHandler).onFatalError(failure);

        curatorFrameworkWrapper.close();
        verify(unhandledErrorListenable).removeListener(listenerCaptor.getValue());
        verify(curatorFramework).close();
    }

