    @ParameterizedTest
    @MethodSource("outOfRangeMaxCloseWaitDurations")
    void testStartCuratorFrameworkRejectsOutOfRangeMaxCloseWait(Duration maxCloseWait) {
        final Configuration configuration = zooKeeperConfiguration();
        configuration.set(HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT, maxCloseWait);

