        assertSame(operatorBackend, context.operatorStateBackend());
        assertNull(context.keyedStateBackend());
        assertNull(context.asyncKeyedStateBackend());
        assertNull(context.keySerializer());
        assertNull(context.internalTimerServiceManager());
        assertNull(context.asyncInternalTimerServiceManager());
        assertEquals(OptionalLong.empty(), context.getRestoredCheckpointId());
        assertFalse(context.rawOperatorStateInputs().iterator().hasNext());
        assertFalse(context.rawKeyedStateInputs().iterator().hasNext());

        assertEquals(0, fixture.stateBackend.keyedCreationAttempts);
