    // ------------------------------------------------------------------------
    //  Tests for the end-to-end conversion of a StreamGraph into a JobGraph
    // ------------------------------------------------------------------------

    @Test
    void testChainedPipelineIsCollapsedIntoOneJobVertex() {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);
        env.fromData(1, 2, 3).map(value -> value + 1).addSink(new PrintSinkFunction<>());

        JobGraph jobGraph = StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());

        assertThat(jobGraph.getNumberOfVertices()).isEqualTo(1);
        JobVertex vertex = jobGraph.getVerticesSortedTopologicallyFromSources().get(0);
        assertThat(vertex.getName()).isEqualTo("Source: Collection Source -> Map -> Sink: Unnamed");
        assertThat(vertex.getParallelism()).isEqualTo(1);

        StreamConfig headConfig = new StreamConfig(vertex.getConfiguration());
        assertThat(headConfig.isChainStart()).isTrue();
        assertThat(headConfig.getChainIndex()).isEqualTo(1);
        assertThat(headConfig.getOperatorName()).isEqualTo("Source: Collection Source");

        Map<Integer, StreamConfig> chainedConfigs =
                headConfig.getTransitiveChainedTaskConfigs(CLASS_LOADER);
        assertThat(chainedConfigs).hasSize(2);
        assertThat(chainedConfigs.values())
                .extracting(StreamConfig::getOperatorName)
                .containsExactlyInAnyOrder("Map", "Sink: Unnamed");
        assertThat(chainedConfigs.values())
                .extracting(StreamConfig::getChainIndex)
                .containsExactlyInAnyOrder(2, 3);

        assertThat(vertex.getOperatorPrettyName())
                .isEqualTo("Source: Collection Source\n+- Map\n   +- Sink: Unnamed\n");
    }

    @Test
    void testNonChainableExchangeCreatesJobEdgeWithExpectedPartitionType() {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(2);
        env.fromData(1, 2, 3).rebalance().map(value -> value + 1);

        JobGraph jobGraph = StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());

        assertThat(jobGraph.getNumberOfVertices()).isEqualTo(2);
        List<JobVertex> vertices = jobGraph.getVerticesSortedTopologicallyFromSources();
        JobVertex sourceVertex = vertices.get(0);
        JobVertex mapVertex = vertices.get(1);

        assertThat(sourceVertex.getName()).isEqualTo("Source: Collection Source");
        assertThat(sourceVertex.getParallelism()).isEqualTo(1);
        assertThat(sourceVertex.getProducedDataSets()).hasSize(1);
        assertThat(sourceVertex.getProducedDataSets().get(0).getResultType())
                .isEqualTo(ResultPartitionType.PIPELINED_BOUNDED);

        assertThat(mapVertex.getName()).isEqualTo("Map");
        assertThat(mapVertex.getParallelism()).isEqualTo(2);
        assertThat(mapVertex.getInputs()).hasSize(1);

        JobEdge jobEdge = mapVertex.getInputs().get(0);
        assertThat(jobEdge.getDistributionPattern()).isEqualTo(DistributionPattern.ALL_TO_ALL);
        assertThat(jobEdge.getShipStrategyName()).isEqualTo("REBALANCE");
        assertThat(jobEdge.getSource()).isSameAs(sourceVertex.getProducedDataSets().get(0));
        assertThat(new StreamConfig(mapVertex.getConfiguration()).getNumberOfNetworkInputs())
                .isEqualTo(1);
    }

