        configuration.set(CheckpointingOptions.CHECKPOINTING_INTERVAL, Duration.ofMillis(5L));
        configuration.set(CheckpointingOptions.PAUSE_SOURCES_UNTIL_FIRST_CHECKPOINT, true);
        StreamGraph streamGraph = createStreamGraph(new CheckpointConfig(configuration));
