        StreamGraph streamGraph = createStreamGraph();
        StreamNode upstream = addNode(streamGraph, 1, "upstream");
        StreamNode downstream = addNode(streamGraph, 2, "downstream");
        StreamEdge edge = addEdge(upstream, downstream, 0, new RebalancePartitioner<>());

        JobGraph jobGraph = new JobGraph("test");
        JobVertex headVertex = new JobVertex("head");
        headVertex.setParallelism(1);
        JobVertex tailVertex = new JobVertex("tail");
        tailVertex.setParallelism(2);
        jobGraph.addVertex(headVertex);
        jobGraph.addVertex(tailVertex);

        JobVertexBuildContext context = buildContext(streamGraph, jobGraph);
        Map<Integer, JobVertex> jobVertices = new HashMap<>();
        jobVertices.put(1, headVertex);
        jobVertices.put(2, tailVertex);
        NonChainedOutput output =
                new NonChainedOutput(
                        true,
                        1,
                        2,
                        128,
                        0L,
                        false,
                        new IntermediateDataSetID(),
                        null,
                        new RebalancePartitioner<>(),
                        ResultPartitionType.PIPELINED_BOUNDED);

        IntermediateDataSet dataSet =
                StreamingJobGraphGenerator.connect(1, edge, output, jobVertices, context);

        assertThat(tailVertex.getInputs()).hasSize(1);
        JobEdge jobEdge = tailVertex.getInputs().get(0);
        assertThat(jobEdge.getDistributionPattern()).isEqualTo(DistributionPattern.ALL_TO_ALL);
        assertThat(jobEdge.getShipStrategyName()).isEqualTo("REBALANCE");
        assertThat(jobEdge.getSource()).isSameAs(dataSet);
        assertThat(dataSet.getProducer()).isSameAs(headVertex);
        assertThat(dataSet.getResultType()).isEqualTo(ResultPartitionType.PIPELINED_BOUNDED);
        assertThat(new StreamConfig(tailVertex.getConfiguration()).getNumberOfNetworkInputs())
                .isEqualTo(1);
        assertThat(context.getPhysicalEdgesInOrder()).containsExactly(edge);
    }

