    @Test
    void testJobGraphInheritsStreamGraphMetadata() {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);
        env.fromData(1, 2, 3);

        StreamGraph streamGraph = env.getStreamGraph();
        JobID jobId = new JobID();
        ApplicationID applicationId = new ApplicationID();
        SavepointRestoreSettings savepointRestoreSettings =
                SavepointRestoreSettings.forPath("/tmp/savepoint");
        streamGraph.setJobId(jobId);
        streamGraph.setApplicationId(applicationId);
        streamGraph.setJobName("metadata-job");
        streamGraph.setJobType(JobType.BATCH);
        streamGraph.setSavepointRestoreSettings(savepointRestoreSettings);

        JobGraph jobGraph = StreamingJobGraphGenerator.createJobGraph(streamGraph);

        assertThat(jobGraph.getJobID()).isEqualTo(jobId);
        assertThat(jobGraph.getApplicationId()).contains(applicationId);
        assertThat(jobGraph.getName()).isEqualTo("metadata-job");
        assertThat(jobGraph.getJobType()).isEqualTo(JobType.BATCH);
        assertThat(jobGraph.isDynamic()).isFalse();
        assertThat(jobGraph.getSavepointRestoreSettings()).isEqualTo(savepointRestoreSettings);
        assertThat(jobGraph.getJobConfiguration().get(PipelineOptions.OPERATOR_CHAINING)).isTrue();
    }

