    @Test
    void testPreValidateRejectsUnalignedCheckpointsForIterativeGraphs() {
        CheckpointConfig checkpointConfig = enabledCheckpointConfig();
        checkpointConfig.enableUnalignedCheckpoints();
        StreamGraph streamGraph = createStreamGraph(checkpointConfig);
        addNode(streamGraph, 1, "operator");
