    @Test
    void testPreValidateRejectsPauseSourcesWithoutBacklogCheckpoints() {
        Configuration configuration = new Configuration();
        // an interval below the minimal checkpoint interval disables checkpointing during
        // backlog while keeping checkpointing enabled in general
        configuration.set(CheckpointingOptions.CHECKPOINTING_INTERVAL, Duration.ofMillis(5L));
        configuration.set(CheckpointingOptions.PAUSE_SOURCES_UNTIL_FIRST_CHECKPOINT, true);
        StreamGraph streamGraph = createStreamGraph(new CheckpointConfig(configuration));
        addNode(streamGraph, 1, "operator");

        assertThatThrownBy(() -> StreamingJobGraphGenerator.preValidate(streamGraph, CLASS_LOADER))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining(
                        "Pausing sources until first checkpoint is incompatible with disabling"
                                + " checkpoints during backlog processing");
    }

