    @Test
    void testIsChainableForForwardEdge() {
        StreamGraph streamGraph = createStreamGraph();
        StreamNode upstream = addNodeWithParallelism(streamGraph, 1, "upstream", 1);
        StreamNode downstream = addNodeWithParallelism(streamGraph, 2, "downstream", 1);
        StreamEdge edge = addEdge(upstream, downstream, 0, new ForwardPartitioner<>());

        assertThat(StreamingJobGraphGenerator.isChainable(edge, streamGraph)).isTrue();
        assertThat(StreamingJobGraphGenerator.isChainable(edge, streamGraph, true)).isTrue();

        StreamNode otherDownstream = addNodeWithParallelism(streamGraph, 3, "other", 1);
        StreamEdge rebalanceEdge =
                addEdge(upstream, otherDownstream, 0, new RebalancePartitioner<>());
        assertThat(StreamingJobGraphGenerator.isChainable(rebalanceEdge, streamGraph)).isFalse();
    }

