    @Test
    void testPartitionerAndExchangeModeChainability() {
        assertThat(
                        StreamingJobGraphGenerator.arePartitionerAndExchangeModeChainable(
                                new ForwardPartitioner<>(),
                                StreamExchangeMode.UNDEFINED,
                                false))
                .isTrue();
        assertThat(
                        StreamingJobGraphGenerator.arePartitionerAndExchangeModeChainable(
                                new ForwardPartitioner<>(),
                                StreamExchangeMode.PIPELINED,
                                false))
                .isTrue();
        assertThat(
                        StreamingJobGraphGenerator.arePartitionerAndExchangeModeChainable(
                                new ForwardPartitioner<>(), StreamExchangeMode.BATCH, false))
                .isFalse();
        assertThat(
                        StreamingJobGraphGenerator.arePartitionerAndExchangeModeChainable(
                                new RebalancePartitioner<>(),
                                StreamExchangeMode.PIPELINED,
                                false))
                .isFalse();

        ForwardForConsecutiveHashPartitioner<Integer> consecutiveHashPartitioner =
                new ForwardForConsecutiveHashPartitioner<>(new RebalancePartitioner<>());
        assertThat(
                        StreamingJobGraphGenerator.arePartitionerAndExchangeModeChainable(
                                consecutiveHashPartitioner, StreamExchangeMode.PIPELINED, true))
                .isTrue();
        assertThatThrownBy(
                        () ->
                                StreamingJobGraphGenerator
                                        .arePartitionerAndExchangeModeChainable(
                                                consecutiveHashPartitioner,
                                                StreamExchangeMode.PIPELINED,
                                                false))
                .isInstanceOf(IllegalStateException.class);
    }

    @Test
    void testAreOperatorsChainableRespectsChainingStrategies() {
        StreamGraph streamGraph = createStreamGraph();
        StreamNode upstream = addNodeWithParallelism(streamGraph, 1, "upstream", 1);
        StreamNode downstream = addNodeWithParallelism(streamGraph, 2, "downstream", 1);

        assertThat(
                        StreamingJobGraphGenerator.areOperatorsChainable(
                                upstream, downstream, streamGraph, false))
                .isTrue();

        setChainingStrategy(downstream, ChainingStrategy.NEVER);
        assertThat(
                        StreamingJobGraphGenerator.areOperatorsChainable(
                                upstream, downstream, streamGraph, false))
                .isFalse();

        setChainingStrategy(downstream, ChainingStrategy.HEAD_WITH_SOURCES);
        assertThat(
                        StreamingJobGraphGenerator.areOperatorsChainable(
                                upstream, downstream, streamGraph, false))
                .isFalse();

        setChainingStrategy(downstream, ChainingStrategy.ALWAYS);
        setChainingStrategy(upstream, ChainingStrategy.NEVER);
        assertThat(
                        StreamingJobGraphGenerator.areOperatorsChainable(
                                upstream, downstream, streamGraph, false))
                .isFalse();
    }

