    @Test
    void testCreateChainedName() {
        StreamGraph streamGraph = createStreamGraph();
        StreamNode map = addNode(streamGraph, 1, "Map");
        StreamNode firstSink = addNode(streamGraph, 2, "SinkA");
        StreamNode secondSink = addNode(streamGraph, 3, "SinkB");
        StreamEdge firstEdge = addEdge(map, firstSink, 0, new ForwardPartitioner<>());
        StreamEdge secondEdge = addEdge(map, secondSink, 0, new ForwardPartitioner<>());
        JobVertexBuildContext context = buildContext(streamGraph, new JobGraph("test"));

        Map<Integer, String> chainedNames = new HashMap<>();
        chainedNames.put(2, "SinkA");
        chainedNames.put(3, "SinkB");

        assertThat(
                        StreamingJobGraphGenerator.createChainedName(
                                1,
                                Arrays.asList(firstEdge, secondEdge),
                                Optional.empty(),
                                chainedNames,
                                context))
                .isEqualTo("Map -> (SinkA, SinkB)");
        assertThat(
                        StreamingJobGraphGenerator.createChainedName(
                                1,
                                Collections.singletonList(firstEdge),
                                Optional.empty(),
                                chainedNames,
                                context))
                .isEqualTo("Map -> SinkA");
        assertThat(
                        StreamingJobGraphGenerator.createChainedName(
                                1,
                                Collections.emptyList(),
                                Optional.empty(),
                                chainedNames,
                                context))
                .isEqualTo("Map");
    }

    @Test
    void testCreateSourceChainInfoRegistersChainedSource() {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);
        env.fromData(1, 2, 3).map(value -> value + 1);

        StreamGraph streamGraph = env.getStreamGraph();
        Integer sourceId = streamGraph.getSourceIDs().iterator().next();
        StreamNode sourceNode = streamGraph.getStreamNode(sourceId);
        Integer targetId = sourceNode.getOutEdges().get(0).getTargetId();

        JobVertexBuildContext context = buildContext(streamGraph, new JobGraph("test"));
        Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
        StreamingJobGraphGenerator.createSourceChainInfo(
                sourceNode, chainEntryPoints, context);

        assertThat(chainEntryPoints).containsOnlyKeys(targetId);
        OperatorChainInfo chainInfo = chainEntryPoints.get(targetId);
        assertThat(chainInfo.getChainedSources()).containsKey(sourceId);
        assertThat(chainInfo.getAllChainedNodes()).containsExactly(sourceNode);
        assertThat(
                        chainInfo
                                .getChainedSources()
                                .get(sourceId)
                                .getOperatorConfig()
                                .getChainIndex())
                .isZero();
        assertThat(chainInfo.getCoordinatorProviders()).isNotEmpty();

        assertThat(
                        StreamingJobGraphGenerator.createChainedName(
                                targetId,
                                Collections.emptyList(),
                                Optional.of(chainInfo),
                                new HashMap<>(),
                                context))
                .isEqualTo("Map [Collection Source]");
    }

    @Test
    void testCreateChainedResourcesMergesOperatorResources() {
        StreamGraph streamGraph = createStreamGraph();
        StreamNode head = addNode(streamGraph, 1, "head");
        StreamNode chained = addNode(streamGraph, 2, "chained");
        head.setResources(
                ResourceSpec.newBuilder(1.0, 100).build(),
                ResourceSpec.newBuilder(1.0, 100).build());
        StreamEdge edge = addEdge(head, chained, 0, new ForwardPartitioner<>());

        OperatorChainInfo chainInfo = new OperatorChainInfo(1);
        chainInfo.addChainedMinResources(2, ResourceSpec.newBuilder(2.0, 200).build());
        chainInfo.addChainedPreferredResources(2, ResourceSpec.newBuilder(3.0, 300).build());
        JobVertexBuildContext context = buildContext(streamGraph, new JobGraph("test"));

        assertThat(
                        StreamingJobGraphGenerator.createChainedMinResources(
                                1, Collections.singletonList(edge), chainInfo, context))
                .isEqualTo(ResourceSpec.newBuilder(2.0, 300).build());
        assertThat(
                        StreamingJobGraphGenerator.createChainedPreferredResources(
                                1, Collections.singletonList(edge), chainInfo, context))
                .isEqualTo(ResourceSpec.newBuilder(3.0, 400).build());
        assertThat(
                        StreamingJobGraphGenerator.createChainedMinResources(
                                1, Collections.emptyList(), chainInfo, context))
                .isEqualTo(ResourceSpec.newBuilder(1.0, 100).build());
    }

