    @Test
    void testDetermineUndefinedResultPartitionTypeFromGlobalExchangeMode() {
        StreamGraph streamGraph = createStreamGraph();
        StreamNode upstream = addNode(streamGraph, 1, "upstream");
        StreamNode downstream = addNode(streamGraph, 2, "downstream");
        StreamNode otherDownstream = addNode(streamGraph, 3, "other");
        StreamEdge forwardEdge = addEdge(upstream, downstream, 0, new ForwardPartitioner<>());
        StreamEdge rescaleEdge = addEdge(upstream, otherDownstream, 0, new RescalePartitioner<>());
        JobVertexBuildContext context = buildContext(streamGraph, new JobGraph("test"));

        streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                forwardEdge, context))
                .isEqualTo(ResultPartitionType.BLOCKING);

        streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.FORWARD_EDGES_PIPELINED);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                forwardEdge, context))
                .isEqualTo(ResultPartitionType.PIPELINED_BOUNDED);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                rescaleEdge, context))
                .isEqualTo(ResultPartitionType.BLOCKING);

        streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.POINTWISE_EDGES_PIPELINED);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                rescaleEdge, context))
                .isEqualTo(ResultPartitionType.PIPELINED_BOUNDED);

        streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_PIPELINED);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                rescaleEdge, context))
                .isEqualTo(ResultPartitionType.PIPELINED_BOUNDED);

        streamGraph.setGlobalStreamExchangeMode(GlobalStreamExchangeMode.ALL_EDGES_HYBRID_SELECTIVE);
        assertThat(
                        StreamingJobGraphGenerator.determineUndefinedResultPartitionType(
                                rescaleEdge, context))
                .isEqualTo(ResultPartitionType.HYBRID_SELECTIVE);
    }

