                .isEqualTo(new OperatorID(hashes.get(2)));
        assertThat(context.getJobVertex(1)).isSameAs(jobVertex);
        assertThat(context.getJobGraph().findVertexByID(jobVertex.getID())).isSameAs(jobVertex);
    }

