    @Test
    void testTryConvertPartitionerForDynamicGraph() {
        StreamGraph streamGraph = createStreamGraph();
        streamGraph.setDynamic(true);
        StreamNode upstream = addNode(streamGraph, 1, "upstream");
        StreamNode forwardTarget = addNode(streamGraph, 2, "forwardTarget");
        StreamNode hashTarget = addNode(streamGraph, 3, "hashTarget");
        StreamNode rescaleTarget = addNode(streamGraph, 4, "rescaleTarget");
        StreamEdge chainableForwardEdge =
                addEdge(upstream, forwardTarget, 0, new ForwardForUnspecifiedPartitioner<>());
        StreamPartitioner<Integer> hashPartitioner = new RebalancePartitioner<>();
        StreamEdge nonChainableHashEdge =
                addEdge(
                        upstream,
                        hashTarget,
                        0,
                        new ForwardForConsecutiveHashPartitioner<>(hashPartitioner));
        StreamEdge nonChainableForwardEdge =
                addEdge(upstream, rescaleTarget, 0, new ForwardForUnspecifiedPartitioner<>());
        JobVertexBuildContext context = buildContext(streamGraph, new JobGraph("test"));

        StreamingJobGraphGenerator.tryConvertPartitionerForDynamicGraph(
                Collections.singletonList(chainableForwardEdge),
                Arrays.asList(nonChainableHashEdge, nonChainableForwardEdge),
                context);

        assertThat(chainableForwardEdge.getPartitioner())
                .isInstanceOf(ForwardPartitioner.class)
                .isNotInstanceOf(ForwardForUnspecifiedPartitioner.class);
        assertThat(nonChainableHashEdge.getPartitioner()).isSameAs(hashPartitioner);
        assertThat(nonChainableForwardEdge.getPartitioner())
                .isInstanceOf(RescalePartitioner.class);
    }

