    private static CheckpointConfig enabledCheckpointConfig() {
        CheckpointConfig checkpointConfig = new CheckpointConfig();
        checkpointConfig.setCheckpointInterval(100L);
        return checkpointConfig;
    }

    private static StreamGraph createStreamGraph() {
        return createStreamGraph(new CheckpointConfig());
    }

    private static StreamGraph createStreamGraph(CheckpointConfig checkpointConfig) {
        return new StreamGraph(
                new Configuration(),
                new ExecutionConfig(),
                checkpointConfig,
                SavepointRestoreSettings.none());
    }

    private static StreamNode addNode(StreamGraph streamGraph, int id, String operatorName) {
        return addNodeWithParallelism(streamGraph, id, operatorName, 0);
    }

    private static StreamNode addNodeWithParallelism(
            StreamGraph streamGraph, int id, String operatorName, int parallelism) {
        StreamNode node =
                streamGraph.addNode(
                        id,
                        StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP,
                        null,
                        OneInputStreamTask.class,
                        newOperatorFactory(),
                        operatorName);
        node.setParallelism(parallelism);
        node.setMaxParallelism(128);
        return node;
    }

    private static StreamNode addNodeWithCoLocation(
            StreamGraph streamGraph, int id, String operatorName, String coLocationGroup) {
        StreamNode node =
                streamGraph.addNode(
                        id,
                        StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP,
                        coLocationGroup,
                        OneInputStreamTask.class,
                        newOperatorFactory(),
                        operatorName);
        node.setParallelism(1);
        node.setMaxParallelism(128);
        return node;
    }

    private static SimpleOperatorFactory<Object> newOperatorFactory() {
        SimpleOperatorFactory<Object> factory = SimpleOperatorFactory.of(new DummyOperator());
        factory.setChainingStrategy(ChainingStrategy.ALWAYS);
        return factory;
    }

    private static void setChainingStrategy(StreamNode node, ChainingStrategy strategy) {
        node.getOperatorFactory().setChainingStrategy(strategy);
    }

    private static StreamEdge addEdge(
            StreamNode source,
            StreamNode target,
            int typeNumber,
            StreamPartitioner<?> partitioner) {
        StreamEdge edge = new StreamEdge(source, target, typeNumber, partitioner, null);
        source.addOutEdge(edge);
        target.addInEdge(edge);
        return edge;
    }

    private static JobVertexBuildContext buildContext(StreamGraph streamGraph, JobGraph jobGraph) {
        return new JobVertexBuildContext(
                jobGraph,
                streamGraph,
                new AtomicBoolean(false),
                hashesFor(streamGraph),
                Collections.emptyList(),
                new SlotSharingGroup());
    }

    private static Map<Integer, byte[]> hashesFor(StreamGraph streamGraph) {
        return new StreamGraphHasherV2().traverseStreamGraphAndGenerateHashes(streamGraph);
    }

    private static OperatorInfo createOperatorInfo(
            JobVertexBuildContext context, int chainStartNodeId) {
        OperatorChainInfo chainInfo = new OperatorChainInfo(chainStartNodeId);
        OperatorInfo operatorInfo =
                chainInfo.createAndGetOperatorInfo(chainStartNodeId, new OperatorID());
        operatorInfo.setVertexConfig(new StreamConfig(new Configuration()));
        context.addChainInfo(chainStartNodeId, chainInfo);
        return operatorInfo;
    }

    /** Plain operator that does not implement any special operator interface. */
    private static class DummyOperator extends AbstractStreamOperator<Object> {
        private static final long serialVersionUID = 1L;
    }

    /** Operator which makes the checkpointing validation fail because it selects its inputs. */
    private static class InputSelectableOperator extends AbstractStreamOperator<Object>
            implements InputSelectable {
        private static final long serialVersionUID = 1L;

        @Override
        public InputSelection nextSelection() {
            return InputSelection.FIRST;
        }
    }

    // Keep imports which are only used by helper methods referenced from tests.
    @SuppressWarnings("unused")
    private static final List<OutputTag<?>> UNUSED_OUTPUT_TAGS = new ArrayList<>();
}
