        return typeFactory.builder()
            .add("A", SqlTypeName.INTEGER)
            .add("B", SqlTypeName.VARCHAR, 10)
            .build();
      }
    });
    CalciteCatalogReader cr = new CalciteCatalogReader(root, Collections.emptyList(), tf, CalciteConnectionConfig.DEFAULT);
