import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.parser.SqlParser;
import org.apache.calcite.sql.type.*;
import org.apache.calcite.sql.validate.*;
import org.apache.calcite.config.CalciteConnectionConfig;
import java.util.*;
public class Probe8 {
  static RelDataTypeFactory tf=new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
  static SqlValidatorImpl v(){
    CalciteSchema root=CalciteSchema.createRootSchema(true);
    root.add("T", new AbstractTable(){ public RelDataType getRowType(RelDataTypeFactory f){
      return f.builder().add("A",SqlTypeName.INTEGER).add("B",SqlTypeName.VARCHAR,10).build();}});
    CalciteCatalogReader cr=new CalciteCatalogReader(root, Collections.emptyList(), tf, CalciteConnectionConfig.DEFAULT);
    return (SqlValidatorImpl) SqlValidatorUtil.newValidator(SqlStdOperatorTable.instance(), cr, tf, SqlValidator.Config.DEFAULT);
  }
  public static void main(String[] a) throws Exception {
    SqlValidatorImpl x=v();
    SqlNode q=SqlParser.create("SELECT 1 AS C, A AS X, B AS Y FROM T").parseQuery();
    SqlNode vq=x.validate(q);
    RelDataType t=x.getValidatedNodeType(vq);
    for(RelDataTypeField f: t.getFieldList()) System.out.println(f.getName()+" "+f.getType()+" nullable="+f.getType().isNullable());
    System.out.println("---expanded star---");
    SqlNode q2=SqlParser.create("SELECT * FROM T").parseQuery();
    SqlNode vq2=x.validate(q2);
    SqlNodeList ex=x.expandStar(((SqlSelect)vq2).getSelectList(),(SqlSelect)vq2,false);
    for(SqlNode n: ex) System.out.println(n+" kind="+n.getKind()+" type="+x.getValidatedNodeTypeIfKnown(n));
    System.out.println("---qualified star---");
    SqlNode q3=SqlParser.create("SELECT X.* FROM T AS X").parseQuery();
    SqlNode vq3=x.validate(q3);
    System.out.println("type="+x.getValidatedNodeType(vq3));
    System.out.println("expand="+x.expandStar(((SqlSelect)vq3).getSelectList(),(SqlSelect)vq3,false));
    System.out.println("---no from star---");
    try { SqlNode q4=SqlParser.create("SELECT *").parseQuery(); x.validate(q4); } catch(Throwable e){System.out.println(e.getClass().getSimpleName()+": "+e.getMessage());}
  }
}
