/** Tests for {@link SqlValidatorImpl}. */
public class SqlValidatorImplTests {

    private static final RelDataTypeFactory TYPE_FACTORY =
            new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);

    private static final SqlOperatorTable OPERATOR_TABLE = SqlStdOperatorTable.instance();

    private SqlValidatorImpl validator;

    @BeforeEach
    void setUp() {
        validator = newValidator();
    }

    // ---------------------------------------------------------------------
    // Validator setup and basic accessors
    // ---------------------------------------------------------------------

    @Test
    void exposesConfiguredCollaborators() {
        assertSame(TYPE_FACTORY, validator.getTypeFactory());
        assertSame(OPERATOR_TABLE, validator.getOperatorTable());
        assertNotNull(validator.getCatalogReader());
        assertNotNull(validator.getTimeFrameSet());
        assertEquals(SqlTypeName.UNKNOWN, validator.getUnknownType().getSqlTypeName());
        assertTrue(validator.getUnknownType().isNullable());
        assertEquals(SqlConformanceEnum.DEFAULT, validator.getConformance());
        assertNotNull(validator.getEmptyScope());
        assertSame(validator, validator.getEmptyScope().getValidator());
    }

    // ---------------------------------------------------------------------
    // SELECT validation
    // ---------------------------------------------------------------------

    @Test
    void validateSelectDerivesRowType() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT A AS X, B AS Y FROM T"));

        RelDataType rowType = validator.getValidatedNodeType(validated);
        assertEquals(2, rowType.getFieldCount());
        assertEquals("X", rowType.getFieldList().get(0).getName());
        assertEquals(SqlTypeName.INTEGER, rowType.getFieldList().get(0).getType().getSqlTypeName());
        assertEquals("Y", rowType.getFieldList().get(1).getName());
        assertEquals(SqlTypeName.VARCHAR, rowType.getFieldList().get(1).getType().getSqlTypeName());

        SqlNode selectItem = ((SqlSelect) validated).getSelectList().get(0);
        assertEquals(SqlTypeName.INTEGER, validator.getValidatedNodeType(selectItem).getSqlTypeName());
    }

    @Test
    void validateFunctionCallInfersType() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT ABS(-1) AS X"));

        RelDataType rowType = validator.getValidatedNodeType(validated);
        assertEquals(1, rowType.getFieldCount());
        assertEquals("X", rowType.getFieldList().get(0).getName());
        assertEquals(SqlTypeName.INTEGER, rowType.getFieldList().get(0).getType().getSqlTypeName());
    }

    @Test
    void validateRejectsInvalidFunctionArgumentCount() throws Exception {
        CalciteContextException exception =
                assertValidationError("SELECT ABS(1, 2)", "Invalid number of arguments to function 'ABS'");
        assertTrue(exception.getMessage().contains("Was expecting 1 arguments"), exception.getMessage());
    }

    @Test
    void validateRejectsUnknownFunction() throws Exception {
        assertValidationError(
                "SELECT NOSUCHFUNC(1)", "No match found for function signature NOSUCHFUNC");
    }

    @Test
    void validateRejectsUnknownColumn() throws Exception {
        assertValidationError("SELECT D FROM T", "Column 'D' not found in any table");
    }

    @Test
    void validateRejectsUnknownTable() throws Exception {
        assertValidationError("SELECT * FROM NOPE", "Object 'NOPE' not found");
    }

    @Test
    void validateRejectsStarWithoutFrom() throws Exception {
        assertValidationError("SELECT *", "SELECT * requires a FROM clause");
    }

    // ---------------------------------------------------------------------
    // Star expansion
    // ---------------------------------------------------------------------

    @Test
    void expandStarProducesQualifiedColumns() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT * FROM T"));
        SqlSelect select = (SqlSelect) validated;

        SqlNodeList expanded = validator.expandStar(select.getSelectList(), select, false);

        assertEquals(3, expanded.size());
        SqlIdentifier firstColumn = (SqlIdentifier) expanded.get(0);
        assertEquals(Arrays.asList("T", "A"), firstColumn.names);
        assertEquals(
                SqlTypeName.INTEGER, validator.getValidatedNodeType(firstColumn).getSqlTypeName());
        assertEquals(
                SqlTypeName.VARCHAR,
                validator.getValidatedNodeType(expanded.get(1)).getSqlTypeName());
        assertEquals(
                SqlTypeName.INTEGER, validator.getValidatedNodeType(expanded.get(2)).getSqlTypeName());
    }

    // ---------------------------------------------------------------------
    // Aggregate and window validation
    // ---------------------------------------------------------------------

    @Test
    void validateRejectsNonGroupedColumnInAggregateQuery() throws Exception {
        assertValidationError(
                "SELECT A, COUNT(*) FROM T", "Expression 'A' is not being grouped");
    }

    @Test
    void isAggregateDistinguishesAggregateQueries() throws Exception {
        SqlValidatorImpl aggregateValidator = newValidator();
        SqlSelect aggregateSelect =
                (SqlSelect)
                        aggregateValidator.validate(
                                parse("SELECT A, COUNT(*) FROM T GROUP BY A"));
        assertTrue(aggregateValidator.isAggregate(aggregateSelect));

        SqlValidatorImpl plainValidator = newValidator();
        SqlSelect plainSelect = (SqlSelect) plainValidator.validate(parse("SELECT A FROM T"));
        assertFalse(plainValidator.isAggregate(plainSelect));
    }

    @Test
    void validateRejectsAggregateInWhereClause() throws Exception {
        assertValidationError(
                "SELECT * FROM T WHERE SUM(A) > 1", "Aggregate expression is illegal in WHERE clause");
    }

    @Test
    void validateRejectsWindowAggregateInWhereClause() throws Exception {
        assertValidationError(
                "SELECT * FROM T WHERE ROW_NUMBER() OVER (ORDER BY A) = 1",
                "Windowed aggregate expression is illegal in WHERE clause");
    }

    @Test
    void validateRejectsNestedAggregate() throws Exception {
        assertValidationError(
                "SELECT SUM(COUNT(*)) FROM T", "Aggregate expressions cannot be nested");
    }

    // ---------------------------------------------------------------------
    // INSERT and VALUES validation
    // ---------------------------------------------------------------------

    @Test
    void validateRejectsInsertWithWrongNumberOfSourceItems() throws Exception {
        assertValidationError(
                "INSERT INTO T VALUES (1)",
                "Number of INSERT target columns (3) does not equal number of source items (1)");
    }

    @Test
    void validateValuesDerivesRowType() throws Exception {
        SqlNode validated = validator.validate(parse("VALUES (1, 'a')"));

        RelDataType rowType = validator.getValidatedNodeType(validated);
        assertEquals(2, rowType.getFieldCount());
        assertEquals("EXPR$0", rowType.getFieldList().get(0).getName());
        assertEquals(SqlTypeName.INTEGER, rowType.getFieldList().get(0).getType().getSqlTypeName());
        assertEquals("EXPR$1", rowType.getFieldList().get(1).getName());
        assertEquals(SqlTypeName.CHAR, rowType.getFieldList().get(1).getType().getSqlTypeName());
    }

