        RelDataType rowType = validator.getValidatedNodeType(validated);
        assertEquals(2, rowType.getFieldCount());
        assertEquals("X", rowType.getFieldList().get(0).getName());
        assertEquals(SqlTypeName.INTEGER, rowType.getFieldList().get(0).getType().getSqlTypeName());
        assertEquals("Y", rowType.getFieldList().get(1).getName());
        assertEquals(SqlTypeName.INTEGER, rowType.getFieldList().get(1).getType().getSqlTypeName());
    }

    @Test
    void validateUnpivotDerivesUnpivotedRowType() throws Exception {
        SqlNode validated =
                validator.validate(
                        parse("SELECT * FROM (SELECT A, C FROM T) UNPIVOT (V FOR K IN (A, C))"));

        RelDataType rowType = validator.getValidatedNodeType(validated);
        assertEquals(2, rowType.getFieldCount());
        assertEquals("K", rowType.getFieldList().get(0).getName());
        assertEquals(SqlTypeName.VARCHAR, rowType.getFieldList().get(0).getType().getSqlTypeName());
        assertEquals("V", rowType.getFieldList().get(1).getName());
