        assertEquals("CURRENT_DATE", call.getOperator().getName());
        assertEquals(0, call.operandCount());
        assertTrue(call.isExpanded());

        assertNull(validator.makeNullaryCall(new SqlIdentifier("NOT_A_FUNCTION", SqlParserPos.ZERO)));
