/**
 * Tests for {@link RexBuilder}.
 *
 * <p>All behaviour is exercised through the public API of the builder, using a real {@link
 * FlinkTypeFactory} rather than mocks so that derived types are the ones the planner really sees.
 */
class RexBuilderTests {

    private static final RelDataTypeFactory TYPE_FACTORY =
            new FlinkTypeFactory(RexBuilderTests.class.getClassLoader());

    private RexBuilder rexBuilder;

    @BeforeEach
    void setUp() {
        rexBuilder = new RexBuilder(TYPE_FACTORY);
    }

    // ~ helpers ---------------------------------------------------------------

    private static RelDataType nullableSqlType(SqlTypeName typeName) {
        return TYPE_FACTORY.createSqlType(typeName);
    }

    private static RelDataType notNull(RelDataType type) {
        return TYPE_FACTORY.createTypeWithNullability(type, false);
    }

    private RelDataType rowType() {
        return TYPE_FACTORY
                .builder()
                .add("A", nullableSqlType(SqlTypeName.INTEGER))
                .add("B", nullableSqlType(SqlTypeName.VARCHAR))
                .build();
    }

    private RexNode intLiteral(int value) {
        return rexBuilder.makeExactLiteral(BigDecimal.valueOf(value));
    }

    private RexNode intInputRef(int index) {
        return rexBuilder.makeInputRef(nullableSqlType(SqlTypeName.INTEGER), index);
    }

    // ~ accessors -------------------------------------------------------------

    @Test
    void getTypeFactory_returnsTypeFactoryUsedAtConstruction() {
        assertThat(rexBuilder.getTypeFactory()).isSameAs(TYPE_FACTORY);
    }

    @Test
    void getOpTab_returnsStandardOperatorTable() {
        assertThat(rexBuilder.getOpTab()).isSameAs(SqlStdOperatorTable.instance());
    }

    @Test
    void identityProjects_createsOneInputRefPerField() {
        final RelDataType rowType = rowType();

        final List<RexNode> projects = rexBuilder.identityProjects(rowType);

        assertThat(projects).hasSize(2);
        assertThat(projects.get(0)).isInstanceOf(RexInputRef.class);
        assertThat(((RexInputRef) projects.get(0)).getIndex()).isEqualTo(0);
        assertThat(projects.get(0).getType()).isEqualTo(rowType.getFieldList().get(0).getType());
        assertThat(((RexInputRef) projects.get(1)).getIndex()).isEqualTo(1);
        assertThat(projects.get(1).getType().getSqlTypeName()).isEqualTo(SqlTypeName.VARCHAR);
    }

    // ~ field access ----------------------------------------------------------

    @Test
    void makeFieldAccess_byName_isCaseSensitiveWhenRequested() {
        final RelDataType rowType = rowType();
        final RexNode reference = rexBuilder.makeInputRef(rowType, 0);

        final RexNode fieldAccess = rexBuilder.makeFieldAccess(reference, "B", true);

        assertThat(fieldAccess).isInstanceOf(RexFieldAccess.class);
        final RexFieldAccess access = (RexFieldAccess) fieldAccess;
        assertThat(access.getField().getName()).isEqualTo("B");
        assertThat(access.getField().getIndex()).isEqualTo(1);
        assertThat(access.getType().getSqlTypeName()).isEqualTo(SqlTypeName.VARCHAR);
        assertThat(access.getReferenceExpr()).isSameAs(reference);
    }

    @Test
    void makeFieldAccess_byName_failsForUnknownCaseSensitiveField() {
        final RexNode reference = rexBuilder.makeInputRef(rowType(), 0);

        assertThatThrownBy(() -> rexBuilder.makeFieldAccess(reference, "b", true))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("has no field 'b'");
    }

    @Test
    void makeFieldAccess_byName_matchesIgnoringCaseWhenNotCaseSensitive() {
        final RexNode reference = rexBuilder.makeInputRef(rowType(), 0);

        final RexNode fieldAccess = rexBuilder.makeFieldAccess(reference, "b", false);

        assertThat(((RexFieldAccess) fieldAccess).getField().getName()).isEqualTo("B");
    }

    @Test
    void makeFieldAccess_byOrdinal_makesFieldNullableForNullableReference() {
        final RelDataType rowType =
                TYPE_FACTORY
                        .builder()
                        .add("A", notNull(nullableSqlType(SqlTypeName.INTEGER)))
                        .build();
        final RelDataType nullableRowType = TYPE_FACTORY.createTypeWithNullability(rowType, true);
        final RelDataType notNullRowType = TYPE_FACTORY.createTypeWithNullability(rowType, false);

        final RexNode fromNullable = rexBuilder.makeFieldAccess(
                rexBuilder.makeInputRef(nullableRowType, 0), 0);
        final RexNode fromNotNull = rexBuilder.makeFieldAccess(
                rexBuilder.makeInputRef(notNullRowType, 0), 0);

        assertThat(fromNullable.getType().isNullable()).isTrue();
        assertThat(fromNotNull.getType().isNullable()).isFalse();
        assertThat(fromNotNull.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTEGER);
    }

    @Test
    void makeFieldAccess_byOrdinal_rejectsInvalidOrdinals() {
        final RexNode reference = rexBuilder.makeInputRef(rowType(), 0);

        assertThatThrownBy(() -> rexBuilder.makeFieldAccess(reference, 2))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("Field ordinal 2 is invalid");
        assertThatThrownBy(() -> rexBuilder.makeFieldAccess(reference, -1))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("Field ordinal -1 is invalid");
    }

    @Test
    void makeFieldAccess_onRangeReference_shiftsFieldIndexByOffset() {
        final RelDataType rowType = rowType();
        final RexRangeRef range = rexBuilder.makeRangeReference(rowType, 5, false);

        final RexNode access = rexBuilder.makeFieldAccess(range, 1);

