import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class SimpleRunner {
    public static void main(String[] args) throws Exception {
        Class<?> testClass = Class.forName(args[0]);
        List<Method> beforeEach = new ArrayList<>();
        for (Method m : testClass.getDeclaredMethods()) {
            if (m.isAnnotationPresent(BeforeEach.class)) {
                beforeEach.add(m);
            }
        }
        int pass = 0;
        List<String> failures = new ArrayList<>();
        Method[] methods = testClass.getDeclaredMethods();
        java.util.Arrays.sort(methods, java.util.Comparator.comparing(Method::getName));
        for (Method m : methods) {
            if (!m.isAnnotationPresent(Test.class)) {
                continue;
            }
            Object instance = testClass.getDeclaredConstructor().newInstance();
            try {
                for (Method b : beforeEach) {
                    b.setAccessible(true);
                    b.invoke(instance);
                }
                m.setAccessible(true);
                m.invoke(instance);
                pass++;
            } catch (Throwable t) {
                Throwable cause = t.getCause() != null ? t.getCause() : t;
                failures.add(m.getName() + " -> " + cause.getClass().getName() + ": " + cause.getMessage());
            }
        }
        System.out.println("PASSED: " + pass + ", FAILED: " + failures.size());
        for (String f : failures) {
            System.out.println("  FAIL " + f);
        }
    }
}
EOF
cd /tmp/runner && javac -cp "$(cat /tmp/cp.txt)" -d /tmp/runner SimpleRunner.java && echo compiled"}

