    // ~ literals --------------------------------------------------------------

    @Test
    void makeLiteral_emptyStringReusesCachedLiteral() {
        final RexLiteral first = rexBuilder.makeLiteral("");
        final RexLiteral second = rexBuilder.makeLiteral("");

        assertThat(first).isSameAs(second);
        assertThat(first.getTypeName()).isEqualTo(SqlTypeName.CHAR);
        assertThat(RexLiteral.stringValue(first)).isEmpty();
        assertThat(first.isNull()).isFalse();
    }

    @Test
    void makeLiteral_stringLiteralHasCharTypeOfValueLength() {
        final RexLiteral literal = rexBuilder.makeLiteral("abc");

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.CHAR);
        assertThat(literal.getType().getPrecision()).isEqualTo(3);
        assertThat(RexLiteral.stringValue(literal)).isEqualTo("abc");
    }

    @Test
    void makeLiteral_padsCharValueToTypePrecision() {
        final RelDataType charType = TYPE_FACTORY.createSqlType(SqlTypeName.CHAR, 5);

        final RexLiteral literal =
                (RexLiteral) rexBuilder.makeLiteral("foo", charType);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.CHAR);
        assertThat(literal.getType().getPrecision()).isEqualTo(5);
        assertThat(RexLiteral.stringValue(literal)).isEqualTo("foo  ");
    }

    @Test
    void makeLiteral_trimsCharValueWhenRequested() {
        final RelDataType charType = TYPE_FACTORY.createSqlType(SqlTypeName.CHAR, 5);

        final RexNode node = rexBuilder.makeLiteral("foo  ", charType, false, true);

        assertThat(node).isInstanceOf(RexLiteral.class);
        assertThat(node.getType().getPrecision()).isEqualTo(3);
        assertThat(RexLiteral.stringValue((RexLiteral) node)).isEqualTo("foo");
    }

    @Test
    void makeLiteral_padsBinaryValueToTypePrecision() {
        final RelDataType binaryType = TYPE_FACTORY.createSqlType(SqlTypeName.BINARY, 3);

        final RexLiteral literal = (RexLiteral) rexBuilder.makeLiteral(
                new ByteString(new byte[] {1}), binaryType);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.BINARY);
        assertThat(((ByteString) literal.getValue()).length()).isEqualTo(3);
        assertThat(((ByteString) literal.getValue()).getBytes()[2]).isEqualTo((byte) 0);
    }

    @Test
    void makeLiteral_nullValueProducesTypedNullLiteral() {
        final RelDataType varcharType = nullableSqlType(SqlTypeName.VARCHAR);

        final RexNode node = rexBuilder.makeLiteral(null, varcharType);

        assertThat(node).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) node).isNull()).isTrue();
        assertThat(node.getType().isNullable()).isTrue();
        assertThat(node.getType().getSqlTypeName()).isEqualTo(SqlTypeName.VARCHAR);
    }

    @Test
    void makeLiteral_decimalValueExceedingTypePrecisionIsRejected() {
        final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 2, 0);

        assertThatThrownBy(() -> rexBuilder.makeLiteral(new BigDecimal("100"), decimalType))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("due to overflow");
    }

    @Test
    void makeLiteral_unsupportedTypeIsRejected() {
        final RelDataType nullType = TYPE_FACTORY.createSqlType(SqlTypeName.NULL);

        assertThatThrownBy(() -> rexBuilder.makeLiteral("x", nullType))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Cannot create literal for type 'NULL'");
    }

    @Test
    void makeLiteral_arrayValueBuildsArrayConstructorCall() {
        final RelDataType arrayType = TYPE_FACTORY.createArrayType(
                nullableSqlType(SqlTypeName.INTEGER), -1);

        final RexNode node = rexBuilder.makeLiteral(Arrays.asList(1, 2, 3), arrayType);

        assertThat(node).isInstanceOf(RexCall.class);
        assertThat(node.getKind()).isEqualTo(SqlKind.ARRAY_VALUE_CONSTRUCTOR);
        final List<RexNode> operands = ((RexCall) node).getOperands();
        assertThat(operands).hasSize(3);
        assertThat(((RexLiteral) operands.get(2)).getValueAs(Comparable.class))
                .isEqualTo(new BigDecimal(3));
    }

    @Test
    void makeLiteral_mapValueBuildsMapConstructorCall() {
        final RelDataType mapType = TYPE_FACTORY.createMapType(
                nullableSqlType(SqlTypeName.VARCHAR),
                nullableSqlType(SqlTypeName.INTEGER));
        final Map<Object, Object> map = new LinkedHashMap<>();
        map.put("k1", 1);
        map.put("k2", 2);

        final RexNode node = rexBuilder.makeLiteral(map, mapType);

        assertThat(node).isInstanceOf(RexCall.class);
        assertThat(node.getKind()).isEqualTo(SqlKind.MAP_VALUE_CONSTRUCTOR);
        assertThat(((RexCall) node).getOperands()).hasSize(4);
        assertThat(RexLiteral.stringValue((RexLiteral) ((RexCall) node).getOperands().get(0)))
                .isEqualTo("k1");
    }

    @Test
    void makeLiteral_rowValueProducesCompositeLiteral() {
        final RelDataType rowType = TYPE_FACTORY
                .builder()
                .add("a", nullableSqlType(SqlTypeName.INTEGER))
                .add("b", nullableSqlType(SqlTypeName.VARCHAR))
                .build();

        final RexNode node = rexBuilder.makeLiteral(Arrays.asList(1, "x"), rowType);

        assertThat(node).isInstanceOf(RexLiteral.class);
        assertThat(node.getType().getSqlTypeName()).isEqualTo(SqlTypeName.ROW);
        final Object value = ((RexLiteral) node).getValue();
        assertThat(value).isInstanceOf(List.class);
        final List<?> fields = (List<?>) value;
        assertThat(fields).hasSize(2);
        assertThat(((RexLiteral) fields.get(0)).getValueAs(Comparable.class))
                .isEqualTo(new BigDecimal(1));
        assertThat(RexLiteral.stringValue((RexLiteral) fields.get(1))).isEqualTo("x");
    }

    @Test
    void makeLiteral_anyTypeUsesGuessedType() {
        final RelDataType anyType = TYPE_FACTORY.createSqlType(SqlTypeName.ANY);

        final RexNode node = rexBuilder.makeLiteral(BigDecimal.valueOf(7), anyType);

        assertThat(node).isInstanceOf(RexLiteral.class);
        assertThat(node.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
    }

    @Test
    void makeExactLiteral_choosesIntegerForSmallScaleZeroValues() {
        final RexLiteral literal = rexBuilder.makeExactLiteral(BigDecimal.valueOf(42));

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTEGER);
    }

    @Test
    void makeExactLiteral_choosesBigintOutsideIntegerRange() {
        final BigDecimal beyondInt = BigDecimal.valueOf(Integer.MAX_VALUE).add(BigDecimal.ONE);

        final RexLiteral literal = rexBuilder.makeExactLiteral(beyondInt);
        final RexLiteral belowInt = rexBuilder.makeExactLiteral(
                BigDecimal.valueOf(Integer.MIN_VALUE).subtract(BigDecimal.ONE));

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
        assertThat(belowInt.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
    }

    @Test
    void makeExactLiteral_choosesDecimalWithDerivedPrecisionAndScale() {
        final RexLiteral atLeastOne = rexBuilder.makeExactLiteral(new BigDecimal("1.23"));
        final RexLiteral belowOne = rexBuilder.makeExactLiteral(new BigDecimal("0.123"));

        assertThat(atLeastOne.getType().getPrecision()).isEqualTo(3);
        assertThat(atLeastOne.getType().getScale()).isEqualTo(2);
        assertThat(belowOne.getType().getPrecision()).isEqualTo(4);
        assertThat(belowOne.getType().getScale()).isEqualTo(3);
    }

    @Test
    void makeExactLiteral_withNullValueProducesNullLiteral() {
        final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 2);

        final RexLiteral literal = rexBuilder.makeExactLiteral(null, decimalType);

        assertThat(literal.isNull()).isTrue();
        assertThat(literal.getType().isNullable()).isTrue();
    }

    @Test
    void makeBigintLiteral_alwaysUsesBigintType() {
        final RexLiteral literal = rexBuilder.makeBigintLiteral(BigDecimal.valueOf(3));

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
        assertThat(literal.getValueAs(Comparable.class)).isEqualTo(new BigDecimal(3));
        assertThat(rexBuilder.makeBigintLiteral(null).isNull()).isTrue();
    }

    @Test
    void makeApproxLiteral_usesDoubleTypeAndValue() {
        final RexLiteral literal = rexBuilder.makeApproxLiteral(new BigDecimal("1.5"));

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.DOUBLE);
        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.DOUBLE);
        assertThat(literal.getValueAs(Double.class)).isEqualTo(1.5);
    }

    @Test
    void makeApproxLiteral_underflowingValueBecomesZero() {
        final RexLiteral literal = rexBuilder.makeApproxLiteral(new BigDecimal("1E-400"));

        assertThat(literal.getValueAs(Double.class)).isEqualTo(0.0);
    }

    @Test
    void makeApproxLiteral_fromDoubleKeepsValue() {
        final RelDataType realType = TYPE_FACTORY.createSqlType(SqlTypeName.REAL);

        final RexLiteral literal = rexBuilder.makeApproxLiteral(2.75, realType);

        assertThat(literal.getValueAs(Double.class)).isEqualTo(2.75);
        assertThat(literal.getType()).isEqualTo(realType);
    }

    @Test
    void makeBinaryLiteral_usesLengthAsPrecision() {
        final ByteString bytes = new ByteString(new byte[] {1, 2, 3});

        final RexLiteral literal = rexBuilder.makeBinaryLiteral(bytes);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.BINARY);
        assertThat(literal.getType().getPrecision()).isEqualTo(3);
        assertThat(literal.getValue()).isEqualTo(bytes);
    }

    @Test
    void makeCharLiteral_populatesCharsetAndCollation() {
        final RexLiteral literal = rexBuilder.makeCharLiteral(new NlsString("abc", null, null));

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.CHAR);
        assertThat(literal.getType().getPrecision()).isEqualTo(3);
        assertThat(literal.getType().getCharset()).isNotNull();
        assertThat(literal.getType().getCollation()).isNotNull();
        assertThat(RexLiteral.stringValue(literal)).isEqualTo("abc");
    }

    @Test
    void makeFlag_producesSymbolLiteral() {
        final RexLiteral literal = rexBuilder.makeFlag(TimeUnitRange.YEAR_TO_MONTH);

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.SYMBOL);
        assertThat(literal.getValue()).isEqualTo(TimeUnitRange.YEAR_TO_MONTH);
    }

    @Test
    void makeFlag_rejectsNullFlag() {
        assertThatThrownBy(() -> rexBuilder.makeFlag(null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("flag");
    }

    @Test
    void makeDateLiteral_keepsValueAndDateType() {
        final RexLiteral literal = rexBuilder.makeDateLiteral(DateString.parse("2020-02-29"));

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.DATE);
        assertThat(literal.getValueAs(Comparable.class).toString()).isEqualTo("2020-02-29");
        assertThat(literal.isNull()).isFalse();
    }

    @Test
    void makeTimeLiteral_appliesPrecisionAndRounds() {
        final RexLiteral millis = rexBuilder.makeTimeLiteral(new TimeString("12:34:56.789"), 3);
        final RexLiteral seconds = rexBuilder.makeTimeLiteral(new TimeString("12:34:56.789"), 0);

        assertThat(millis.getTypeName()).isEqualTo(SqlTypeName.TIME);
        assertThat(millis.getType().getPrecision()).isEqualTo(3);
        assertThat(millis.getValueAs(Comparable.class).toString()).isEqualTo("12:34:56.789");
        assertThat(seconds.getType().getPrecision()).isEqualTo(0);
        assertThat(seconds.getValueAs(Comparable.class).toString()).isEqualTo("12:34:57");
    }

    @Test
    void makeTimeWithLocalTimeZoneLiteral_usesLocalTimeZoneType() {
        final RexLiteral literal =
                rexBuilder.makeTimeWithLocalTimeZoneLiteral(new TimeString("01:02:03"), 1);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIME_WITH_LOCAL_TIME_ZONE);
        assertThat(literal.getType().getPrecision()).isEqualTo(1);
        assertThat(literal.getValueAs(Comparable.class).toString()).isEqualTo("01:02:03.0");
    }

    @Test
    void makeTimeTzLiteral_usesTimeTzType() {
        final TimeWithTimeZoneString time =
                new TimeWithTimeZoneString(new TimeString("01:02:03.4"), TimeZone.getTimeZone("GMT+02:00"));

        final RexLiteral literal = rexBuilder.makeTimeTzLiteral(time, 1);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIME_TZ);
        assertThat(literal.getType().getPrecision()).isEqualTo(1);
        assertThat(literal.getValueAs(Comparable.class).toString()).contains("GMT+02:00");
    }

    @Test
    void makeTimestampLiteral_appliesPrecisionAndRounds() {
        final RexLiteral millis = rexBuilder.makeTimestampLiteral(
                TimestampString.parse("2020-01-02 03:04:05.678"), 3);
        final RexLiteral seconds = rexBuilder.makeTimestampLiteral(
                TimestampString.parse("2020-01-02 03:04:05.678"), 0);

        assertThat(millis.getTypeName()).isEqualTo(SqlTypeName.TIMESTAMP);
        assertThat(millis.getType().getPrecision()).isEqualTo(3);
        assertThat(millis.getValueAs(Comparable.class).toString())
                .isEqualTo("2020-01-02 03:04:05.678");
        assertThat(seconds.getType().getPrecision()).isEqualTo(0);
        assertThat(seconds.getValueAs(Comparable.class).toString())
                .isEqualTo("2020-01-02 03:04:06");
    }

    @Test
    void makeTimestampWithLocalTimeZoneLiteral_usesLocalTimeZoneType() {
        final RexLiteral literal = rexBuilder.makeTimestampWithLocalTimeZoneLiteral(
                TimestampString.parse("2020-01-02 03:04:05"), 0);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE);
        assertThat(literal.getValueAs(Comparable.class).toString())
                .isEqualTo("2020-01-02 03:04:05");
    }

    @Test
    void makeTimestampTzLiteral_usesTimestampTzType() {
        final RexLiteral literal = rexBuilder.makeTimestampTzLiteral(
                org.apache.calcite.util.TimestampWithTimeZoneString.fromCalendarFields(
                        java.util.Calendar.getInstance(TimeZone.getTimeZone("GMT+02:00"))),
                0);

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIMESTAMP_TZ);
        assertThat(literal.getType().getPrecision()).isEqualTo(0);
    }

    @Test
    void makeIntervalLiteral_fromQualifierProducesFlagLiteral() {
        final SqlIntervalQualifier qualifier =
                new SqlIntervalQualifier(TimeUnit.YEAR, TimeUnit.MONTH, SqlParserPos.ZERO);

        final RexLiteral literal = rexBuilder.makeIntervalLiteral(qualifier);

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.SYMBOL);
        assertThat(literal.getValue()).isEqualTo(TimeUnitRange.YEAR_TO_MONTH);
    }

    @Test
    void makeIntervalLiteral_fromTimeFrameNameProducesStringLiteral() {
        final SqlIntervalQualifier qualifier = new SqlIntervalQualifier("DOW", SqlParserPos.ZERO);

        final RexLiteral literal = rexBuilder.makeIntervalLiteral(qualifier);

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.CHAR);
        assertThat(RexLiteral.stringValue(literal)).isEqualTo("DOW");
    }

    @Test
    void makeIntervalLiteral_fromValueUsesIntervalType() {
        final SqlIntervalQualifier qualifier =
                new SqlIntervalQualifier(TimeUnit.DAY, null, SqlParserPos.ZERO);

        final RexLiteral literal = rexBuilder.makeIntervalLiteral(BigDecimal.valueOf(3), qualifier);

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTERVAL_DAY);
        assertThat(literal.getValueAs(Comparable.class)).isEqualTo(new BigDecimal(3));
    }

    @Test
    void makeNullLiteral_makesTypeNullable() {
        final RelDataType intType = notNull(nullableSqlType(SqlTypeName.INTEGER));

        final RexLiteral literal = rexBuilder.makeNullLiteral(intType);

        assertThat(literal.isNull()).isTrue();
        assertThat(literal.getType().isNullable()).isTrue();
        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTEGER);
    }

    @Test
    void constantNull_isCachedNullLiteral() {
        final RexLiteral nullLiteral = rexBuilder.constantNull();

        assertThat(nullLiteral).isSameAs(rexBuilder.constantNull());
        assertThat(nullLiteral.isNull()).isTrue();
        assertThat(nullLiteral.getTypeName()).isEqualTo(SqlTypeName.NULL);
    }

    @Test
    void makeUuidLiteral_usesUuidType() {
        final UUID uuid = UUID.fromString("00000000-0000-0000-0000-000000000001");

        final RexLiteral literal = rexBuilder.makeUuidLiteral(uuid);

        assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.UUID);
        assertThat(literal.getValue()).isEqualTo(uuid);
    }

    @Test
    void makeSearchArgumentLiteral_keepsSargValue() {
        final Sarg<BigDecimal> sarg = Sarg.of(RexUnknownAs.UNKNOWN,
                ImmutableRangeSet.of(Range.closed(BigDecimal.ONE, BigDecimal.TEN)));

        final RexLiteral literal = rexBuilder.makeSearchArgumentLiteral(
                sarg, nullableSqlType(SqlTypeName.INTEGER));

        assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.SARG);
        assertThat(literal.getValue()).isSameAs(sarg);
    }

    @Test
    void makeZeroLiteral_usesTypeSpecificDefaults() {
        final RexLiteral integer =
                rexBuilder.makeZeroLiteral(nullableSqlType(SqlTypeName.INTEGER));
        final RexLiteral bool = rexBuilder.makeZeroLiteral(nullableSqlType(SqlTypeName.BOOLEAN));
        final RexLiteral charLiteral = rexBuilder.makeZeroLiteral(
                TYPE_FACTORY.createSqlType(SqlTypeName.CHAR, 3));
        final RexLiteral varchar =
                rexBuilder.makeZeroLiteral(nullableSqlType(SqlTypeName.VARCHAR));
        final RexLiteral binary = rexBuilder.makeZeroLiteral(
                TYPE_FACTORY.createSqlType(SqlTypeName.BINARY, 2));
        final RexLiteral timestamp =
                rexBuilder.makeZeroLiteral(nullableSqlType(SqlTypeName.TIMESTAMP));
        final RexLiteral date = rexBuilder.makeZeroLiteral(nullableSqlType(SqlTypeName.DATE));

        assertThat(integer.getValueAs(Comparable.class)).isEqualTo(BigDecimal.ZERO);
        assertThat(RexLiteral.booleanValue(bool)).isFalse();
        assertThat(RexLiteral.stringValue(charLiteral)).isEqualTo("   ");
        assertThat(charLiteral.getType().getPrecision()).isEqualTo(3);
        assertThat(RexLiteral.stringValue(varchar)).isEmpty();
        assertThat(((ByteString) binary.getValue()).length()).isEqualTo(2);
        assertThat(timestamp.getValueAs(Comparable.class).toString())
                .isEqualTo("1970-01-01 00:00:00");
        assertThat(date.getValueAs(Comparable.class).toString()).isEqualTo("1970-01-01");
    }

    @Test
    void makeZeroLiteral_unsupportedTypeFails() {
        final RelDataType nullType = TYPE_FACTORY.createSqlType(SqlTypeName.NULL);

        assertThatThrownBy(() -> rexBuilder.makeZeroLiteral(nullType))
                .isInstanceOf(Error.class);
    }
