    // ~ casts ----------------------------------------------------------------

    @Test
    void makeCast_foldsCastOfLiteralIntoLiteral() {
        final RelDataType doubleType = nullableSqlType(SqlTypeName.DOUBLE);

        final RexNode casted = rexBuilder.makeCast(doubleType, intLiteral(10));

        assertThat(casted).isInstanceOf(RexLiteral.class);
        assertThat(casted.getType().getSqlTypeName()).isEqualTo(SqlTypeName.DOUBLE);
        assertThat(((RexLiteral) casted).getValueAs(Double.class)).isEqualTo(10.0);
    }

    @Test
    void makeCast_keepsCastWhenLiteralDoesNotFitType() {
        final RelDataType tinyintType = nullableSqlType(SqlTypeName.TINYINT);

        final RexNode casted = rexBuilder.makeCast(tinyintType, intLiteral(1000));

        assertThat(casted).isInstanceOf(RexCall.class);
        final RexCall call = (RexCall) casted;
        assertThat(call.getOperator()).isSameAs(SqlStdOperatorTable.CAST);
        assertThat(call.getType()).isEqualTo(tinyintType);
        assertThat(call.getOperands()).hasSize(1);
        assertThat(call.getOperands().get(0)).isInstanceOf(RexLiteral.class);
    }

    @Test
    void makeCast_toBooleanFromExactNumericComparesWithZero() {
        final RelDataType booleanType = nullableSqlType(SqlTypeName.BOOLEAN);

        final RexNode casted = rexBuilder.makeCast(booleanType, intInputRef(0));

        assertThat(casted.getKind()).isEqualTo(SqlKind.NOT_EQUALS);
        final List<RexNode> operands = ((RexCall) casted).getOperands();
        assertThat(operands).hasSize(2);
        assertThat(operands.get(0)).isInstanceOf(RexInputRef.class);
        assertThat(((RexLiteral) operands.get(1)).getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.ZERO);
    }

    @Test
    void makeCast_booleanLiteralToExactNumericUsesCaseExpression() {
        final RelDataType intType = nullableSqlType(SqlTypeName.INTEGER);

        final RexNode casted = rexBuilder.makeCast(intType, rexBuilder.makeLiteral(true));

        assertThat(casted.getKind()).isEqualTo(SqlKind.CASE);
        final List<RexNode> operands = ((RexCall) casted).getOperands();
        assertThat(operands).hasSize(3);
        assertThat(operands.get(0)).isInstanceOf(RexLiteral.class);
        assertThat(RexLiteral.booleanValue(operands.get(0))).isTrue();
        assertThat(((RexLiteral) operands.get(1)).getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.ONE);
    }

    @Test
    void makeCast_booleanExpressionToExactNumericAddsNullCheck() {
        final RelDataType nullableBoolean =
                TYPE_FACTORY.createTypeWithNullability(nullableSqlType(SqlTypeName.BOOLEAN), true);
        final RexNode booleanRef = rexBuilder.makeInputRef(nullableBoolean, 0);

        final RexNode casted = rexBuilder.makeCast(nullableSqlType(SqlTypeName.INTEGER), booleanRef);

        final List<RexNode> operands = ((RexCall) casted).getOperands();
        assertThat(((RexCall) operands.get(0)).getKind()).isEqualTo(SqlKind.IS_NOT_NULL);
        assertThat(operands.get(1).getKind()).isEqualTo(SqlKind.CASE);
        assertThat(operands.get(2)).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) operands.get(2)).isNull()).isTrue();
    }

    @Test
    void makeCast_intervalToExactNumericDecodesAndConverts() {
        final SqlIntervalQualifier qualifier =
                new SqlIntervalQualifier(TimeUnit.DAY, null, SqlParserPos.ZERO);
        final RelDataType intervalType = TYPE_FACTORY.createSqlIntervalType(qualifier);
        final RexNode intervalRef = rexBuilder.makeInputRef(intervalType, 0);

        final RexNode casted =
                rexBuilder.makeCast(nullableSqlType(SqlTypeName.INTEGER), intervalRef);

        assertThat(casted.getKind()).isEqualTo(SqlKind.CAST);
        final RexNode decoded = ((RexCall) casted).getOperands().get(0);
        assertThat(decoded.getKind()).isEqualTo(SqlKind.DIVIDE_INTEGER);
        final List<RexNode> operands = ((RexCall) decoded).getOperands();
        assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.REINTERPRET);
        assertThat(((RexLiteral) operands.get(1)).getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.valueOf(TimeUnit.DAY.multiplier.longValue()));
    }

