                TYPE_FACTORY.createTypeWithNullability(
                        TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 4, 0), true);

        final RexNode withMatch = rexBuilder.makeCast(nullableDecimal, intLiteral(5), true, false);
        final RexNode withoutMatch =
                rexBuilder.makeCast(nullableDecimal, intLiteral(5), false, false);

        assertThat(withMatch.getKind()).isEqualTo(SqlKind.CAST);
        assertThat(withMatch.getType().isNullable()).isTrue();
        assertThat(withoutMatch).isInstanceOf(RexLiteral.class);
        assertThat(withoutMatch.getType().getSqlTypeName()).isEqualTo(SqlTypeName.DECIMAL);
