        assertThat(casted.getKind()).isEqualTo(SqlKind.CAST);
        final RexNode decoded = ((RexCall) casted).getOperands().get(0);
        assertThat(decoded.getKind()).isEqualTo(SqlKind.DIVIDE_INTEGER);
        final List<RexNode> operands = ((RexCall) decoded).getOperands();
        assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.REINTERPRET);
        assertThat(((RexLiteral) operands.get(1)).getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.valueOf(TimeUnit.DAY.multiplier.longValue()));
    }

    @Test
    void makeCast_matchesNullabilityOfTargetTypeWhenRequested() {
        final RelDataType nullableDecimal =
                TYPE_FACTORY.createTypeWithNullability(
                        TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 4, 0), true);

        final RexNode withMatch = rexBuilder.makeCast(nullableDecimal, intLiteral(5), true, false);
        final RexNode withoutMatch =
                rexBuilder.makeCast(nullableDecimal, intLiteral(5), false, false);

        assertThat(withMatch.getKind()).isEqualTo(SqlKind.CAST);
        assertThat(withMatch.getType().isNullable()).isTrue();
        assertThat(withoutMatch).isInstanceOf(RexLiteral.class);
        assertThat(withoutMatch.getType().getSqlTypeName()).isEqualTo(SqlTypeName.DECIMAL);
    }

    @Test
    void makeCast_safeCastUsesSafeCastOperator() {
        final RexNode casted = rexBuilder.makeCast(
                nullableSqlType(SqlTypeName.DOUBLE), intInputRef(0), false, true);

        assertThat(casted).isInstanceOf(RexCall.class);
        assertThat(((RexCall) casted).getOperator()).isSameAs(SqlLibraryOperators.SAFE_CAST);
        assertThat(((RexCall) casted).getOperands()).hasSize(1);
    }

    @Test
    void makeAbstractCast_addsFormatOperandOnlyWhenNotLiteralNull() {
        final RelDataType varcharType =
                TYPE_FACTORY.createSqlType(SqlTypeName.VARCHAR, 10);
        final RexNode ref = intInputRef(0);

        final RexNode withoutFormat =
                rexBuilder.makeAbstractCast(varcharType, ref, false, rexBuilder.constantNull());
        final RexNode withFormat = rexBuilder.makeAbstractCast(
                varcharType, ref, false, rexBuilder.makeLiteral("999"));

        assertThat(((RexCall) withoutFormat).getOperands()).hasSize(1);
        assertThat(((RexCall) withFormat).getOperands()).hasSize(2);
        assertThat(((RexCall) withFormat).getOperator()).isSameAs(SqlStdOperatorTable.CAST);
        assertThat(RexLiteral.stringValue((RexLiteral) ((RexCall) withFormat).getOperands().get(1)))
                .isEqualTo("999");
    }

    @Test
    void makeReinterpretCast_addsOverflowOperandOnlyForAlwaysTrueCheck() {
        final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 0);
        final RexNode ref = intInputRef(0);

        final RexNode withoutCheck =
                rexBuilder.makeReinterpretCast(decimalType, ref, rexBuilder.makeLiteral(false));
        final RexNode withCheck =
                rexBuilder.makeReinterpretCast(decimalType, ref, rexBuilder.makeLiteral(true));

        assertThat(withoutCheck.getKind()).isEqualTo(SqlKind.REINTERPRET);
        assertThat(((RexCall) withoutCheck).getOperands()).hasSize(1);
        assertThat(withoutCheck.getType()).isEqualTo(decimalType);
        assertThat(((RexCall) withCheck).getOperands()).hasSize(2);
    }

    @Test
    void decodeIntervalOrDecimal_reinterpretsAsBigint() {
        final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 2);
        final RexNode ref = rexBuilder.makeInputRef(decimalType, 0);

        final RexNode decoded = rexBuilder.decodeIntervalOrDecimal(ref);

        assertThat(decoded.getKind()).isEqualTo(SqlKind.REINTERPRET);
        assertThat(decoded.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
        assertThat(((RexCall) decoded).getOperands()).hasSize(1);
        assertThat(((RexCall) decoded).getOperands().get(0)).isSameAs(ref);
    }

    @Test
    void encodeIntervalOrDecimal_castsToBigintThenReinterprets() {
        final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 0);
        final RexNode ref = intInputRef(0);

        final RexNode encoded = rexBuilder.encodeIntervalOrDecimal(ref, decimalType, true);

        assertThat(encoded.getKind()).isEqualTo(SqlKind.REINTERPRET);
        assertThat(encoded.getType()).isEqualTo(decimalType);
        final List<RexNode> operands = ((RexCall) encoded).getOperands();
        assertThat(operands).hasSize(2);
        assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.CAST);
        assertThat(operands.get(0).getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
        assertThat(RexLiteral.booleanValue(operands.get(1))).isTrue();
    }

    @Test
    void multiplyDivide_skipsArithmeticWhenFactorsAreEqual() {
        final RexNode ref = intInputRef(0);

        final RexNode result = rexBuilder.multiplyDivide(ref, BigDecimal.ONE, BigDecimal.ONE);

        assertThat(result).isSameAs(ref);
    }

    @Test
    void multiplyDivide_multipliesWhenMultiplierIsGreater() {
        final RexNode result = rexBuilder.multiplyDivide(
                intInputRef(0), BigDecimal.valueOf(1000), BigDecimal.TEN);

        assertThat(result.getKind()).isEqualTo(SqlKind.MULTIPLY);
        assertThat(((RexLiteral) ((RexCall) result).getOperands().get(1))
                        .getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.valueOf(100));
    }

    @Test
    void multiplyDivide_dividesWhenDividerIsGreater() {
        final RexNode result = rexBuilder.multiplyDivide(
                intInputRef(0), BigDecimal.TEN, BigDecimal.valueOf(1000));

        assertThat(result.getKind()).isEqualTo(SqlKind.DIVIDE_INTEGER);
        assertThat(((RexLiteral) ((RexCall) result).getOperands().get(1))
                        .getValueAs(Comparable.class))
                .isEqualTo(BigDecimal.valueOf(100));
    }

    @Test
    void ensureType_returnsNodeWhenTypeAlreadyMatches() {
        final RelDataType intType = nullableSqlType(SqlTypeName.INTEGER);
        final RexNode ref = rexBuilder.makeInputRef(intType, 0);

        assertThat(rexBuilder.ensureType(intType, ref, false)).isSameAs(ref);
    }

    @Test
    void ensureType_castsWhenTypeDiffers() {
        final RexNode ref = intInputRef(0);
        final RelDataType bigintType = notNull(nullableSqlType(SqlTypeName.BIGINT));

        final RexNode ensured = rexBuilder.ensureType(bigintType, ref, false);

        assertThat(ensured.getKind()).isEqualTo(SqlKind.CAST);
        assertThat(ensured.getType()).isEqualTo(bigintType);
    }

    @Test
    void ensureType_keepsNodeForAnyTypeWhenNullabilityIsNotMatched() {
        final RelDataType anyType = TYPE_FACTORY.createSqlType(SqlTypeName.ANY);
        final RexNode ref = intInputRef(0);

        assertThat(rexBuilder.ensureType(anyType, ref, false)).isSameAs(ref);
    }

    @Test
    void ensureType_adjustsNullabilityWhenRequested() {
        final RelDataType notNullInt = notNull(nullableSqlType(SqlTypeName.INTEGER));
        final RexNode ref = rexBuilder.makeInputRef(nullableSqlType(SqlTypeName.INTEGER), 0);

        final RexNode ensured = rexBuilder.ensureType(notNullInt, ref, true);

        assertThat(ensured.getType().isNullable()).isFalse();
    }

    @Test
    void matchNullability_adoptsValueNullability() {
        final RelDataType nullableInt = nullableSqlType(SqlTypeName.INTEGER);
        final RelDataType notNullInt = notNull(nullableInt);
        final RexNode notNullValue = rexBuilder.makeInputRef(notNullInt, 0);
        final RexNode nullableValue = rexBuilder.makeInputRef(nullableInt, 0);

        assertThat(rexBuilder.matchNullability(nullableInt, notNullValue).isNullable()).isFalse();
        assertThat(rexBuilder.matchNullability(notNullInt, nullableValue).isNullable()).isTrue();
        assertThat(rexBuilder.matchNullability(notNullInt, notNullValue)).isEqualTo(notNullInt);
    }

    @Test
    void makeNullable_andMakeNotNull_wrapOnlyWhenNullabilityDiffers() {
        final RelDataType nullableInt = nullableSqlType(SqlTypeName.INTEGER);
        final RexNode nullableRef = rexBuilder.makeInputRef(nullableInt, 0);
        final RexNode notNullRef = rexBuilder.makeInputRef(notNull(nullableInt), 1);

        assertThat(rexBuilder.makeNullable(nullableRef)).isSameAs(nullableRef);
        final RexNode casted = rexBuilder.makeNotNull(nullableRef);
        assertThat(casted.getKind()).isEqualTo(SqlKind.CAST);
        assertThat(casted.getType().isNullable()).isFalse();
        assertThat(rexBuilder.makeNotNull(notNullRef)).isSameAs(notNullRef);
    }

    @Test
    void makeNullable_falseIsEquivalentToMakeNotNull() {
        final RexNode nullableRef =
                rexBuilder.makeInputRef(nullableSqlType(SqlTypeName.INTEGER), 0);

        final RexNode explicit = rexBuilder.makeNullable(nullableRef, false);

        assertThat(explicit.getKind()).isEqualTo(SqlKind.CAST);
        assertThat(explicit.getType().isNullable()).isFalse();
        assertThat(explicit).isEqualTo(rexBuilder.makeNotNull(nullableRef));
    }

    // ~ IN and BETWEEN --------------------------------------------------------

    @Test
    void makeIn_withSeveralLiteralsCreatesSearchExpression() {
        final RexNode arg = intInputRef(0);

        final RexNode in = rexBuilder.makeIn(
                arg, ImmutableList.of(intLiteral(1), intLiteral(2)));

        assertThat(in.getKind()).isEqualTo(SqlKind.SEARCH);
        final List<RexNode> operands = ((RexCall) in).getOperands();
        assertThat(operands).hasSize(2);
        assertThat(operands.get(0)).isSameAs(arg);
        final RexLiteral sargLiteral = (RexLiteral) operands.get(1);
        assertThat(sargLiteral.getTypeName()).isEqualTo(SqlTypeName.SARG);
        assertThat(((Sarg<?>) sargLiteral.getValue()).pointCount).isEqualTo(2);
    }

    @Test
    void makeIn_withSingleLiteralCreatesEquality() {
        final RexNode in = rexBuilder.makeIn(intInputRef(0), ImmutableList.of(intLiteral(7)));

        assertThat(in.getKind()).isEqualTo(SqlKind.EQUALS);
        assertThat(((RexCall) in).getOperands()).hasSize(2);
    }

    @Test
    void makeIn_withoutLiteralsCreatesDisjunctionOfEqualities() {
        final RexNode arg = intInputRef(0);

        final RexNode in = rexBuilder.makeIn(arg, ImmutableList.of(intInputRef(1), intInputRef(2)));

        assertThat(in.getKind()).isEqualTo(SqlKind.OR);
        final List<RexNode> operands = ((RexCall) in).getOperands();
        assertThat(operands).hasSize(2);
        assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.EQUALS);
        assertThat(operands.get(1).getKind()).isEqualTo(SqlKind.EQUALS);
    }

    @Test
    void makeIn_withEmptyListIsAlwaysFalse() {
        final RexNode in = rexBuilder.makeIn(intInputRef(0), ImmutableList.of());

        assertThat(in.getKind()).isEqualTo(SqlKind.LITERAL);
        assertThat(((RexLiteral) in).isAlwaysFalse()).isTrue();
    }

    @Test
    void makeIn_withIncompatibleTypesKeepsEqualityDisjunction() {
        final RexNode in = rexBuilder.makeIn(
                intInputRef(0),
                ImmutableList.of(rexBuilder.makeLiteral("a"), rexBuilder.makeLiteral("b")));

        assertThat(in.getKind()).isEqualTo(SqlKind.OR);
        assertThat(((RexCall) in).getOperands()).hasSize(2);
    }

    @Test
    void makeBetween_withLiteralsCreatesSearchExpression() {
        final RexNode arg = intInputRef(0);

        final RexNode between = rexBuilder.makeBetween(arg, intLiteral(1), intLiteral(10));

        assertThat(between.getKind()).isEqualTo(SqlKind.SEARCH);
        final RexLiteral sargLiteral = (RexLiteral) ((RexCall) between).getOperands().get(1);
        final Sarg<?> sarg = (Sarg<?>) sargLiteral.getValue();
        assertThat(sarg.rangeSet.contains(new BigDecimal(5))).isTrue();
        assertThat(sarg.rangeSet.contains(new BigDecimal(11))).isFalse();
    }

    @Test
    void makeBetween_withoutLiteralsCreatesConjunctionOfComparisons() {
        final RexNode between =
                rexBuilder.makeBetween(intInputRef(0), intInputRef(1), intInputRef(2));

        assertThat(between.getKind()).isEqualTo(SqlKind.AND);
        final List<RexNode> operands = ((RexCall) between).getOperands();
        assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.GREATER_THAN_OR_EQUAL);
        assertThat(operands.get(1).getKind()).isEqualTo(SqlKind.LESS_THAN_OR_EQUAL);
    }
EOF
