                        ImmutableList.of(1),
                        -1,
                        bigintType,
                        "c2");

        final RexNode first =
                rexBuilder.addAggCall(twoArgs, 0, aggCalls, aggCallMapping, i -> i == 1);
        final RexNode second =
                rexBuilder.addAggCall(oneArg, 0, aggCalls, aggCallMapping, i -> i == 1);

        assertThat(aggCalls).hasSize(1);
        assertThat(second).isSameAs(first);
    }

    @Test
    void addAggCall_keepsArgumentsOfDistinctCount() {
        final RelDataType bigintType = nullableSqlType(SqlTypeName.BIGINT);
        final AggregateCall distinctCount =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        true,
                        ImmutableList.of(0, 1),
                        -1,
                        bigintType,
                        "c");
        final List<AggregateCall> aggCalls = new ArrayList<>();

        rexBuilder.addAggCall(
                distinctCount, 0, aggCalls, new HashMap<>(), i -> i == 1);

        assertThat(aggCalls.get(0).getArgList()).containsExactly(0, 1);
    }

    @Test
    void addAggCall_keepsArgumentsOfNonCountAggregations() {
        final RelDataType bigintType = nullableSqlType(SqlTypeName.BIGINT);
        final AggregateCall sum = AggregateCall.create(
                SqlStdOperatorTable.SUM, false, ImmutableList.of(0, 1), -1, bigintType, "s");
        final List<AggregateCall> aggCalls = new ArrayList<>();

        rexBuilder.addAggCall(sum, 0, aggCalls, new HashMap<>(), i -> false);

        assertThat(aggCalls.get(0).getArgList()).containsExactly(0, 1);
    }

    @Test
    void addAggCall_withArgumentTypesUsesTheirNullability() {
        final RelDataType bigintType = nullableSqlType(SqlTypeName.BIGINT);
        final RelDataType notNullInt = nullableSqlType(SqlTypeName.INTEGER);
        final AggregateCall count =
                AggregateCall.create(
