    assertThat(belowOne.getType().getScale()).isEqualTo(3);
}

@Test
void makeExactLiteral_withNullValueProducesNullLiteral() {
    final RelDataType decimalType = TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 2);

    final RexLiteral literal = rexBuilder.makeExactLiteral(null, decimalType);

    assertThat(literal.isNull()).isTrue();
    assertThat(literal.getType().isNullable()).isTrue();
}

@Test
void makeBigintLiteral_alwaysUsesBigintType() {
    final RexLiteral literal = rexBuilder.makeBigintLiteral(BigDecimal.valueOf(3));

    assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.BIGINT);
    assertThat(literal.getValueAs(Comparable.class)).isEqualTo(new BigDecimal(3));
    assertThat(rexBuilder.makeBigintLiteral(null).isNull()).isTrue();
}

@Test
void makeApproxLiteral_usesDoubleTypeAndValue() {
    final RexLiteral literal = rexBuilder.makeApproxLiteral(new BigDecimal("1.5"));

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.DOUBLE);
    assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.DOUBLE);
    assertThat(literal.getValueAs(Double.class)).isEqualTo(1.5);
}

@Test
void makeApproxLiteral_underflowingValueBecomesZero() {
    final RexLiteral literal = rexBuilder.makeApproxLiteral(new BigDecimal("1E-400"));

    assertThat(literal.getValueAs(Double.class)).isEqualTo(0.0);
}

@Test
void makeApproxLiteral_fromDoubleKeepsValue() {
    final RelDataType realType = TYPE_FACTORY.createSqlType(SqlTypeName.REAL);

    final RexLiteral literal = rexBuilder.makeApproxLiteral(2.75, realType);

    assertThat(literal.getValueAs(Double.class)).isEqualTo(2.75);
    assertThat(literal.getType()).isEqualTo(realType);
}

@Test
void makeBinaryLiteral_usesLengthAsPrecision() {
    final ByteString bytes = new ByteString(new byte[] {1, 2, 3});

    final RexLiteral literal = rexBuilder.makeBinaryLiteral(bytes);

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.BINARY);
    assertThat(literal.getType().getPrecision()).isEqualTo(3);
    assertThat(literal.getValue()).isEqualTo(bytes);
}

@Test
void makeCharLiteral_populatesCharsetAndCollation() {
    final RexLiteral literal = rexBuilder.makeCharLiteral(new NlsString("abc", null, null));

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.CHAR);
    assertThat(literal.getType().getPrecision()).isEqualTo(3);
    assertThat(literal.getType().getCharset()).isNotNull();
    assertThat(literal.getType().getCollation()).isNotNull();
    assertThat(RexLiteral.stringValue(literal)).isEqualTo("abc");
}

@Test
void makeFlag_producesSymbolLiteral() {
    final RexLiteral literal = rexBuilder.makeFlag(TimeUnitRange.YEAR_TO_MONTH);

    assertThat(literal.getType().getSqlTypeName()).isEqualTo(SqlTypeName.SYMBOL);
    assertThat(literal.getValue()).isEqualTo(TimeUnitRange.YEAR_TO_MONTH);
}

@Test
void makeFlag_rejectsNullFlag() {
    assertThatThrownBy(() -> rexBuilder.makeFlag(null))
            .isInstanceOf(NullPointerException.class)
            .hasMessageContaining("flag");
}

@Test
void makeDateLiteral_keepsValueAndDateType() {
    final RexLiteral literal = rexBuilder.makeDateLiteral(new DateString("2020-02-29"));

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.DATE);
    assertThat(literal.getValueAs(Comparable.class).toString()).isEqualTo("2020-02-29");
    assertThat(literal.isNull()).isFalse();
}

@Test
void makeTimeLiteral_appliesPrecisionAndRounds() {
    final RexLiteral millis = rexBuilder.makeTimeLiteral(new TimeString("12:34:56.789"), 3);
    final RexLiteral seconds = rexBuilder.makeTimeLiteral(new TimeString("12:34:56.789"), 0);

    assertThat(millis.getTypeName()).isEqualTo(SqlTypeName.TIME);
    assertThat(millis.getType().getPrecision()).isEqualTo(3);
    assertThat(millis.getValueAs(Comparable.class).toString()).isEqualTo("12:34:56.789");
    assertThat(seconds.getType().getPrecision()).isEqualTo(0);
    assertThat(seconds.getValueAs(Comparable.class).toString()).isEqualTo("12:34:56");
}

@Test
void makeTimeWithLocalTimeZoneLiteral_usesLocalTimeZoneType() {
    final RexLiteral literal =
            rexBuilder.makeTimeWithLocalTimeZoneLiteral(new TimeString("01:02:03"), 1);

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIME_WITH_LOCAL_TIME_ZONE);
    assertThat(literal.getType().getPrecision()).isEqualTo(1);
    assertThat(literal.getValueAs(Comparable.class).toString()).isEqualTo("01:02:03");
}

@Test
void makeTimeTzLiteral_usesTimeTzType() {
    final TimeWithTimeZoneString time =
            new TimeWithTimeZoneString(
                    new TimeString("01:02:03.4"), TimeZone.getTimeZone("GMT+02:00"));

    final RexLiteral literal = rexBuilder.makeTimeTzLiteral(time, 1);

    assertThat(literal.getTypeName()).isEqualTo(SqlTypeName.TIME_TZ);

    final RexNode in = rexBuilder.makeIn(arg, ImmutableList.of(intInputRef(1), intInputRef(2)));

    assertThat(in.getKind()).isEqualTo(SqlKind.OR);
    final List<RexNode> operands = ((RexCall) in).getOperands();
    assertThat(operands).hasSize(2);
    assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.EQUALS);
    assertThat(operands.get(1).getKind()).isEqualTo(SqlKind.EQUALS);
}

@Test
void makeIn_withEmptyListIsAlwaysFalse() {
    final RexNode in = rexBuilder.makeIn(intInputRef(0), ImmutableList.of());

    assertThat(in.getKind()).isEqualTo(SqlKind.LITERAL);
    assertThat(((RexLiteral) in).isAlwaysFalse()).isTrue();
}

@Test
void makeIn_withIncompatibleTypesKeepsEqualityDisjunction() {
    final RexNode in =
            rexBuilder.makeIn(
                    intInputRef(0),
                    ImmutableList.of(rexBuilder.makeLiteral("a"), rexBuilder.makeLiteral("b")));

    assertThat(in.getKind()).isEqualTo(SqlKind.OR);
    assertThat(((RexCall) in).getOperands()).hasSize(2);
}

@Test
void makeBetween_withLiteralsCreatesSearchExpression() {
    final RexNode arg = intInputRef(0);

    final RexNode between = rexBuilder.makeBetween(arg, intLiteral(1), intLiteral(10));

    assertThat(between.getKind()).isEqualTo(SqlKind.SEARCH);
    final RexLiteral sargLiteral = (RexLiteral) ((RexCall) between).getOperands().get(1);
    @SuppressWarnings("unchecked")
    final Sarg<BigDecimal> sarg = (Sarg<BigDecimal>) sargLiteral.getValue();
    assertThat(sarg.rangeSet.contains(new BigDecimal(5))).isTrue();
    assertThat(sarg.rangeSet.contains(new BigDecimal(11))).isFalse();
}

@Test
void makeBetween_withoutLiteralsCreatesConjunctionOfComparisons() {
    final RexNode between =
            rexBuilder.makeBetween(intInputRef(0), intInputRef(1), intInputRef(2));

    assertThat(between.getKind()).isEqualTo(SqlKind.AND);
    final List<RexNode> operands = ((RexCall) between).getOperands();
    assertThat(operands.get(0).getKind()).isEqualTo(SqlKind.GREATER_THAN_OR_EQUAL);
    assertThat(operands.get(1).getKind()).isEqualTo(SqlKind.LESS_THAN_OR_EQUAL);
}

// ~ windowing -------------------------------------------------------------

@Test
void makeWindow_rangeWithoutOrderKeysBecomesUnbounded() {
    final RexWindow window =
            rexBuilder.makeWindow(
                    ImmutableList.of(intInputRef(0)),
                    ImmutableList.of(),
                    RexWindowBounds.CURRENT_ROW,
                    RexWindowBounds.CURRENT_ROW,
                    false);

    assertThat(window.partitionKeys).hasSize(1);
    assertThat(window.getLowerBound()).isSameAs(RexWindowBounds.UNBOUNDED_PRECEDING);
    assertThat(window.getUpperBound()).isSameAs(RexWindowBounds.UNBOUNDED_FOLLOWING);
    assertThat(window.isRows()).isFalse();
    assertThat(window.getExclude()).isEqualTo(RexWindowExclusion.EXCLUDE_NO_OTHER);
}

@Test
void makeWindow_prefersRangeForUnboundedUnboundedFrame() {
    final RexWindow window =
            rexBuilder.makeWindow(
                    ImmutableList.of(),
                    ImmutableList.of(),
                    RexWindowBounds.UNBOUNDED_PRECEDING,
                    RexWindowBounds.UNBOUNDED_FOLLOWING,
                    true);

    assertThat(window.isRows()).isFalse();
    assertThat(window.getLowerBound()).isSameAs(RexWindowBounds.UNBOUNDED_PRECEDING);
    assertThat(window.getUpperBound()).isSameAs(RexWindowBounds.UNBOUNDED_FOLLOWING);
}

@Test
void makeWindow_keepsRowFrameAndExclusion() {
    final RexWindow window =
            rexBuilder.makeWindow(
                    ImmutableList.of(intInputRef(0)),
                    ImmutableList.of(new RexFieldCollation(intInputRef(1), ImmutableSet.of())),
                    RexWindowBounds.preceding(intLiteral(1)),
                    RexWindowBounds.following(intLiteral(1)),
                    true,
                    RexWindowExclusion.EXCLUDE_CURRENT_ROW);

    assertThat(window.isRows()).isTrue();
    assertThat(window.orderKeys).hasSize(1);
    assertThat(window.getLowerBound().isPreceding()).isTrue();
    assertThat(window.getUpperBound().isFollowing()).isTrue();
    assertThat(window.getExclude()).isEqualTo(RexWindowExclusion.EXCLUDE_CURRENT_ROW);
}

@Test
void makeOver_buildsWindowedAggregate() {
    final RelDataType bigintType = sqlType(SqlTypeName.BIGINT);

    final RexNode over =
            rexBuilder.makeOver(
                    bigintType,
                    SqlStdOperatorTable.COUNT,
                    ImmutableList.of(intInputRef(0)),
                    ImmutableList.of(intInputRef(1)),
                    ImmutableList.of(new RexFieldCollation(intInputRef(2), ImmutableSet.of())),
                    RexWindowBounds.UNBOUNDED_PRECEDING,
                    RexWindowBounds.CURRENT_ROW,
                    true,
                    true,
                    false,
                    true,
                    false);

    assertThat(over).isInstanceOf(RexOver.class);
    final RexOver rexOver = (RexOver) over;
    assertThat(rexOver.getAggOperator()).isSameAs(SqlStdOperatorTable.COUNT);
    assertThat(rexOver.getWindow().isRows()).isTrue();
    assertThat(rexOver.getWindow().partitionKeys).hasSize(1);
    assertThat(rexOver.getWindow().orderKeys).hasSize(1);
    assertThat(rexOver.isDistinct()).isTrue();
    assertThat(rexOver.ignoreNulls()).isFalse();
    assertThat(rexOver.getType()).isEqualTo(bigintType);
}

@Test
void makeOver_nullWhenCountZeroWrapsResultInCase() {
    final RexNode over =
            rexBuilder.makeOver(
                    sqlType(SqlTypeName.BIGINT),
                    SqlStdOperatorTable.COUNT,
                    ImmutableList.of(),
                    ImmutableList.of(),
                    ImmutableList.of(),
                    RexWindowBounds.UNBOUNDED_PRECEDING,
                    RexWindowBounds.CURRENT_ROW,
                    true,
                    true,
                    true,
                    false,
                    false);

