        }

        @Override
        public RelNode visit(RelNode other) {
            if (other instanceof Join) {
                Join join = (Join) other;
                try {
                    stack.push(join);
                    join.getCondition().accept(rexVisitor(join));
                } finally {
                    stack.pop();
