 static void run(JoinRelType jt){RelBuilder b=b(); Holder<RexCorrelVariable> v=Holder.of(null); b.values(new String[]{"k","v"},1,10).as("left"); RexNode key=b.field(0); b.variable(v); b.values(new String[]{"rk","rv"},1,100).as("right"); b.filter(b.equals(b.field(0),b.field(v.get(),0))); b.correlate(jt,v.get().id,key); RelNode root=b.build(); System.out.println("IN\n"+RelOptUtil.toString(root)+"\nreq="+((Correlate)root).getRequiredColumns()); RelNode out=RelDecorrelator.decorrelateQuery(root,b); System.out.println("OUT\n"+RelOptUtil.toString(out)+"\nschema="+out.getRowType());}
 static void agg(){RelBuilder b=b(); Holder<RexCorrelVariable> v=Holder.of(null); b.values(new String[]{"k","v"},1,10).as("left"); RexNode key=b.field(0); b.variable(v); b.values(new String[]{"rk","rv"},1,100).as("right"); b.filter(b.equals(b.field(0),b.field(v.get(),0))); b.aggregate(b.groupKey(),b.count(b.field(1))); b.correlate(JoinRelType.INNER,v.get().id,key); RelNode root=b.build(); System.out.println("AGG IN\n"+RelOptUtil.toString(root)+"\nreq="+((Correlate)root).getRequiredColumns()); RelNode out=RelDecorrelator.decorrelateQuery(root,b); System.out.println("AGG OUT\n"+RelOptUtil.toString(out)+"\nschema="+out.getRowType());}
