import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link RelDecorrelator}. */
class RelDecorrelatorTests {

    @Test
    void corelMapBuilderBuildsEmptyMapForUncorrelatedRel() {
        RelBuilder builder = newBuilder();
        RelNode root =
                builder.values(new String[] {"id", "amount"}, 1, 10)
                        .project(builder.field(0))
                        .build();

        RelDecorrelator.CorelMap corelMap = new RelDecorrelator.CorelMapBuilder().build(root);

        assertThat(corelMap.hasCorrelation()).isFalse();
        assertThat(corelMap.getMapCorToCorRel()).isEmpty();
        assertThat(new RelDecorrelator.CorelMapBuilder().build().hasCorrelation()).isFalse();
    }

    @Test
    void corelMapBuilderFindsCorrelationAndRebuildIsStable() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.INNER);

        RelDecorrelator.CorelMap firstMap = new RelDecorrelator.CorelMapBuilder().build(query.root);
        RelDecorrelator.CorelMap secondMap =
                new RelDecorrelator.CorelMapBuilder().build(query.root);

        assertThat(firstMap.hasCorrelation()).isTrue();
        assertThat(firstMap.getMapCorToCorRel())
                .containsOnlyKeys(query.corVar.id)
                .containsEntry(query.corVar.id, query.root);
        assertThat(firstMap.getMapCorToCorRel().get(query.corVar.id)).isInstanceOf(Correlate.class);
        assertThat(firstMap).isEqualTo(secondMap).hasSameHashCodeAs(secondMap);
    }

    @Test
    void corelMapOfKeepsProvidedCorrelationMap() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.INNER);
        NavigableMap<CorrelationId, RelNode> correlationMap = new TreeMap<>();
        correlationMap.put(query.corVar.id, query.root);

        RelDecorrelator.CorelMap corelMap =
                RelDecorrelator.CorelMap.of(
                        com.google.common.collect.MultimapBuilder.SortedSetMultimapBuilder
                                .<RelNode, RelDecorrelator.CorRef>hashKeys()
                                .treeSetValues()
                                .build(),
                        correlationMap,
                        Collections.emptyMap());

        assertThat(corelMap.hasCorrelation()).isTrue();
        assertThat(corelMap.getMapCorToCorRel()).isSameAs(correlationMap);
        assertThat(corelMap.getMapCorToCorRel()).containsEntry(query.corVar.id, query.root);
    }

    @Test
    void decorrelateQueryReturnsOriginalPlanWhenNoCorrelation() {
        RelBuilder builder = newBuilder();
        RelNode root =
                builder.values(new String[] {"id", "amount"}, 1, 10)
                        .filter(builder.greaterThan(builder.field(1), builder.literal(0)))
                        .build();

        RelNode result = RelDecorrelator.decorrelateQuery(root, newBuilderFor(root));

        assertThat(result).isSameAs(root);
    }

    @Test
    void decorrelateQuerySkipsRulePreprocessingWhenNoCorrelation() {
        RelNode root = unrelatedSingleValueAggregate();

        RelNode result =
                RelDecorrelator.decorrelateQuery(
                        root,
                        newBuilderFor(root),
                        RuleSets.ofList(
                                RelDecorrelator.RemoveSingleAggregateRule.DEFAULT.toRule()));

        assertThat(result).isSameAs(root);
        assertThat(preOrder(result))
                .anyMatch(
                        rel ->
                                rel instanceof Aggregate
                                        && containsSingleValueAggregate((Aggregate) rel));
    }

    @Test
    void decorrelateQueryRewritesInnerCorrelationToJoin() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.INNER);

        RelNode result = RelDecorrelator.decorrelateQuery(query.root, newBuilderFor(query.root));

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(preOrder(result)).noneMatch(Filter.class::isInstance);
        assertThat(result).isInstanceOf(Join.class);
        Join join = (Join) result;
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.INNER);
        assertThat(join.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);
        assertThat(((RexCall) join.getCondition()).getOperands())
                .extracting(operand -> ((RexInputRef) operand).getIndex())
                .containsExactly(0, 2);
        assertThat(result.getRowType().getFieldNames()).containsExactly("k", "v", "rk", "rv");
    }

    @Test
    void decorrelateQueryPreservesLeftJoinType() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.LEFT);

        RelNode result = RelDecorrelator.decorrelateQuery(query.root, newBuilderFor(query.root));

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(result).isInstanceOf(Join.class);
        Join join = (Join) result;
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.LEFT);
        assertThat(join.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);
        assertThat(join.getLeft()).isInstanceOf(org.apache.calcite.rel.logical.LogicalValues.class);
        assertThat(join.getRight())
                .isInstanceOf(org.apache.calcite.rel.logical.LogicalValues.class);
        assertThat(result.getRowType().getFieldCount()).isEqualTo(4);
        assertThat(result.getRowType().getFieldNames()).containsExactly("k", "v", "rk", "rv");
    }

    @Test
    void decorrelateQueryHandlesCorrelatedCountAggregate() {
        CorrelatedQuery query = correlatedCountAggregate(JoinRelType.INNER);

        RelNode result = RelDecorrelator.decorrelateQuery(query.root, newBuilderFor(query.root));

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(result).isInstanceOf(Project.class);
        assertThat(result.getRowType().getFieldCount()).isEqualTo(3);
        assertThat(result.getRowType().getFieldList().get(2).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.BIGINT);
        assertThat(preOrder(result))
                .anyMatch(
                        rel ->
                                rel instanceof Join
                                        && ((Join) rel).getJoinType() == JoinRelType.INNER);
        assertThat(preOrder(result))
                .anyMatch(
                        rel ->
                                rel instanceof Join
                                        && ((Join) rel).getJoinType() == JoinRelType.LEFT);
    }

    @Test
    void decorrelateQueryHonorsEmptyCustomRuleSet() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.INNER);

        RelNode result =
                RelDecorrelator.decorrelateQuery(
                        query.root, newBuilderFor(query.root), RuleSets.ofList());

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(result).isInstanceOf(Join.class);
        assertThat(((Join) result).getJoinType()).isEqualTo(JoinRelType.INNER);
    }

    @Test
    @SuppressWarnings("deprecation")
    void decorrelateQueryUsesDeprecatedSingleArgumentOverload() {
        CorrelatedQuery query = correlatedFilter(JoinRelType.INNER);

        RelNode result = RelDecorrelator.decorrelateQuery(query.root);

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(result).isInstanceOf(Join.class);
        assertThat(result.getRowType().getFieldNames()).containsExactly("k", "v", "rk", "rv");
    }

    @Test
    void removeCorrelationViaRuleUsesDefaultRulesForScalarProject() {
        RelNode root = correlatedScalarProject();
        RelDecorrelator decorrelator = newDecorrelator(root);

        RelNode result = decorrelator.removeCorrelationViaRule(root);

        assertThat(preOrder(result)).noneMatch(Correlate.class::isInstance);
        assertThat(new RelDecorrelator.CorelMapBuilder().build(result).hasCorrelation()).isFalse();
        assertThat(result).isInstanceOf(Project.class);
        Join join = (Join) result.getInput(0);
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.LEFT);
        assertThat(join.getCondition().isAlwaysTrue()).isTrue();
        assertThat(result.getRowType().getFieldCount()).isEqualTo(3);
    }

    @Test
    void removeCorrelationViaRuleUsesProvidedRuleSet() {
        RelNode root = unrelatedSingleValueAggregate();
        RelDecorrelator decorrelator = newDecorrelator(root);

        RelNode result =
                decorrelator.removeCorrelationViaRule(
                        root,
                        RuleSets.ofList(
                                RelDecorrelator.RemoveSingleAggregateRule.DEFAULT.toRule()));

        assertThat(result).isNotSameAs(root);
        assertThat(preOrder(result))
                .noneMatch(
                        rel ->
                                rel instanceof Aggregate
                                        && containsSingleValueAggregate((Aggregate) rel));
        assertThat(preOrder(result).stream().filter(Aggregate.class::isInstance).count())
                .isEqualTo(1);
        assertThat(result).isInstanceOf(Project.class);
        assertThat(result.getRowType().getFieldCount()).isEqualTo(1);
    }

    private static boolean containsSingleValueAggregate(Aggregate aggregate) {
        return aggregate.getAggCallList().stream()
                .anyMatch(call -> call.getAggregation() instanceof SqlSingleValueAggFunction);
    }

    private static List<RelNode> preOrder(RelNode root) {
        List<RelNode> rels = new ArrayList<>();
        collect(root, rels);
        return rels;
    }

    private static void collect(RelNode rel, List<RelNode> rels) {
        rels.add(rel);
        for (RelNode input : rel.getInputs()) {
            collect(input, rels);
        }
    }

    private static RelDecorrelator newDecorrelator(RelNode root) {
        return new RelDecorrelator(
                new RelDecorrelator.CorelMapBuilder().build(root),
                root.getCluster().getPlanner().getContext(),
                newBuilderFor(root));
    }

    private static RelNode unrelatedSingleValueAggregate() {
        RelBuilder builder = newBuilder();
        builder.values(new String[] {"v"}, 1);
        builder.aggregate(builder.groupKey(), builder.count());
        builder.project(
                builder.call(SqlStdOperatorTable.PLUS, builder.field(0), builder.literal(1)));
        builder.aggregate(
                builder.groupKey(),
                builder.aggregateCall(SqlStdOperatorTable.SINGLE_VALUE, builder.field(0)));
        return builder.build();
    }

    private static RelNode correlatedScalarProject() {
        RelBuilder builder = newBuilder();
        Holder<RexCorrelVariable> corVar = Holder.of(null);
        builder.values(new String[] {"k", "v"}, 1, 10).as("left");
        RexNode correlationKey = builder.field(0);
        builder.variable(corVar);
        builder.values(new String[] {"rk"}, 1).as("right");
        builder.project(builder.field(corVar.get(), 0));
        builder.aggregate(
                builder.groupKey(),
                builder.aggregateCall(SqlStdOperatorTable.SINGLE_VALUE, builder.field(0)));
        builder.correlate(JoinRelType.LEFT, corVar.get().id, correlationKey);
        return builder.build();
    }

    private static CorrelatedQuery correlatedFilter(JoinRelType joinType) {
        RelBuilder builder = newBuilder();
        Holder<RexCorrelVariable> corVar = Holder.of(null);
        builder.values(new String[] {"k", "v"}, 1, 10).as("left");
        RexNode correlationKey = builder.field(0);
        builder.variable(corVar);
        builder.values(new String[] {"rk", "rv"}, 1, 100).as("right");
        builder.filter(builder.equals(builder.field(0), builder.field(corVar.get(), 0)));
        builder.correlate(joinType, corVar.get().id, correlationKey);
        RelNode root = builder.build();
        assertThat(root).isInstanceOf(Correlate.class);
        return new CorrelatedQuery(corVar.get(), root);
    }

    private static CorrelatedQuery correlatedCountAggregate(JoinRelType joinType) {
        RelBuilder builder = newBuilder();
        Holder<RexCorrelVariable> corVar = Holder.of(null);
        builder.values(new String[] {"k", "v"}, 1, 10).as("left");
        RexNode correlationKey = builder.field(0);
        builder.variable(corVar);
        builder.values(new String[] {"rk", "rv"}, 1, 100).as("right");
        builder.filter(builder.equals(builder.field(0), builder.field(corVar.get(), 0)));
        builder.aggregate(builder.groupKey(), builder.count(builder.field(1)));
        builder.correlate(joinType, corVar.get().id, correlationKey);
        RelNode root = builder.build();
        assertThat(root).isInstanceOf(Correlate.class);
        return new CorrelatedQuery(corVar.get(), root);
    }

    private static RelBuilder newBuilder() {
        SqlTypeFactoryImpl typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        RelOptCluster cluster =
                RelOptCluster.create(
                        new HepPlanner(new HepProgramBuilder().build()),
                        new RexBuilder(typeFactory));
        return RelFactories.LOGICAL_BUILDER.create(cluster, null);
    }

    private static RelBuilder newBuilderFor(RelNode root) {
        return RelFactories.LOGICAL_BUILDER.create(root.getCluster(), null);
    }

    private static final class CorrelatedQuery {
        private final RexCorrelVariable corVar;
        private final RelNode root;

        private CorrelatedQuery(RexCorrelVariable corVar, RelNode root) {
            this.corVar = corVar;
            this.root = root;
        }
    }
}

