                newCall =
                        AggregateCall.create(
                                new SqlSumEmptyIsZeroAggFunction(),
                                false,
                                aggCall.isApproximate(),
                                false,
                                newArgs,
                                -1,
                                aggCall.distinctKeys,
                                RelCollations.EMPTY,
                                originalGroupSet.cardinality(),
                                relBuilder.peek(),
                                aggCall.getType(),
                                aggCall.getName());
            } else {
                newCall =
                        AggregateCall.create(
                                aggCall.getAggregation(),
                                false,
                                aggCall.isApproximate(),
                                false,
                                newArgs,
                                -1,
                                aggCall.distinctKeys,
                                RelCollations.EMPTY,
                                originalGroupSet.cardinality(),
                                relBuilder.peek(),
                                aggCall.getType(),
                                aggCall.name);
