import org.apache.calcite.jdbc.JavaTypeFactoryImpl;
import org.apache.calcite.plan.RelOptCluster;
import org.apache.calcite.plan.RelOptUtil;
import org.apache.calcite.plan.hep.HepPlanner;
import org.apache.calcite.plan.hep.HepProgramBuilder;
import org.apache.calcite.rel.RelNode;
import org.apache.calcite.rel.core.AggregateCall;
import org.apache.calcite.rel.logical.LogicalAggregate;
import org.apache.calcite.rel.logical.LogicalValues;
import org.apache.calcite.rel.type.RelDataType;
import org.apache.calcite.rel.type.RelDataTypeFactory;
import org.apache.calcite.rex.RexBuilder;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.type.SqlTypeName;
import org.apache.calcite.util.ImmutableBitSet;
import org.apache.calcite.util.Util;
import org.apache.flink.table.planner.plan.rules.logical.FlinkAggregateExpandDistinctAggregatesRule;

import com.google.common.collect.ImmutableList;
import java.util.Arrays;

public class S2 {
    static RelDataTypeFactory tf;
    static RelNode input;

    public static void main(String[] args) {
        JavaTypeFactoryImpl typeFactory = new JavaTypeFactoryImpl();
        tf = typeFactory;
        RelOptCluster cluster = RelOptCluster.create(new HepPlanner(new HepProgramBuilder().build()), new RexBuilder(typeFactory));
        RelDataType rowType = typeFactory.builder()
                .add("a", SqlTypeName.INTEGER)
                .add("b", SqlTypeName.INTEGER)
                .add("c", SqlTypeName.DOUBLE)
                .add("d", SqlTypeName.INTEGER)
                .build();
        input = LogicalValues.createEmpty(cluster, rowType);

        // A: monopole
        AggregateCall cdB = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(1), -1, SqlTypeName.BIGINT, "cd_b");
        AggregateCall sdB = call(SqlStdOperatorTable.SUM, true, false, Arrays.asList(1), -1, SqlTypeName.INTEGER, "sd_b");
        show("A monopole INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, cdB, sdB));
        show("A monopole JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN,
                agg(ImmutableBitSet.of(0), null, cdB, sdB));

        // B: singleton distinct + non-distinct
        AggregateCall star = call(SqlStdOperatorTable.COUNT, false, false, ImmutableList.of(), -1, SqlTypeName.BIGINT, "cnt");
        AggregateCall sumC = call(SqlStdOperatorTable.SUM, false, false, Arrays.asList(2), -1, SqlTypeName.DOUBLE, "sum_c");
        show("B singleton JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN,
                agg(ImmutableBitSet.of(0), null, star, sumC, cdB));
        show("B singleton INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, star, sumC, cdB));

        // E: filter
        AggregateCall cdBFilter = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(1), 3, SqlTypeName.BIGINT, "cd_b_f");
        AggregateCall cdCFilter = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(2), 3, SqlTypeName.BIGINT, "cd_c_f");
        show("E filter JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN,
                agg(ImmutableBitSet.of(0), null, cdBFilter, cdCFilter));
        show("E filter INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, cdBFilter, cdCFilter));

        // F: approximate + accurate
        AggregateCall approx = call(SqlStdOperatorTable.COUNT, true, true, Arrays.asList(1), -1, SqlTypeName.BIGINT, "approx");
        show("F mixed", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, approx, cdB));

        // G: no distinct
        show("G no distinct", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, star, sumC));

        // H: grouping sets
        RelNode aggGS = LogicalAggregate.create(input, ImmutableBitSet.of(0),
                ImmutableList.of(ImmutableBitSet.of(0), ImmutableBitSet.of(0, 1)), ImmutableList.of(cdB));
        show("H grouping sets", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggGS);

        // I: global aggregate with INSTANCE
        show("I global INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(), null, cdB, sumC));
        show("I global JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN,
                agg(ImmutableBitSet.of(), null, cdB, sumC));

        // J: MIN (distinct ignored) with COUNT DISTINCT
        AggregateCall minB = call(SqlStdOperatorTable.MIN, false, false, Arrays.asList(1), -1, SqlTypeName.INTEGER, "min_b");
        show("J min promo INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                agg(ImmutableBitSet.of(0), null, cdB, minB));
        show("J min promo JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN,
                agg(ImmutableBitSet.of(0), null, cdB, minB));
    }

    static void show(String label, FlinkAggregateExpandDistinctAggregatesRule rule, RelNode rel) {
        HepProgramBuilder b = new HepProgramBuilder();
        b.addRuleInstance(rule);
        HepPlanner p = new HepPlanner(b.build());
        p.setRoot(rel);
        RelNode out;
        try {
            out = p.findBestExp();
        } catch (Throwable t) {
            System.out.println("### " + label + " -> THROWN " + t.getClass().getName() + ": " + t.getMessage());
            return;
        }
        System.out.println("### " + label + " changed=" + (out != rel) + "\n" + Util.toLinux(RelOptUtil.toString(out)));
    }

    static AggregateCall call(org.apache.calcite.sql.SqlAggFunction f, boolean d, boolean approx,
                              java.util.List<Integer> args, int filter, SqlTypeName type, String name) {
        return AggregateCall.create(f, d, approx, args, filter, tf.createSqlType(type), name);
    }

    static RelNode agg(ImmutableBitSet groupSet, java.util.List<ImmutableBitSet> groupSets, AggregateCall... calls) {
        return LogicalAggregate.create(input, groupSet, groupSets, Arrays.asList(calls));
    }
}
