        RelNode aggGS = LogicalAggregate.create(input, ImmutableBitSet.of(0),
                ImmutableList.sortedCopyOf(ImmutableBitSet.ORDERING, ImmutableList.of(ImmutableBitSet.of(0), ImmutableBitSet.of(0, 1))), ImmutableList.of(cdB));
        show("H grouping sets INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggGS);
        show("H grouping sets JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggGS);

        // I: global aggregate
        show("I global INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg(ImmutableBitSet.of(), null, cdB, sumC));
        show("I global JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg(ImmutableBitSet.of(), null, cdB, sumC));

        // J: MIN promo
        AggregateCall minB = call(SqlStdOperatorTable.MIN, false, false, Arrays.asList(1), -1, SqlTypeName.INTEGER, "min_b");
        show("J min promo INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg(ImmutableBitSet.of(0), null, cdB, minB));

        // K: mono with filter
        AggregateCall cdBFilter = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(1), 3, SqlTypeName.BIGINT, "cd_b_f");
        show("K mono filter JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg(ImmutableBitSet.of(0), null, cdBFilter));
        show("K mono filter INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg(ImmutableBitSet.of(0), null, cdBFilter));

        // L: approximate only
        AggregateCall approx = call(SqlStdOperatorTable.COUNT, true, true, Arrays.asList(1), -1, SqlTypeName.BIGINT, "approx");
        show("L approximate only", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg(ImmutableBitSet.of(0), null, approx, sumC));

        // M: unsupported non distinct agg (e.g. AVG) plus 2 distinct arg lists -> join path
        AggregateCall avgC = call(SqlStdOperatorTable.AVG, false, false, Arrays.asList(2), -1, SqlTypeName.DOUBLE, "avg_c");
        AggregateCall cdCFilter = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(2), -1, SqlTypeName.BIGINT, "cd_c");
        show("M unsupported nonDistinct + multi distinct JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg(ImmutableBitSet.of(0), null, cdB, cdCFilter, avgC));

        // N: no group by, single arglist with non distinct COUNT -> singleton distinct with global agg (JOIN)
        show("N global singleton JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg(ImmutableBitSet.of(), null, star, cdB));

        // O: INSTANCE global singleton with count default value path
        show("O global no-group single distinct INSTANCE", FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg(ImmutableBitSet.of(), null, star, cdB));

        // P: distinct on group key
        AggregateCall cdA = call(SqlStdOperatorTable.COUNT, true, false, Arrays.asList(0), -1, SqlTypeName.BIGINT, "cd_a");
        show("P distinct on group key JOIN", FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg(ImmutableBitSet.of(0), null, cdA, cdB));
    }

    static void show(String label, FlinkAggregateExpandDistinctAggregatesRule rule, RelNode rel) {
        HepProgramBuilder b = new HepProgramBuilder();
        b.addRuleInstance(rule);
        HepPlanner p = new HepPlanner(b.build());
        p.setRoot(rel);
        RelNode out;
        try {
            out = p.findBestExp();
        } catch (Throwable t) {
            System.out.println("### " + label + " -> THROWN " + t.getClass().getName() + ": " + t.getMessage());
            return;
        }
        System.out.println("### " + label + " sameAsInput=" + RelOptUtil.toString(out).equals(RelOptUtil.toString(rel)) + "\n" + Util.toLinux(RelOptUtil.toString(out)));
    }

    static AggregateCall call(org.apache.calcite.sql.SqlAggFunction f, boolean d, boolean approx,
                              java.util.List<Integer> args, int filter, SqlTypeName type, String name) {
        return AggregateCall.create(f, d, approx, args, filter, tf.createSqlType(type), name);
    }

    static RelNode agg(ImmutableBitSet groupSet, java.util.List<ImmutableBitSet> groupSets, AggregateCall... calls) {
        return LogicalAggregate.create(input, groupSet, groupSets, Arrays.asList(calls));
    }
}
