import com.google.common.collect.ImmutableList;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class S6 {
    static JavaTypeFactoryImpl tf = new JavaTypeFactoryImpl();
    static VolcanoPlanner volcano;
    static RelOptCluster cluster;

    public static void main(String[] args) throws Exception {
        volcano = new VolcanoPlanner(RelOptCostImpl.FACTORY, null);
        volcano.addRelTraitDef(ConventionTraitDef.INSTANCE);
        volcano.setRelMetadataProvider(DefaultRelMetadataProvider.INSTANCE);
        cluster = RelOptCluster.create(volcano, new RexBuilder(tf));
        RelDataType rowType = tf.builder()
                .add("a", tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.INTEGER), true))
                .add("b", tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.INTEGER), true))
                .add("c", tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.DOUBLE), true))
                .build();
        List<ImmutableList<RexLiteral>> rows = new ArrayList<>();
        rows.add(row(1, 10, 1.0));
        rows.add(row(1, 20, 2.0));
        rows.add(row(1, 20, 3.0));
        rows.add(row(2, 30, 4.0));
        rows.add(row(2, 30, 5.0));
        RelNode input = LogicalValues.create(cluster, rowType, ImmutableList.copyOf(rows));

        AggregateCall cdB = AggregateCall.create(SqlStdOperatorTable.COUNT, true, false,
                Arrays.asList(1), -1, tf.createSqlType(SqlTypeName.BIGINT), "cd_b");
        AggregateCall sumC = AggregateCall.create(SqlStdOperatorTable.SUM, false, false,
                Arrays.asList(2), -1, tf.createSqlType(SqlTypeName.DOUBLE), "sum_c");
        RelNode agg = LogicalAggregate.create(input, ImmutableBitSet.of(0), null, ImmutableList.of(cdB, sumC));

        System.out.println("original: " + exec(agg));
        RelNode r1 = applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, agg);
        System.out.println(Util.toLinux(RelOptUtil.toString(r1)));
        System.out.println("INSTANCE: " + exec(r1));
        RelNode r2 = applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, agg);
        System.out.println("JOIN: " + exec(r2));
    }

    static ImmutableList<RexLiteral> row(int a, int b, double c) {
        RexBuilder rb = cluster.getRexBuilder();
        RelDataType intNotNull = tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.INTEGER), false);
        RexLiteral la = rb.makeExactLiteral(BigDecimal.valueOf(a), intNotNull);
        RexLiteral lb = rb.makeExactLiteral(BigDecimal.valueOf(b), intNotNull);
        RexLiteral lc = (RexLiteral) rb.makeApproxLiteral(BigDecimal.valueOf(c),
                tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.DOUBLE), false));
        return ImmutableList.of(la, lb, lc);
    }

    static RelNode applyRule(FlinkAggregateExpandDistinctAggregatesRule rule, RelNode rel) {
        HepProgramBuilder b = new HepProgramBuilder();
        b.addRuleInstance(rule);
        HepPlanner p = new HepPlanner(b.build());
        p.setRoot(rel);
        return p.findBestExp();
    }

    static List<String> exec(RelNode rel) throws Exception {
        Program program = Programs.ofRules(
                EnumerableRules.ENUMERABLE_VALUES_RULE,
                EnumerableRules.ENUMERABLE_AGGREGATE_RULE,
                EnumerableRules.ENUMERABLE_PROJECT_RULE,
                EnumerableRules.ENUMERABLE_JOIN_RULE,
                EnumerableRules.ENUMERABLE_FILTER_RULE);
        RelNode out = program.run(volcano, rel, rel.getTraitSet().replace(EnumerableConvention.INSTANCE),
                ImmutableList.of(), ImmutableList.of());
        Bindable bindable = EnumerableInterpretable.toBindable(new java.util.HashMap<>(), null,
                (EnumerableRel) out, EnumerableRel.Prefer.ARRAY);
        List<String> result = new ArrayList<>();
        Enumerator<Object> e = bindable.bind(new DataContext() {
            public SchemaPlus getRootSchema() { return null; }
            public JavaTypeFactory getTypeFactory() { return tf; }
            public QueryProvider getQueryProvider() { return null; }
            public Object get(String name) { return null; }
        }).enumerator();
        while (e.moveNext()) {
            result.add(String.valueOf(e.current()));
        }
        return result;
    }
}
