        System.out.println("### " + label);
        for (RelNode n : collect(out, RelNode.class)) {
            System.out.println("  node " + n.getClass().getSimpleName());
            if (n instanceof LogicalProject) {
                for (RexNode e : ((LogicalProject) n).getProjects()) {
                    System.out.println("    expr " + e.getKind() + " ops=" + (e instanceof RexCall ? String.valueOf(((RexCall) e).getOperator()) : "-"));
