        Deque<RelNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            RelNode n = stack.pop();
            if (clazz.isInstance(n)) {
                result.add(clazz.cast(n));
            }
            for (RelNode c : n.getInputs()) {
                stack.push(c);
            }
        }
        return result;
    }

