  List<ImmutableBitSet> groupSets = getGroupSets();
  if (groupSets.size() == 1) {
    if (groupSets.get(0).equals(groupSet)) return Group.SIMPLE;
    // maybe not
  }
  if (groupSets.size() == 2 && groupSets.contains(ImmutableBitSet.of()) && groupSets.contains(groupSet)) {
