import org.apache.calcite.config.CalciteConnectionConfig;
import org.apache.calcite.jdbc.CalciteSchema;
import org.apache.calcite.plan.*;
import org.apache.calcite.plan.hep.*;
import org.apache.calcite.plan.volcano.VolcanoPlanner;
import org.apache.calcite.prepare.CalciteCatalogReader;
import org.apache.calcite.rel.*;
import org.apache.calcite.rel.core.*;
import org.apache.calcite.rel.logical.*;
import org.apache.calcite.rel.type.*;
import org.apache.calcite.rex.*;
import org.apache.calcite.schema.impl.AbstractTable;
import org.apache.calcite.sql.*;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.type.*;
import org.apache.calcite.tools.*;
import org.apache.calcite.util.*;
import org.apache.flink.table.planner.plan.rules.logical.FlinkAggregateJoinTransposeRule;
import org.apache.flink.table.planner.functions.sql.FlinkSqlOperatorTable;
import java.util.*;

public class Exp3 {
  static RelDataTypeFactory tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
  static RexBuilder rex = new RexBuilder(tf);
  static RelOptCluster cluster;
  static RelBuilder rb;
  static RelNode join;

  static AbstractTable table(RelDataTypeFactory f, String... cols) {
    return new AbstractTable() {
      @Override public RelDataType getRowType(RelDataTypeFactory t) {
        RelDataTypeFactory.Builder b = t.builder();
        for (String c : cols) {
          if (c.equals("ACTIVE")) b.add(c, t.createSqlType(SqlTypeName.BOOLEAN));
          else if (c.equals("SAL")) b.add(c, t.createSqlType(SqlTypeName.INTEGER));
          else b.add(c, t.createSqlType(SqlTypeName.INTEGER));
        }
        return b.build();
      }
    };
  }
  static void init() {
    CalciteSchema root = CalciteSchema.createRootSchema(false, false);
    root.add("EMP", table(tf,"EMPNO","DEPTNO","SAL","ACTIVE"));
    root.add("DEPT", table(tf,"DEPTNO","DNAME"));
    CalciteCatalogReader catalog = new CalciteCatalogReader(root, Collections.emptyList(), tf, CalciteConnectionConfig.DEFAULT);
    cluster = RelOptCluster.create(new VolcanoPlanner(), rex);
    rb = RelBuilder.proto(Contexts.empty()).create(cluster, catalog);
    join = rb.scan("EMP").scan("DEPT")
        .join(JoinRelType.INNER, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO")))
        .build();
  }
  static AggregateCall call(SqlAggFunction fn, boolean distinct, List<Integer> args, int filter, RelDataType type, String name) {
    return AggregateCall.create(fn, distinct, false, false, ImmutableList.of(), args, filter, null, RelCollations.EMPTY, type, name);
  }
  static Aggregate agg(RelNode input, ImmutableBitSet groupSet, List<AggregateCall> calls) {
    return LogicalAggregate.create(input, groupSet, ImmutableList.of(groupSet), calls);
  }
  static RelNode apply(RelNode in, RelOptRule rule) {
    HepProgram p = new HepProgramBuilder().addRuleInstance(rule).build();
    HepPlanner h = new HepPlanner(p);
    h.setRoot(in);
    return h.findBestExp();
  }
  static RelDataType intType() { return tf.createSqlType(SqlTypeName.INTEGER); }
  static void show(String name, RelNode in, RelOptRule rule) {
    System.out.println("#### " + name);
    try {
      System.out.println("--in--\n" + in.explain());
      System.out.println("--out--\n" + apply(in, rule).explain());
    } catch (Throwable t) { System.out.println("ERROR: " + t); t.printStackTrace(System.out); }
  }
  public static void main(String[] a) {
    init();
    System.out.println("join type=" + join.getRowType());

    RelNode aggNoFn = agg(join, ImmutableBitSet.of(1), Collections.emptyList());
    show("A INSTANCE no fn", aggNoFn, FlinkAggregateJoinTransposeRule.INSTANCE);
    show("A EXTENDED no fn", aggNoFn, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode aggSum = agg(join, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.SUM, false, List.of(2), -1, intType(), "S")));
    show("C EXTENDED sum", aggSum, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode leftJoin = rb.scan("EMP").scan("DEPT")
        .join(JoinRelType.LEFT, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
    RelNode aggLeft = agg(leftJoin, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("D LEFT join", aggLeft, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode aggDistinct = agg(join, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, true, List.of(2), -1, intType(), "CD")));
    show("E DISTINCT", aggDistinct, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode aggFilter = agg(join, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), 3, intType(), "CF")));
    show("F FILTER", aggFilter, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode nonEqui = rb.scan("EMP").scan("DEPT")
        .join(JoinRelType.INNER, rb.lessThan(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
    RelNode aggNonEqui = agg(nonEqui, ImmutableBitSet.of(0),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("G non-equi", aggNonEqui, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode snap = LogicalSnapshot.create(rb.scan("DEPT").build(), rb.literal(true));
    RelNode rightSnapJoin = rb.scan("EMP").push(snap)
        .join(JoinRelType.INNER, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
    RelNode aggRightSnap = agg(rightSnapJoin, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("H right snapshot", aggRightSnap, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode leftSnap = LogicalSnapshot.create(rb.scan("EMP").build(), rb.literal(true));
    RelNode leftSnapJoin = rb.push(leftSnap).scan("DEPT")
        .join(JoinRelType.INNER, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
    RelNode aggLeftSnap = agg(leftSnapJoin, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("I left snapshot", aggLeftSnap, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode filterOverSnap = LogicalFilter.create(snap, rb.literal(true));
    RelNode rightNestedJoin = rb.scan("EMP").push(filterOverSnap)
        .join(JoinRelType.INNER, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
    RelNode aggRightNested = agg(rightNestedJoin, ImmutableBitSet.of(1),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("J right filter->snapshot", aggRightNested, FlinkAggregateJoinTransposeRule.EXTENDED);

    // K aux group: aux call on field 2 (SAL), group {1}, plus sum
    AggregateCall aux = AggregateCall.create(FlinkSqlOperatorTable.AUXILIARY_GROUP,
        false, false, false, ImmutableList.of(), ImmutableList.of(2), -1, null, RelCollations.EMPTY,
        intType(), "SAL");
    AggregateCall sum = call(SqlStdOperatorTable.SUM, false, List.of(2), -1, intType(), "S");
    RelNode aggAux = agg(join, ImmutableBitSet.of(1), List.of(aux, sum));
    show("K aux group", aggAux, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode aggEmpno = agg(join, ImmutableBitSet.of(0),
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    show("L group by empno", aggEmpno, FlinkAggregateJoinTransposeRule.EXTENDED);

    RelNode aggGroupSets = LogicalAggregate.create(join, ImmutableBitSet.of(1),
        List.of(ImmutableBitSet.of(1), ImmutableBitSet.of()), 
        List.of(call(SqlStdOperatorTable.COUNT, false, List.of(), -1, intType(), "C")));
    System.out.println("groupType=" + ((Aggregate)aggGroupSets).getGroupType());
    show("M group sets", aggGroupSets, FlinkAggregateJoinTransposeRule.EXTENDED);

    // unsupported splitter scan
    System.out.println("### splitters");
    for (SqlOperator op : SqlStdOperatorTable.instance().getOperatorList()) {
      if (op instanceof SqlAggFunction) {
        System.out.println(op.getName() + " -> " + (((SqlAggFunction)op).unwrap(SqlSplittableAggFunction.class) != null));
      }
    }
  }
}
