import org.apache.flink.table.planner.functions.sql.FlinkSqlOperatorTable;
import java.util.*;

public class Exp4 {
  static RelDataTypeFactory tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
  static RexBuilder rex = new RexBuilder(tf);
  static RelOptCluster cluster;
  static RelBuilder rb;
  static RelNode join;
  static AbstractTable table(RelDataTypeFactory f, String... cols) {
    return new AbstractTable() {
      @Override public RelDataType getRowType(RelDataTypeFactory t) {
        RelDataTypeFactory.Builder b = t.builder();
        for (String c : cols) b.add(c, c.equals("ACTIVE") ? t.createSqlType(SqlTypeName.BOOLEAN) : t.createSqlType(SqlTypeName.INTEGER));
        return b.build();
      }
    };
  }
  static void init() {
    CalciteSchema root = CalciteSchema.createRootSchema(false, false);
    root.add("EMP", table(tf,"EMPNO","DEPTNO","SAL","ACTIVE"));
    root.add("DEPT", table(tf,"DEPTNO","DNAME"));
    CalciteCatalogReader catalog = new CalciteCatalogReader(root, Collections.emptyList(), tf, CalciteConnectionConfig.DEFAULT);
    cluster = RelOptCluster.create(new VolcanoPlanner(), rex);
    rb = RelBuilder.proto(Contexts.empty()).create(cluster, catalog);
    join = rb.scan("EMP").scan("DEPT").join(JoinRelType.INNER, rb.equals(rb.field(2,0,"DEPTNO"), rb.field(2,1,"DEPTNO"))).build();
  }
  static AggregateCall call(SqlAggFunction fn, boolean distinct, List<Integer> args, int filter, RelDataType type, String name) {
    return AggregateCall.create(fn, distinct, false, false, Collections.emptyList(), args, filter, null, RelCollations.EMPTY, type, name);
  }
  static Aggregate agg(RelNode input, ImmutableBitSet groupSet, List<AggregateCall> calls) {
    return LogicalAggregate.create(input, groupSet, Collections.singletonList(groupSet), calls);
  }
  static RelNode apply(RelNode in, RelOptRule rule) {
    HepProgram p = new HepProgramBuilder().addRuleInstance(rule).build();
    HepPlanner h = new HepPlanner(p); h.setRoot(in); return h.findBestExp();
  }
  static RelDataType intType() { return tf.createSqlType(SqlTypeName.INTEGER); }
  static void show(String n, RelNode in, RelOptRule r) {
    RelNode out = apply(in, r);
    System.out.println("#### " + n + " same=" + (out == in));
    System.out.println("in  type=" + in.getRowType());
    System.out.println("out type=" + out.getRowType());
    System.out.println("in  names=" + in.getRowType().getFieldNames());
    System.out.println("out names=" + out.getRowType().getFieldNames());
    System.out.println(out.explain());
  }
  public static void main(String[] a) {
    init();
    RelNode cnt = agg(join, ImmutableBitSet.of(1), Collections.singletonList(call(SqlStdOperatorTable.COUNT, false, Collections.emptyList(), -1, intType(), "C")));
    show("COUNT star", cnt, FlinkAggregateJoinTransposeRule.EXTENDED);
    RelNode sum = agg(join, ImmutableBitSet.of(1), Collections.singletonList(call(SqlStdOperatorTable.SUM, false, Collections.singletonList(2), -1, intType(), "S")));
    show("SUM", sum, FlinkAggregateJoinTransposeRule.EXTENDED);
    RelNode nofn = agg(join, ImmutableBitSet.of(1), Collections.emptyList());
    show("no fn", nofn, FlinkAggregateJoinTransposeRule.EXTENDED);
    AggregateCall aux = AggregateCall.create(FlinkSqlOperatorTable.AUXILIARY_GROUP, false, false, false, Collections.emptyList(), Collections.singletonList(2), -1, null, RelCollations.EMPTY, intType(), "SAL");
    RelNode auxa = agg(join, ImmutableBitSet.of(1), Arrays.asList(aux, call(SqlStdOperatorTable.SUM, false, Collections.singletonList(2), -1, intType(), "S")));
    show("aux", auxa, FlinkAggregateJoinTransposeRule.EXTENDED);
    RelNode empno = agg(join, ImmutableBitSet.of(0), Collections.singletonList(call(SqlStdOperatorTable.COUNT, false, Collections.emptyList(), -1, intType(), "C")));
    show("empno", empno, FlinkAggregateJoinTransposeRule.EXTENDED);
    // no fn INSTANCE
    show("no fn INSTANCE", nofn, FlinkAggregateJoinTransposeRule.INSTANCE);
  }
}
