import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link SubQueryDecorrelator}.
 *
 * <p>The tests construct logical relational trees directly so that the public entry point {@link
 * SubQueryDecorrelator#decorrelateQuery(RelNode)} can be exercised with precisely controlled
 * correlated subqueries.
 */
class SubQueryDecorrelatorTests {

    private RelOptCluster cluster;
    private RexBuilder rexBuilder;
    private FlinkTypeFactory typeFactory;

    @BeforeEach
    void setUp() {
        typeFactory = new FlinkTypeFactory(getClass().getClassLoader(), FlinkTypeSystem.INSTANCE);
        FlinkContext context =
                new FlinkContextImpl(
                        true,
                        TableConfig.getDefault(),
                        null,
                        null,
                        null,
                        null,
                        getClass().getClassLoader());
        RelOptPlanner planner = new VolcanoPlanner(context);
        cluster =
                FlinkRelOptClusterFactory.create(
                        planner, new FlinkRexBuilder(typeFactory));
        rexBuilder = cluster.getRexBuilder();
    }

    @Test
    void testRootWithoutSubqueryProducesEmptyResult() {
        RelNode values = values(rowType("a"), 1);
        RelNode filter =
                LogicalFilter.create(
                        values, rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL,
                                rexBuilder.makeInputRef(values, 0)));

        Result result = SubQueryDecorrelator.decorrelateQuery(filter);

        assertNotNull(result);
        // There is no subquery in the tree, so no mapping can be retrieved.
        assertNull(result.getSubQueryEquivalent(RexSubQuery.exists(values)));
    }

    @Test
    void testNonCorrelatedSubqueryProducesEmptyResult() {
        RelNode outerValues = values(rowType("a"), 1);
        RelNode innerValues = values(rowType("b"), 2);
        RexSubQuery subQuery = RexSubQuery.exists(innerValues);
        RelNode outerFilter = LogicalFilter.create(outerValues, subQuery);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        assertNull(result.getSubQueryEquivalent(subQuery));
    }

    @Test
    void testSimpleCorrelatedExistsIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);

        // The correlation condition is pulled out and refers to the outer field as well as the
        // subquery field, both addressed as top-level input references.
        ImmutableBitSet conditionInputs = org.apache.calcite.plan.RelOptUtil.InputFinder.bits(equivalent.right);
        assertTrue(conditionInputs.get(0));
        assertTrue(conditionInputs.get(1));
        assertEquals(2, conditionInputs.cardinality());

        // The rewritten subquery has a single output column and no longer has correlation
        // variables embedded in it.
        assertEquals(1, equivalent.left.getRowType().getFieldCount());
        assertFalse(equivalent.right.toString().contains("$cor"));
    }

    @Test
    void testCorrelatedScalarSubqueryIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.scalar(innerFilter);
        RexNode outerField = rexBuilder.makeInputRef(outerType, 0);
        RexNode condition = rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, outerField, subQuery);
        RelNode outerFilter = outerFilter(values(outerType, 1), condition, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);
        assertEquals(1, equivalent.left.getRowType().getFieldCount());
    }

    @Test
    void testInSubqueryAddsProjectionToAlignOutputFields() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery =
                RexSubQuery.in(
                        innerFilter, ImmutableList.of(rexBuilder.makeInputRef(outerType, 0)));
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        // IN requires an explicit projection around the subquery to keep the output order stable.
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertEquals(1, project.getRowType().getFieldCount());
        assertEquals("b", project.getRowType().getFieldNames().get(0));
    }

    @Test
    void testExistsSubqueryProjectsOnlyCorrelatedFields() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b0", "b1"), 7, 8);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        // Only the column participating in the correlation condition is kept.
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertEquals(1, project.getRowType().getFieldCount());
        assertEquals("b0", project.getRowType().getFieldNames().get(0));
    }

    @Test
    void testSortInSubqueryIsPreserved() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RelNode sort =
                LogicalSort.create(
                        innerFilter, RelCollations.of(0), null, null);
        RexSubQuery subQuery = RexSubQuery.exists(sort);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        Sort rewrittenSort = assertInstanceOf(Sort.class, equivalent.left);
        assertEquals(1, rewrittenSort.getRowType().getFieldCount());
    }

    @Test
    void testAggregateInSubqueryIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        AggregateCall count =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        false,
                        ImmutableList.of(),
                        -1,
                        typeFactory.createSqlType(SqlTypeName.BIGINT),
                        "cnt");
        RelNode aggregate =
                LogicalAggregate.create(
                        innerFilter,
                        ImmutableBitSet.of(),
                        ImmutableList.of(ImmutableBitSet.of()),
                        ImmutableList.of(count));
        RexSubQuery subQuery = RexSubQuery.exists(aggregate);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        assertInstanceOf(LogicalAggregate.class, equivalent.left);
    }

    @Test
    void testOrConditionOnCorrelationVariableIsUnsupported() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RexNode corField = correlatedField(outerType, correlationId, 0);
        RexNode equality =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.EQUALS,
                        corField,
                        rexBuilder.makeInputRef(innerValues, 0));
        RexNode greaterThan =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.GREATER_THAN,
                        rexBuilder.makeInputRef(innerValues, 0),
                        rexBuilder.makeExactLiteral(
                                BigDecimal.TEN, typeFactory.createSqlType(SqlTypeName.INTEGER)));
        RelNode innerFilter =
                LogicalFilter.create(
                        innerValues,
                        rexBuilder.makeCall(SqlStdOperatorTable.OR, equality, greaterThan));
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        assertNull(SubQueryDecorrelator.decorrelateQuery(outerFilter));
    }

    @Test
    void testNestedCorrelatedSubqueryIsUnsupported() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode nestedValues = values(rowType("c"), 9);
        RelNode nestedFilter =
                correlatedFilter(outerType, correlationId, nestedValues, 0, 0);
        RelNode innerValues = values(rowType("b"), 7);
        RexNode innerEquality =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.EQUALS,
                        correlatedField(outerType, correlationId, 0),
                        rexBuilder.makeInputRef(innerValues, 0));
        RelNode innerFilter =
                LogicalFilter.create(
                        innerValues,
                        rexBuilder.makeCall(
                                SqlStdOperatorTable.AND,
                                innerEquality,
                                RexSubQuery.exists(nestedFilter)));
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        assertNull(SubQueryDecorrelator.decorrelateQuery(outerFilter));
    }

    @Test
    void testCorrelatedRightInputOfLeftJoinIsUnsupported() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode leftValues = values(rowType("l"), 1);
        RelNode rightValues = values(rowType("r"), 2);
        RelNode correlatedRight =
                correlatedFilter(outerType, correlationId, rightValues, 0, 0);
        RelNode join =
                LogicalJoin.create(
                        leftValues,
                        correlatedRight,
                        ImmutableList.of(),
                        rexBuilder.makeLiteral(true),
                        ImmutableSet.of(),
                        JoinRelType.LEFT);
        RexSubQuery subQuery = RexSubQuery.exists(join);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        assertNull(SubQueryDecorrelator.decorrelateQuery(outerFilter));
    }

    @Test
    void testUnrelatedSubqueryLookupReturnsNull() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery correlated = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), correlated, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);
        assertNotNull(result);
        assertNotNull(result.getSubQueryEquivalent(correlated));

        RexSubQuery unrelated = RexSubQuery.exists(values(rowType("x"), 1));
        assertNull(result.getSubQueryEquivalent(unrelated));
    }

    // ------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------

    private RelDataType rowType(String... names) {
        RelDataTypeFactory.Builder builder = typeFactory.builder();
        for (String name : names) {
            builder.add(name, typeFactory.createSqlType(SqlTypeName.INTEGER));
        }
        return builder.build();
    }

    private RelNode values(RelDataType rowType, int... values) {
        List<RexLiteral> row = new ArrayList<>();
        for (int value : values) {
            row.add(
                    rexBuilder.makeExactLiteral(
                            BigDecimal.valueOf(value),
                            typeFactory.createSqlType(SqlTypeName.INTEGER)));
        }
        return LogicalValues.create(
                cluster, rowType, ImmutableList.of(ImmutableList.copyOf(row)));
    }

    private RexNode correlatedField(
            RelDataType outerRowType, CorrelationId correlationId, int fieldIndex) {
        return rexBuilder.makeFieldAccess(
                rexBuilder.makeCorrel(outerRowType, correlationId), fieldIndex);
    }

    private RelNode correlatedFilter(
            RelDataType outerRowType,
            CorrelationId correlationId,
            RelNode input,
            int outerFieldIndex,
            int innerFieldIndex) {
        RexNode condition =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.EQUALS,
                        correlatedField(outerRowType, correlationId, outerFieldIndex),
                        rexBuilder.makeInputRef(input, innerFieldIndex));
        return LogicalFilter.create(input, condition);
    }

    private RelNode outerFilter(
            RelNode outerInput, RexNode condition, CorrelationId correlationId) {
        return LogicalFilter.create(outerInput, condition, ImmutableSet.of(correlationId));
    }
}
