        byte[] bytes = new byte[] {1, 2, 3};
        assertArrayEquals(bytes, PrimitiveByteArrayConverter.INSTANCE.toExternal(bytes));
        assertArrayEquals(
                bytes,
                PrimitiveByteArrayConverter.INSTANCE.toExternal(GenericRowData.of(bytes), 0));

        short[] shorts = new short[] {1, 2, 3};
        assertArrayEquals(
                shorts,
                PrimitiveShortArrayConverter.INSTANCE.toExternal(
                        PrimitiveShortArrayConverter.INSTANCE.toInternal(shorts)));
        assertArrayEquals(
                shorts,
                PrimitiveShortArrayConverter.INSTANCE.toExternal(
                        GenericRowData.of(new GenericArrayData(shorts)), 0));

        int[] ints = new int[] {1, 2, 3};
        assertArrayEquals(
                ints,
                PrimitiveIntArrayConverter.INSTANCE.toExternal(
                        PrimitiveIntArrayConverter.INSTANCE.toInternal(ints)));
        assertArrayEquals(
                ints,
                PrimitiveIntArrayConverter.INSTANCE.toExternal(
                        GenericRowData.of(new GenericArrayData(ints)), 0));

        long[] longs = new long[] {1L, 2L, 3L};
        assertArrayEquals(
                longs,
                PrimitiveLongArrayConverter.INSTANCE.toExternal(
                        PrimitiveLongArrayConverter.INSTANCE.toInternal(longs)));
        assertArrayEquals(
                longs,
                PrimitiveLongArrayConverter.INSTANCE.toExternal(
                        GenericRowData.of(new GenericArrayData(longs)), 0));

        float[] floats = new float[] {1.5f, 2.5f, 3.5f};
        assertArrayEquals(
                floats,
                PrimitiveFloatArrayConverter.INSTANCE.toExternal(
                        PrimitiveFloatArrayConverter.INSTANCE.toInternal(floats)),
                0.0f);
        assertArrayEquals(
                floats,
                PrimitiveFloatArrayConverter.INSTANCE.toExternal(
                        GenericRowData.of(new GenericArrayData(floats)), 0),
                0.0f);

        double[] doubles = new double[] {1.5d, 2.5d, 3.5d};
        assertArrayEquals(
                doubles,
                PrimitiveDoubleArrayConverter.INSTANCE.toExternal(
                        PrimitiveDoubleArrayConverter.INSTANCE.toInternal(doubles)),
                0.0d);
        assertArrayEquals(
                doubles,
                PrimitiveDoubleArrayConverter.INSTANCE.toExternal(
                        GenericRowData.of(new GenericArrayData(doubles)), 0),
                0.0d);
    }

    @Test
    void testObjectArrayConverterWithIdentityElementConverter() {
        ObjectArrayConverter<Integer> converter =
                new ObjectArrayConverter<>(DataTypes.INT().bridgedTo(Integer.class));
        Integer[] values = new Integer[] {1, null, 3};
        ArrayData internal = converter.toInternal(values);
        assertInstanceOf(GenericArrayData.class, internal);
        assertArrayEquals(values, converter.toExternal(internal));
        assertArrayEquals(
                values,
                converter.toExternal(GenericRowData.of(internal), 0));

        Integer[] primitiveArrayResult =
                converter.toExternal(new GenericArrayData(new int[] {4, 5}));
        assertArrayEquals(new Integer[] {4, 5}, primitiveArrayResult);
    }

    @Test
    void testObjectArrayConverterWithConvertingElementConverter() {
        ObjectArrayConverter<String> converter =
                new ObjectArrayConverter<>(DataTypes.STRING().bridgedTo(String.class));
        String[] values = new String[] {"first", null, "third"};
        ArrayData internal = converter.toInternal(values);
        assertTrue(!(internal instanceof GenericArrayData));
        assertArrayEquals(values, converter.toExternal(internal));
        assertArrayEquals(
                values,
                converter.toExternal(GenericRowData.of(internal), 0));

        assertEquals(3, converter.toExternal(internal).length);
        assertArrayEquals(
                new String[] {"a", "b"},
                converter.toExternal(converter.toInternal(new String[] {"a", "b"})));
        assertArrayEquals(
                new String[] {"c", "d"},
                converter.toExternal(converter.toInternal(new String[] {"c", "d"})));
    }

    @Test
    void testObjectArrayConverterReadsGenericArrayDataWithElementConversion() {
        ObjectArrayConverter<String> converter =
                new ObjectArrayConverter<>(DataTypes.STRING().bridgedTo(String.class));
        GenericArrayData generic =
                new GenericArrayData(
                        new Object[] {StringData.fromString("one"), null, StringData.fromString("three")});
        assertArrayEquals(
                new String[] {"one", null, "three"}, converter.toExternal(generic));
    }

    @Test
    void testMapConverterWithIdentityKeyAndValueConverters() {
        MapConverter converter =
                new MapConverter(
                        DataTypes.INT().bridgedTo(Integer.class),
                        DataTypes.BIGINT().bridgedTo(Long.class));
        Map<Integer, Long> values = new LinkedHashMap<>();
        values.put(1, 10L);
        values.put(2, null);

        MapData internal = converter.toInternal(values);
        assertInstanceOf(GenericMapData.class, internal);
        assertEquals(values, converter.toExternal(internal));
        assertEquals(values, converter.toExternal(GenericRowData.of(internal), 0));
    }

    @Test
    void testMapConverterWithConvertedKeysAndValues() {
        MapConverter converter =
                new MapConverter(
                        DataTypes.STRING().bridgedTo(String.class),
                        DataTypes.STRING().bridgedTo(String.class));
        Map<String, String> values = new LinkedHashMap<>();
        values.put("one", "first");
        values.put("two", null);
        values.put("three", "third");

        MapData internal = converter.toInternal(values);
        assertEquals(values, converter.toExternal(internal));
        assertEquals(values, converter.toExternal(GenericRowData.of(internal), 0));

        Map<String, String> second = new LinkedHashMap<>();
        second.put("four", "fourth");
        assertEquals(second, converter.toExternal(converter.toInternal(second)));
        assertEquals(second, converter.toExternal(converter.toInternal(second)));
    }

    @Test
    void testRowConverterPreservesValuesKindAndNulls() {
        RowConverter converter =
                new RowConverter(
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        Row row = Row.ofKind(RowKind.UPDATE_BEFORE, 42, null);
        RowData internal = converter.toInternal(row);
        assertEquals(RowKind.UPDATE_BEFORE, internal.getRowKind());
        assertEquals(42, internal.getInt(0));
        assertTrue(internal.isNullAt(1));

        Row result = converter.toExternal(internal);
        assertEquals(RowKind.UPDATE_BEFORE, result.getKind());
        assertEquals(42, result.getField(0));
        assertNull(result.getField(1));
        assertEquals(result, converter.toExternal(internal));
    }

    @Test
    void testRowDataConverterFromLookupReadsNestedRow() {
        DataFormatConverter<RowData, RowData> converter =
                DataFormatConverters.getConverterForDataType(
                        DataTypes.ROW(DataTypes.INT(), DataTypes.STRING())
                                .bridgedTo(RowData.class));
        GenericRowData nested = GenericRowData.of(1, StringData.fromString("nested"));
        GenericRowData outer = GenericRowData.of(nested);
        assertSame(nested, converter.toExternal(outer, 0));
        assertSame(nested, converter.toInternal(nested));
        assertSame(nested, converter.toExternal(nested));
        assertNull(converter.toExternal(GenericRowData.of((Object) null), 0));
    }

    @Test
    void testTupleConverter() {
        TupleConverter converter =
                new TupleConverter(
                        Tuple2.class,
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        Tuple2<Integer, String> tuple = Tuple2.of(1, "one");
        RowData internal = converter.toInternal(tuple);
        assertEquals(1, internal.getInt(0));
        assertEquals("one", internal.getString(1).toString());

        Tuple2<?, ?> result = (Tuple2<?, ?>) converter.toExternal(internal);
        assertEquals(1, result.f0);
        assertEquals("one", result.f1);

        GenericRowData second = GenericRowData.of(2, StringData.fromString("two"));
        Tuple2<?, ?> secondResult = (Tuple2<?, ?>) converter.toExternal(second);
        assertEquals(2, secondResult.f0);
        assertEquals("two", secondResult.f1);
    }

    @Test
    void testPojoConverter() {
        @SuppressWarnings("unchecked")
        PojoTypeInfo<TestPojo> typeInfo =
                (PojoTypeInfo<TestPojo>) TypeExtractor.getForClass(TestPojo.class);
        PojoConverter<TestPojo> converter =
                new PojoConverter<>(
                        typeInfo,
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        TestPojo pojo = new TestPojo();
        pojo.id = 7;
        pojo.name = "seven";

        RowData internal = converter.toInternal(pojo);
        assertEquals(7, internal.getInt(0));
        assertEquals("seven", internal.getString(1).toString());

        TestPojo result = converter.toExternal(internal);
        assertEquals(7, result.id);
        assertEquals("seven", result.name);
    }

    @Test
    void testGenericConverterUsesProvidedSerializer() {
        GenericConverter<Integer> converter = new GenericConverter<>(IntSerializer.INSTANCE);
        RawValueData<Integer> internal = converter.toInternal(123);
        assertEquals(123, converter.toExternal(internal));
        assertEquals(123, converter.toExternal(GenericRowData.of(internal), 0));
        assertNull(converter.toInternal(null));
        assertNull(converter.toExternal((RawValueData<Integer>) null));
    }

    private static DataFormatConverter<?, ?> converter(DataType dataType) {
        return DataFormatConverters.getConverterForDataType(dataType);
    }

    private static <T> void assertConverted(
            GenericRowData row, DataFormatConverter<T, T> converter, T value) {
        assertSame(value, converter.toInternal(value));
        assertSame(value, converter.toExternal(value));
        assertEquals(value, converter.toExternal(row, 0));
    }

    /** Simple POJO used to verify reflective field access. */
    public static class TestPojo {
        public int id;
        public String name;

        public TestPojo() {}
    }
}
