    @Test
    void testAddToEnvironmentCreatesAndAppendsVariables() {
        Map<String, String> environment = new HashMap<>();

        Utils.addToEnvironment(environment, "VAR", "first");
        Utils.addToEnvironment(environment, "VAR", "second");

        assertEquals("first" + File.pathSeparator + "second", environment.get("VAR"));
    }

    @Test
    void testSetupYarnClassPathContainsFlinkAndYarnClasspathEntries() {
        YarnConfiguration yarnConfiguration = new YarnConfiguration();
        yarnConfiguration.setStrings(
                YarnConfiguration.YARN_APPLICATION_CLASSPATH, "yarn/one.jar", "yarn/two.jar");
        Map<String, String> environment = new HashMap<>();
        environment.put(YarnConfigKeys.ENV_FLINK_CLASSPATH, "flink/classpath");
        environment.put("CLASSPATH", "existing");

        Utils.setupYarnClassPath(yarnConfiguration, environment);

        String classpath = environment.get(ApplicationConstants.Environment.CLASSPATH.name());
        assertEquals(
                String.join(
                        File.pathSeparator,
                        "existing",
                        "flink/classpath",
                        "yarn/one.jar",
                        "yarn/two.jar"),
                classpath);
    }

    @Test
    void testSetupYarnClassPathWithoutExistingFlinkClasspath() {
        YarnConfiguration yarnConfiguration = new YarnConfiguration();
        yarnConfiguration.setStrings(
                YarnConfiguration.YARN_APPLICATION_CLASSPATH, "first.jar", "second.jar");
        Map<String, String> environment = new HashMap<>();

        Utils.setupYarnClassPath(yarnConfiguration, environment);

        assertEquals(
                "first.jar" + File.pathSeparator + "second.jar",
                environment.get(ApplicationConstants.Environment.CLASSPATH.name()));
    }

    @Test
    void testDeleteApplicationFilesDeletesDirectoryRecursively() throws IOException {
        java.nio.file.Path directory = Files.createDirectory(tempDir.resolve("application-files"));
        Files.write(directory.resolve("nested.txt"), "content".getBytes(StandardCharsets.UTF_8));

        Utils.deleteApplicationFiles(directory.toString());

        assertFalse(Files.exists(directory));
    }

    @Test
    void testDeleteApplicationFilesIgnoresNullOrBlankDirectory() throws IOException {
        java.nio.file.Path directory = Files.createDirectory(tempDir.resolve("keep-me"));

        Utils.deleteApplicationFiles(null);
        Utils.deleteApplicationFiles("   ");

        assertTrue(Files.exists(directory));
    }

    @Test
    void testResolveKeytabPathAbsoluteRelativeAndMissing() throws IOException {
        java.nio.file.Path absoluteKeytab = Files.createFile(tempDir.resolve("absolute.keytab"));
        java.nio.file.Path workingDirectory = Files.createDirectory(tempDir.resolve("working"));
        java.nio.file.Path relativeKeytab =
                Files.createFile(workingDirectory.resolve("relative.keytab"));

        assertEquals(
                absoluteKeytab.toFile().getAbsolutePath(),
                Utils.resolveKeytabPath(workingDirectory.toString(), absoluteKeytab.toString()));
        assertEquals(
                relativeKeytab.toFile().getAbsolutePath(),
                Utils.resolveKeytabPath(workingDirectory.toString(), "relative.keytab"));
        assertNull(Utils.resolveKeytabPath(workingDirectory.toString(), "missing.keytab"));
        assertNull(Utils.resolveKeytabPath(workingDirectory.toString(), null));
    }

    @Test
    void testRegisterLocalResourceCopiesAllDescriptorFields() {
        Path remotePath = new Path("hdfs://localhost:8020/flink/resource.jar");

        LocalResource localResource =
                Utils.registerLocalResource(
                        remotePath,
                        17L,
                        42L,
                        LocalResourceVisibility.PUBLIC,
                        LocalResourceType.ARCHIVE);

        assertEquals(URL.fromURI(remotePath.toUri()), localResource.getResource());
        assertEquals(17L, localResource.getSize());
        assertEquals(42L, localResource.getTimestamp());
        assertEquals(LocalResourceVisibility.PUBLIC, localResource.getVisibility());
        assertEquals(LocalResourceType.ARCHIVE, localResource.getType());
    }

