/** Tests for the external behavior of the {@link FlinkYarnSessionCli}. */
class FlinkYarnSessionCliTests {

    private static final String SHORT_PREFIX = "y";
    private static final String LONG_PREFIX = "yarn";

    private static final String CONFIGURATION_DIRECTORY = "/flink/conf";

    private static final String APPLICATION_ID = "application_1234_0001";
    private static final String CONFIGURED_APPLICATION_ID = "application_1234_0002";

    private static final String YARN_PROPERTIES_FILE_PREFIX = ".yarn-properties-";

    @TempDir Path temporaryFolder;

    // ------------------------------------------------------------------------
    //  helpers
    // ------------------------------------------------------------------------

    private Configuration newConfiguration() {
        final Configuration configuration = new Configuration();
        configuration.set(
                YarnConfigOptions.PROPERTIES_FILE_LOCATION, temporaryFolder.toString());
        return configuration;
    }

    private FlinkYarnSessionCli createCli() throws FlinkException {
        return createCli(newConfiguration());
    }

    private FlinkYarnSessionCli createCli(Configuration configuration) throws FlinkException {
        return new FlinkYarnSessionCli(
                configuration,
                new DefaultClusterClientServiceLoader(),
                CONFIGURATION_DIRECTORY,
                SHORT_PREFIX,
                LONG_PREFIX,
