    private void writeYarnPropertiesFile(Map<String, String> properties) throws IOException {
        final StringBuilder fileContent = new StringBuilder();
        for (Map.Entry<String, String> property : properties.entrySet()) {
            fileContent
                    .append(property.getKey())
                    .append('=')
                    .append(property.getValue())
                    .append(System.lineSeparator());
        }
        Files.write(yarnPropertiesFile().toPath(), fileContent.toString().getBytes(StandardCharsets.UTF_8));
    }

    private static Map<String, String> properties(String... keyValuePairs) {
        final Map<String, String> properties = new LinkedHashMap<>();
        for (int i = 0; i < keyValuePairs.length; i += 2) {
            properties.put(keyValuePairs[i], keyValuePairs[i + 1]);
        }
        return properties;
    }

    private static CommandLine parse(FlinkYarnSessionCli cli, String... args)
            throws CliArgsException {
        return cli.parseCommandLineOptions(args, true);
    }

