private void writeYarnPropertiesFile(Map<String, String> properties) throws IOException {
    final StringBuilder builder = new StringBuilder();
    for (Map.Entry<String, String> entry : properties.entrySet()) {
        builder.append(entry.getKey()).append('=').append(entry.getValue()).append('\n');
    }
    Files.write(yarnPropertiesFile().toPath(), builder.toString().getBytes(StandardCharsets.UTF_8));
}
